function cpcObligationsCard(priorMonth,priorLabel,nextLabel){
  const T=cpcTheme();
  // v326: fixes a real gap Nikhil hit directly — four of five brands' sales data failed to load
  // this session (confirmed from his console log: only 6 brand×aggregator combos logged, all
  // Wicked Wings, when a healthy session logs 31 across all five brands), which silently
  // collapsed every GMV/mandate figure on this exact page to a fraction of the real number
  // (AED 8.3K "Projected GMV" for Noon vs the real ~200K+ scale) with nothing on screen
  // indicating data was missing. The recovery mechanism (retryBrand) already existed and
  // worked correctly, but the only visible retry button lived on one Overview card — invisible
  // from here, so there was no way to notice or fix this from the Investment Plan itself. This
  // is a load-time network failure (all three CORS fallback sources failing for a brand), not a
  // data or logic bug — the GMV/mandate math itself is correct once the real data is present.
  const failedBrands=Object.keys(window.failedBrandGids||{});
  const failedWarning=failedBrands.length?`<div style="background:rgba(239,68,68,.1);border:1px solid rgba(239,68,68,.4);border-radius:10px;padding:12px 16px;margin-bottom:14px;display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap">
    <div><div style="font-size:13px;font-weight:800;color:#EF4444">⚠ ${failedBrands.length} brand${failedBrands.length===1?"":"s"} failed to load — every number below is understated</div><div style="font-size:11px;color:${T.label};margin-top:2px">${failedBrands.join(", ")} ${failedBrands.length===1?"has":"have"} no sales data this session (a network/proxy issue, not a data problem) — GMV and mandate figures on this page only reflect the brands that DID load.</div></div>
    <div style="display:flex;gap:6px">${failedBrands.map(b=>`<button id="retry-brand-${b.replace(/\s+/g,'-')}" onclick="retryBrand('${b}')" style="background:#EF4444;color:#fff;border:none;border-radius:6px;padding:7px 12px;font-size:11px;font-weight:700;cursor:pointer">Retry ${b}</button>`).join("")}</div>
  </div>`:"";
  const AGG_CARD_CLR={Deliveroo:"#00CCBC",Talabat:"#FF6000",Careem:"#3DDC73",Noon:"#F5CF00"};
  const aggs=["Deliveroo","Talabat","Careem","Noon"];
  const cards=aggs.map(ag=>{
    const gmvInfo=cpcProjectedGroupGMV(priorMonth,ag);
    const gmv=gmvInfo.value;
    const mand=cpcMandatoryBudget(ag,gmv);
    const pct=ag==="Deliveroo"?"2%":ag==="Talabat"?null:"4%";
    const type=ag==="Deliveroo"||ag==="Talabat"?"Per outlet":"Brand pool";
    const clr=AGG_CARD_CLR[ag];
    const statusChip=ag==="Talabat"&&!TALABAT_DEAL_SIGNED
      ?`<span style="color:#D97706;font-size:11px;font-weight:700">⚠ Deal pending</span>`
      :`<span style="color:#16A34A;font-size:11px;font-weight:700">✓ Active</span>`;
    // v147: whenever the reference month is still in progress, the GMV feeding this obligation
    // is a PROJECTION (linear day-count), not a closed-book actual — labeled explicitly so a
    // projected figure is never mistaken for a final one.
    const gmvLabel=gmvInfo.projected
      ?`<span title="Projected from ${fmtAEDExact(gmvInfo.rawSoFar)} through day ${gmvInfo.daysElapsed} of ${gmvInfo.daysInMonth}">Projected ${priorLabel.split(' ')[0]} GMV ⓘ</span>`
      :`${priorLabel.split(' ')[0]} GMV (final)`;
    return`<div onclick="cpcInvPlanGoBrands('${ag}')" style="cursor:pointer;background:${T.panelBg};border:1px solid ${T.border};border-left:4px solid ${clr};border-radius:12px;padding:16px;box-shadow:0 1px 3px rgba(15,23,42,.05);transition:transform .15s" onmouseover="this.style.transform='translateY(-2px)'" onmouseout="this.style.transform='none'">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">
        <div style="font-size:15px;font-weight:800;color:${T.text}">${ag}</div>
        ${statusChip}
      </div>
      <div style="font-size:10px;color:${T.label};font-weight:700;text-transform:uppercase;letter-spacing:.5px;margin-bottom:2px;cursor:${gmvInfo.projected?'help':'default'}">Mandatory budget${pct?" · "+pct+" of "+gmvLabel:""}</div>
      <div style="font-size:24px;font-weight:800;color:#D97706;margin-bottom:10px">${mand?fmtAEDTip(mand):"—"}</div>
      <div style="display:flex;justify-content:space-between;font-size:11px;color:${T.muted};border-top:1px dashed ${T.border};padding-top:8px">
        <span>${gmvInfo.projected?"Projected":priorLabel.split(' ')[0]} GMV: <strong style="color:${T.text}">${fmtAEDTip(gmv)}</strong></span>
        <span>${type}</span>
      </div>
      <div style="margin-top:10px;font-size:11px;color:${clr};font-weight:700">View brands →</div>
    </div>`;
  }).join("");
  const totalMand=aggs.reduce((s,ag)=>s+cpcMandatoryBudget(ag,cpcProjectedGroupGMV(priorMonth,ag).value),0);
  const anyProjected=aggs.some(ag=>cpcProjectedGroupGMV(priorMonth,ag).projected);
  return`<div class="card" style="border:1px solid rgba(245,158,11,.3);background:${_darkPage?`linear-gradient(135deg,rgba(245,158,11,.08),${DARK_THEME.card})`:'linear-gradient(135deg,rgba(245,158,11,.04),rgba(255,255,255,.5))'}">
    ${failedWarning}
    <div style="margin-bottom:14px"><div style="font-size:13px;font-weight:800;color:#fbbf24;letter-spacing:.3px">${nextLabel.toUpperCase()} INVESTMENT PLAN</div><div style="font-size:10.5px;color:${T.label};margin-top:2px">based on ${priorLabel} data${anyProjected?" (in progress — projected to month-end)":" (final)"} · always available · recalculates as new data arrives</div></div>
    <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:12px">${cards}</div>
    <div style="background:${T.rowBg};border:1px solid ${T.border};border-radius:10px;padding:12px 16px;display:flex;justify-content:space-between;align-items:center">
      <div style="font-size:11px;color:${T.muted};font-weight:700;text-transform:uppercase;letter-spacing:.5px">Group total mandatory budget — ${nextLabel}</div>
      <div style="font-size:19px;font-weight:800;color:#16A34A">${fmtAEDTip(totalMand)}</div>
    </div>
    <div style="margin-top:10px;padding:9px 12px;background:rgba(96,165,250,.06);border-left:3px solid #60A5FA;border-radius:4px;font-size:11px;color:${T.secondary};line-height:1.55">💡 <strong>Group-level obligations.</strong> The 2%/4% applies to total group GMV per aggregator — not per brand. Underperforming brands' shares get redirected to higher-ROAS combos in the per-outlet tables below.</div>
  </div>`;
}

// Deliveroo per-outlet allocation table. Key feature: bid recommendations leveraged from
// cpcDeliverooBidOpt (Deliveroo is the only aggregator where bid is in our control).
// Reconciles bottom-up recommendations to the top-down 2% mandate by redistributing any gap
// to the best-performing outlets (weighted by ROAS upside).
// v319: trend-aware verdicts + trim-priority, per Nikhil's direct feedback — Fyoozhen DIP got
// trimmed in September planning despite being Deliveroo's genuinely strong performer for the
// brand, because the trim logic only ever looked at instantaneous ROAS level, never whether that
// performance was climbing or declining. DIP's own Jul→Aug numbers (verified against the real
// sheet) show ROAS dropping 5.50×→3.99× and CTO dropping 15.3%→11.6% in the same window — a real
// warning sign the old model had no way to see, since it only compared ROAS against a static
// break-even threshold with no memory of direction.
//
// cpcTrendSignal() computes month-over-month movement in ROAS and CTO for one outlet, using
// cpcRowForMonth (already fixed to correctly SUM multiple real campaigns sharing a month, per
// the Motorcity fix) for both the current and prior month's data — same trustworthy source the
// rest of the page already relies on. Returns null when there's not enough real data to compare
// (fewer than two comparable months, or either month has zero real spend) rather than guessing
// at a trend from noise. Correlation testing across 48 real outlets with 4+ months of history
// showed spend-vs-ROAS is often weakly negative or inconsistent — not reliable enough to build a
// precise marginal-ROI estimate — so this deliberately stays a simple, honest DIRECTION signal
// (up/flat/down) rather than a fabricated-precision number.
function cpcTrendSignal(brand,ag,outlet,curMonth,adType){
  adType=adType||"CPC";
  const prevMonth=monthBefore(curMonth);
  const cur=cpcRowForMonth(brand,ag,outlet,adType,curMonth);
  const prev=cpcRowForMonth(brand,ag,outlet,adType,prevMonth);
  if(!cur||!prev||!(cur.budgetSpent>0)||!(prev.budgetSpent>0))return null;
  const curROAS=cur.sales>0?cur.sales/cur.budgetSpent:0;
  const prevROAS=prev.sales>0?prev.sales/prev.budgetSpent:0;
  const roasDeltaPct=prevROAS>0?((curROAS-prevROAS)/prevROAS)*100:null;
  const curCTO=cur.cto,prevCTO=prev.cto;
  const ctoDeltaPts=(curCTO!=null&&prevCTO!=null)?curCTO-prevCTO:null;
  // Direction: ROAS is the primary signal (it's what verdicts and budget already key off of);
  // CTO corroborates rather than overrides — an outlet can have a flat ROAS but declining CTO
  // (early saturation warning) without being called "declining" outright on ROAS alone.
  let direction="flat";
  if(roasDeltaPct!=null){
    if(roasDeltaPct<=-10)direction="declining";
    else if(roasDeltaPct>=10)direction="improving";
  }
  return{direction,roasDeltaPct,ctoDeltaPts,curROAS,prevROAS,curCTO,prevCTO};
}
// v327: separate organic-sales-trend signal, per Nikhil's direct question — an outlet's CPC
// verdict (cpcPlanVerdict) only ever measures whether THAT SPECIFIC ad spend is efficient
// (CPC-attributed sales ÷ CPC spend), and has zero visibility into the outlet's real overall
// sales trend. Nikhil caught a genuine case: an outlet showing FLOOR on CPC while its total
// Deliveroo sales were actually climbing — those are two different, real questions that can
// legitimately disagree (organic growth carrying an outlet despite weak ad performance; or ad
// performance being under-measured; or the outlet genuinely doing well independent of ads).
// Deliberately built as a SEPARATE, purely informational signal — not folded into the verdict
// itself, per his explicit choice — since collapsing the two into one number would hide which
// of those real scenarios is actually happening. Uses allData directly (the same real sales
// source powering every other trend figure on this dashboard), completely independent of any
// CPC/ad-spend data.
function cpcOutletSalesTrend(brand,ag,outlet,curMonth){
  const prevMonth=monthBefore(curMonth);
  const curRecs=allData.filter(r=>r.brand===brand&&r.aggregator===ag&&r.branch===outlet&&recMonth(r)===curMonth);
  const prevRecs=allData.filter(r=>r.brand===brand&&r.aggregator===ag&&r.branch===outlet&&recMonth(r)===prevMonth);
  if(!curRecs.length||!prevRecs.length)return null;
  const curSales=curRecs.reduce((s,r)=>s+(r.sales||0),0);
  const prevSales=prevRecs.reduce((s,r)=>s+(r.sales||0),0);
  const curOrders=curRecs.reduce((s,r)=>s+(r.orders||0),0);
  const prevOrders=prevRecs.reduce((s,r)=>s+(r.orders||0),0);
  if(prevSales<=0)return null;
  const salesDeltaPct=((curSales-prevSales)/prevSales)*100;
  return{salesDeltaPct,curSales,prevSales,curOrders,prevOrders,direction:salesDeltaPct>=10?"up":salesDeltaPct<=-10?"down":"flat"};
}
// v328: proportional trim distribution — see the detailed comment at its call site in
// cpcDeliverooRows for the full bug this fixes. Distributes `excess` across `pool` (already
// sorted weakest-priority-first, though this function doesn't depend on that ordering) weighted
// by each outlet's trimScore, capped at `floor`. Runs iteratively: any outlet that hits its cap
// stops absorbing further cuts, and whatever it couldn't take gets redistributed across the
// remaining outlets in the next pass — so the full excess is still placed even if a few outlets
// have very little room to give, without any single outlet ever being asked to give more than
// its own floor allows.
function cpcProportionalTrim(pool,excess,floor,scoreFn){
  const trimLog=[];
  let trimmed=0;
  let active=pool.filter(r=>r.baseRec>floor); // outlets with zero room to give don't participate at all
  let remaining=excess;
  let guard=0; // safety against a pathological infinite loop — real pools are small (a few dozen outlets max)
  while(remaining>0.5&&active.length&&guard<50){
    guard++;
    // Weight = inverse of trim priority (weaker score → cut harder) — same "protect strong,
    // available takes more" direction as trimScore's own design, just applied as a proportional
    // share instead of an all-or-nothing sequential drain.
    const scores=active.map(r=>scoreFn(r));
    const minScore=Math.min(...scores);
    const weights=active.map(r=>Math.max(0.1,scoreFn(r)-minScore+0.5)); // +0.5 floor so even the weakest outlet still gets SOME weight, never zero
    const invWeights=weights.map(w=>1/w); // weaker score (lower trimScore) → smaller w → larger invWeight → cut harder
    const totalInv=invWeights.reduce((s,w)=>s+w,0);
    let placedThisPass=0;
    const stillActive=[];
    active.forEach((r,i)=>{
      const share=remaining*(invWeights[i]/totalInv);
      const capacity=Math.max(0,(r.rec??r.baseRec)-floor);
      const cut=Math.min(capacity,share);
      if(cut>0){
        r.rec=(r.rec??r.baseRec)-cut;
        trimmed+=cut;
        placedThisPass+=cut;
        const existing=trimLog.find(t=>t.r===r);
        if(existing)existing.cut+=cut;else trimLog.push({r,cut});
      }
      // Still has room left after this pass → stays active for the next redistribution round
      if(Math.max(0,(r.rec??r.baseRec)-floor)>0.5)stillActive.push(r);
    });
    remaining-=placedThisPass;
    active=stillActive;
    if(placedThisPass<0.5)break; // nothing more can be placed — every remaining outlet is at its cap
  }
  return{trimmed,trimLog};
}
function cpcDeliverooRows(priorMonth){
  const ag="Deliveroo";
  const floor=CPC_MIN_PER_OUTLET[ag];
  const combos=new Set();
  allData.filter(r=>r.aggregator===ag&&recMonth(r)===priorMonth&&r.sales>0).forEach(r=>combos.add(`${r.brand}|${r.branch}`));
  let rows=[...combos].map(k=>{
    const[brand,outlet]=k.split("|");
    const cpcRow=cpcLatestRow(brand,ag,outlet);
    const latestROAS=cpcRow&&cpcRow.budgetSpent>0?cpcRow.sales/cpcRow.budgetSpent:null;
    const verdict=cpcPlanVerdict(brand,ag,latestROAS,cpcRow?cpcRow.orders:null);
    const priorSpend=cpcRow?cpcRow.budgetSpent:0;
    const baseRec=cpcRecBudget(verdict,priorSpend,floor);
    const histTotal=cpcHistoricalSpend(brand,ag,outlet);
    const bidOpt=cpcDeliverooBidOptModel(brand,outlet)||(cpcRow?cpcDeliverooBidOpt(ag,brand,outlet,cpcRow):null);
    const trend=cpcTrendSignal(brand,ag,outlet,priorMonth);
    const salesTrend=cpcOutletSalesTrend(brand,ag,outlet,priorMonth);
    return{brand,outlet,latestROAS,verdict,priorSpend,baseRec,rec:baseRec,surplusAlloc:0,histTotal,bidOpt,cpcRow,trend,salesTrend};
  }).sort((a,b)=>{
    if(a.brand!==b.brand)return a.brand.localeCompare(b.brand);
    const order={SCALE:0,INVEST:1,MONITOR:2,UNTESTED:3,FLOOR:4,EXCLUDE:5};
    return(order[a.verdict]||5)-(order[b.verdict]||5);
  });

  // ── RECONCILE BOTTOM-UP TO TOP-DOWN MANDATE ──────────────────────────────
  // The 2% × prior-month GMV is non-negotiable per the Deliveroo contract. If the bottom-up
  // verdict-based recommendations sum to LESS than the mandate, distribute the surplus to the
  // best-performing outlets (weighted by ROAS upside above break-even). Always exclude FLOOR/EXCLUDE
  // outlets from receiving the surplus — they failed at break-even, more budget won't help.
  // Smokeys is also excluded per the standing structural-decline guidance.
  const contractualMandate=cpcMandatoryBudget(ag,cpcProjectedGroupGMV(priorMonth,ag).value);
  // v334: same approved-plan override already built for Careem/Noon (cpcPoolRows) — applies an
  // approved growth-opportunity plan on top of the contractual mandate for Deliveroo too, per
  // Nikhil's explicit "all aggregators should have this option" request. Reversible at any time
  // via the same plan-switcher banner.
  let mandate=contractualMandate;
  try{
    const stored=JSON.parse(localStorage.getItem(cpcGrowthOppKey(ag,priorMonth)));
    if(stored&&stored.decision&&stored.decision!=="original"&&stored.result&&stored.result.options&&stored.result.options[stored.decision]){
      mandate=contractualMandate+stored.result.options[stored.decision].amount;
    }
  }catch(e){}
  const baseTotal=rows.reduce((s,r)=>s+r.baseRec,0);
  let surplusBanner="";
  let reconciliationNote="";
  if(mandate>0&&baseTotal<mandate*0.98){ // 2% tolerance — don't redistribute trivial amounts
    const gap=mandate-baseTotal;
    // Eligible for surplus: not FLOOR, not EXCLUDE, not Smokeys, and has a positive ROAS upside vs BE
    const eligible=rows.filter(r=>r.verdict!=="FLOOR"&&r.verdict!=="EXCLUDE"&&r.brand!=="Smokeys"&&r.latestROAS!=null);
    if(eligible.length){
      // Weight = ROAS - BE, floored at 0.1 so even at-BE outlets get some share
      eligible.forEach(r=>{r.upside=Math.max(0.1,(r.latestROAS||0)-cpcPlanBE(ag,r.brand));});
      const totalUpside=eligible.reduce((s,r)=>s+r.upside,0);
      eligible.forEach(r=>{
        r.surplusAlloc=Math.round(gap*(r.upside/totalUpside));
        r.rec=r.baseRec+r.surplusAlloc;
      });
      const eligibleCount=eligible.length;
      const _cdrT=cpcTheme();
      reconciliationNote=`Base verdict-driven recommendations sum to <strong style="color:${_cdrT.secondary}">${fmtAEDTip(baseTotal)}</strong>. Mandate is <strong style="color:#16A34A">${fmtAEDTip(mandate)}</strong>. Distributing the gap across <strong>${eligibleCount}</strong> top-performing outlet${eligibleCount===1?"":"s"}, weighted by ROAS upside above break-even (Smokeys & FLOOR/EXCLUDE excluded).`;
      const reconDetailId=`reconDetail_${Math.random().toString(36).slice(2,7)}`;
      surplusBanner=`<div style="background:${_darkPage?'rgba(22,163,74,.10)':'#F0FDF4'};border:1px solid ${_darkPage?'rgba(22,163,74,.35)':'#BBF7D0'};border-left:5px solid #16A34A;border-radius:10px;padding:14px 18px;margin-bottom:12px">
        <div style="display:flex;align-items:center;justify-content:space-between;gap:16px;cursor:pointer" onclick="const el=document.getElementById('${reconDetailId}');el.style.display=el.style.display==='none'?'block':'none'">
          <div style="display:flex;align-items:center;gap:12px"><span style="font-size:20px">💡</span><div><div style="font-size:14px;font-weight:800;color:#16A34A">Topped up ${fmtAEDTip(gap)} to reach the ${fmtAEDTip(mandate)} mandate</div><div style="font-size:12px;color:${_cdrT.label};margin-top:1px">${eligibleCount} top-performing outlet${eligibleCount===1?"":"s"} — click for details</div></div></div>
          <span style="color:#16A34A;font-size:12px;font-weight:700;white-space:nowrap">Details ▾</span>
        </div>
        <div id="${reconDetailId}" style="display:none;margin-top:12px;padding-top:12px;border-top:1px dashed ${_darkPage?'rgba(22,163,74,.35)':'#BBF7D0'};font-size:12px;color:${_cdrT.secondary};line-height:1.6">${reconciliationNote}</div>
      </div>`;
    }else{
      // No eligible outlets (everything is FLOOR, EXCLUDE, or untested with no ROAS). Flag this — cant
      // hit the mandate by just topping up; needs strategic decision.
      const _cdrT2=cpcTheme();
      surplusBanner=`<div style="background:${_darkPage?'rgba(220,38,38,.10)':'#FEF2F2'};border:1px solid ${_darkPage?'rgba(220,38,38,.35)':'#FECACA'};border-left:5px solid #DC2626;border-radius:10px;padding:14px 18px;margin-bottom:12px;display:flex;align-items:center;gap:12px"><span style="font-size:20px">⚠️</span><div><div style="font-size:14px;font-weight:800;color:#DC2626">${fmtAEDTip(mandate-baseTotal)} short of the ${fmtAEDTip(mandate)} mandate</div><div style="font-size:12px;color:${_cdrT2.label};margin-top:1px">No SCALE/INVEST/MONITOR outlets with ROAS upside found — needs a strategic call (pause the mandate, run brand-level promos, or test new areas)</div></div></div>`;
    }
  }else if(mandate>0&&baseTotal>mandate*1.02){ // v149: tightened from 5% to 2% tolerance, matching the under-mandate side
    // v149: STRUCTURAL FIX per explicit instruction — recommended budget must never exceed the
    // mandate. This used to just show a warning and leave the actual trim to manual review,
    // meaning the displayed "Recommended" total could sit above the contractual 2% obligation.
    // Now trims automatically: weakest-upside MONITOR/INVEST outlets first (closest to
    // break-even gets cut before stronger performers in the same tier), respecting each
    // outlet's AED floor, SCALE always preserved — UNLESS even trimming every MONITOR/INVEST
    // outlet down to its floor still isn't enough to close the gap (SCALE alone exceeds the
    // mandate), in which case SCALE gets trimmed too, weakest-first, as a clearly-labeled last
    // resort — staying within the mandate is the hard constraint here, preserving SCALE is the
    // preference within that constraint.
    let excess=baseTotal-mandate;
    // v320: fixes a real flaw in v319's trend adjustment, found from Nikhil's Al Reef report and
    // confirmed against real data before redesigning. Al Reef genuinely improved 117% Jul→Aug
    // (1.95×→4.22× ROAS, verified against the real sheet) — a real, large improvement — but the
    // OLD multiplicative adjustment (base×0.8 for "improving") scaled proportionally with
    // Al Reef's own already-solid upside, while several of Lollorosso's OTHER outlets were
    // genuinely declining (Motorcity -42%, Al Qouz -33%, Jumeirah -31%) and got the ×1.4
    // protection multiplier — which, because it also scales with THEIR base, can swing further
    // than the gap between outlets that trend was ever meant to break ties within. Net effect:
    // trend could override a large absolute-performance difference rather than just nudge within
    // it — exactly what happened to Al Reef, cut hard despite genuinely strong August ROAS,
    // because being one of only two IMPROVING outlets concentrated all the trim pressure onto it
    // and NAS while every declining outlet got shielded regardless of how weak its own ROAS was.
    // Fixed with a FIXED, CAPPED additive nudge instead of a multiplier — declining outlets get
    // +0.3 upside-points of protection, improving outlets get -0.3, a small constant amount that
    // can only ever move an outlet a bounded distance in the ranking, never enough to flip the
    // order between outlets with a genuinely large real gap between them (like Al Reef's solid
    // 4.22× vs a weak outlet's near-break-even ROAS) — trend now breaks close ties and nudges
    // borderline cases, exactly the "priority adjustment, not an override" intent from v319's own
    // stated design, corrected to actually behave that way.
    const TREND_NUDGE=0.3;
    const trimScore=r=>{
      const base=r.latestROAS-cpcPlanBE(ag,r.brand);
      if(r.trend&&r.trend.direction==="declining")return base+TREND_NUDGE; // protect: push later in cut order
      if(r.trend&&r.trend.direction==="improving")return base-TREND_NUDGE; // more available: pull earlier
      return base;
    };
    // v328: fixes a real bug Nikhil caught with exact numbers — Al Forsan showed SCALE (3.24×
    // ROAS, real upside) but recommended budget was cut all the way to the floor (AED 90),
    // identical to several other SCALE outlets, while later outlets in the sort order (Marina,
    // Al Reef) were left completely untouched despite also needing to contribute to the trim.
    // Root cause: the OLD loop processed the sorted trim pool one outlet at a time, giving each
    // one its FULL available cut capacity before ever considering the next — sequentially
    // draining outlets to their floor one by one, rather than distributing the required cut
    // across the whole pool. Reproduced this exact pattern with a simulation before fixing:
    // confirmed it produces precisely "first few outlets drop to floor, next one partially cut,
    // rest untouched" — matching the screenshot precisely. Fixed with cpcProportionalTrim():
    // distributes the excess proportionally by trim priority across the WHOLE eligible pool at
    // once, capping each outlet at its own floor, and iteratively redistributing any leftover
    // from outlets that hit their cap early — so a shortfall spreads fairly across every outlet
    // with real upside, weakest-priority outlets absorbing proportionally more, but never
    // fully draining one before another is even touched.
    const trimPool=rows.filter(r=>(r.verdict==="MONITOR"||r.verdict==="INVEST")&&r.latestROAS!=null)
      .sort((a,b)=>trimScore(a)-trimScore(b));
    // eslint-note: trimmed uses `let` deliberately — the SCALE fallback branch below adds to it
    // via += when MONITOR/INVEST alone can't close the gap. trimLog stays const since it's only
    // ever pushed to (mutating contents), never reassigned.
    const trimResult=cpcProportionalTrim(trimPool,excess,floor,trimScore);
    let trimmed=trimResult.trimmed;
    const trimLog=trimResult.trimLog;
    excess-=trimmed;
    let forcedScaleNote="";
    if(excess>1){ // MONITOR/INVEST alone couldn't close the gap — SCALE alone exceeds the mandate
      const scalePool=rows.filter(r=>r.verdict==="SCALE"&&r.latestROAS!=null)
        .sort((a,b)=>trimScore(a)-trimScore(b));
      const{trimmed:scaleTrimmed,trimLog:scaleTrimLog}=cpcProportionalTrim(scalePool,excess,floor,trimScore);
      trimmed+=scaleTrimmed;excess-=scaleTrimmed;trimLog.push(...scaleTrimLog);
      if(trimLog.some(t=>t.r.verdict==="SCALE")){
        forcedScaleNote=` SCALE outlets' own base recommendations exceeded the mandate on their own — trimmed proportionally across weakest-SCALE-first (adjusted for trend — declining outlets protected, improving outlets prioritized for the cut) as a last resort since staying within the mandate takes priority.`;
      }
    }
    const newTotal=rows.reduce((s,r)=>s+r.rec,0);
    const trimDetailId=`trimDetail_${Math.random().toString(36).slice(2,7)}`;
    const _cdrT3=cpcTheme();
    surplusBanner=`<div style="background:${_darkPage?'rgba(217,119,6,.10)':'#FFFBEB'};border:1px solid ${_darkPage?'rgba(217,119,6,.35)':'#FDE68A'};border-left:5px solid #D97706;border-radius:10px;padding:14px 18px;margin-bottom:12px">
      <div style="display:flex;align-items:center;justify-content:space-between;gap:16px;cursor:pointer" onclick="const el=document.getElementById('${trimDetailId}');el.style.display=el.style.display==='none'?'block':'none'">
        <div style="display:flex;align-items:center;gap:12px"><span style="font-size:20px">✂️</span><div><div style="font-size:14px;font-weight:800;color:#D97706">Trimmed ${fmtAEDTip(trimmed)} to fit the ${fmtAEDTip(mandate)} mandate</div><div style="font-size:12px;color:${_cdrT3.label};margin-top:1px">${trimLog.length} outlet${trimLog.length===1?"":"s"} adjusted — click for details</div></div></div>
        <span style="color:#D97706;font-size:12px;font-weight:700;white-space:nowrap">Details ▾</span>
      </div>
      <div id="${trimDetailId}" style="display:none;margin-top:12px;padding-top:12px;border-top:1px dashed ${_darkPage?'rgba(217,119,6,.35)':'#FDE68A'};font-size:12px;color:${_cdrT3.secondary};line-height:1.6">
        Base recommendations summed to ${fmtAEDTip(baseTotal)}, exceeding the 2% mandate (${fmtAEDTip(mandate)}) by ${fmtAEDTip(baseTotal-mandate)}. Weakest ROAS-upside outlets within MONITOR/INVEST were cut first, down to the AED ${floor}/outlet floor, with SCALE outlets preserved.${forcedScaleNote} Recommended total is now ${fmtAEDTip(newTotal)}.
      </div>
    </div>`;
  }
  return{rows,mandate,floor,surplusBanner,ag};
}

// v318: verdict glossary, requested directly alongside the FLOOR rename — explains what each
// term means in plain language, since "FLOOR" and "EXCLUDE" (and the existing SCALE/INVEST/
// MONITOR/UNTESTED) are load-bearing recommendations, not self-explanatory labels. Shared across
// every allocation table (Deliveroo, Talabat, Careem/Noon pooled) so the terminology and its
// explanation never drift apart between tables.
function cpcVerdictGlossary(){
  const T=cpcTheme();
  const verdClr={SCALE:"#22C55E",INVEST:"#86EFAC",MONITOR:"#FBBF24",FLOOR:"#EF4444",EXCLUDE:"#94A3B8",UNTESTED:T.label};
  const terms=[
    {v:"SCALE",d:"Strong ROAS, well above break-even. Recommended budget increases from last month — this listing earns more the more it gets."},
    {v:"INVEST",d:"Good ROAS above break-even, room to grow. Recommended budget increases, more conservatively than SCALE."},
    {v:"MONITOR",d:"Roughly matching last month's spend — performing near break-even, worth keeping an eye on rather than actively growing or cutting."},
    {v:"FLOOR",d:"Below break-even. Funded at the mandatory per-listing minimum only — the least you can spend while still running the listing at all — nothing more."},
    {v:"EXCLUDE",d:"No real order activity and no measurable ROAS. Recommended budget is AED 0 — a candidate to stop running entirely, not just fund at the minimum."},
    {v:"UNTESTED",d:"No CPC data yet for this listing this month. Started at the mandatory floor so there's something to measure next month."}
  ];
  return`<div style="margin-top:14px;padding-top:14px;border-top:1px solid ${T.border}">
    <div style="font-size:11px;color:${T.label};font-weight:700;text-transform:uppercase;letter-spacing:.4px;margin-bottom:8px">Glossary</div>
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:8px 16px">
    ${terms.map(t=>`<div style="display:flex;gap:8px;align-items:flex-start"><span style="background:${verdClr[t.v]}22;color:${verdClr[t.v]};padding:2px 8px;border-radius:5px;font-size:10.5px;font-weight:800;letter-spacing:.3px;white-space:nowrap;margin-top:1px">${t.v}</span><span style="font-size:11.5px;color:${T.secondary};line-height:1.5">${t.d}</span></div>`).join("")}
    </div>
    <div style="font-size:10.5px;color:${T.label};margin-top:10px;line-height:1.5">The mandatory floor (AED ${CPC_MIN_PER_OUTLET.Deliveroo}/outlet on Deliveroo) only applies to listings you choose to keep running — it's not a requirement to invest in every listing. The 2% group GMV obligation is a total across all actively-invested listings, not a per-outlet sum, so excluding a dead listing doesn't put that obligation at risk.</div>
  </div>`;
}
function cpcDeliverooAllocCard(priorMonth,brandFilter){
  const T=cpcTheme();
  const{rows:allRows,mandate,floor,surplusBanner,ag}=cpcDeliverooRows(priorMonth);
  // v153: brandFilter (optional) scopes this card's rendering to ONE brand's outlets only —
  // used by the Investment Plan's Level 3 (brand → outlets) drill-down. The reconciliation
  // above already ran across ALL brands' outlets before this filter is applied, so the trim/
  // surplus math stays correct regardless of which single brand is being viewed.
  const rows=brandFilter?allRows.filter(r=>r.brand===brandFilter):allRows;

  const verdClr={SCALE:"#22C55E",INVEST:"#86EFAC",MONITOR:"#FBBF24",FLOOR:"#EF4444",EXCLUDE:"#94A3B8",UNTESTED:T.label};
  const verdBg={SCALE:"rgba(34,197,94,.08)",INVEST:"rgba(134,239,172,.06)",MONITOR:"rgba(251,191,36,.06)",FLOOR:"rgba(239,68,68,.06)",EXCLUDE:"rgba(100,116,139,.06)",UNTESTED:"rgba(148,163,184,.06)"};
  // v148: rows are unchanged from before — every field, every outlet, every computation
  // preserved exactly. Only the FINAL rendering changed: grouped by brand with click-to-expand,
  // instead of every outlet always shown flat.
  const brandGroups={};
  rows.forEach(r=>{(brandGroups[r.brand]=brandGroups[r.brand]||[]).push(r);});
  let gi=0;
  const nextMonthShort=cpcNextMonthLabel().split(" ")[0];
  const prevMonthForCTO=monthBefore(priorMonth);
  const tRows=Object.entries(brandGroups).map(([brand,brRows])=>{
    gi++;
    const rid=`delivRows_${gi}_${Math.random().toString(36).slice(2,7)}`;
    const bClr=BMAP[brand]?.c||"#fff";
    const vCounts={};brRows.forEach(r=>{vCounts[r.verdict]=(vCounts[r.verdict]||0)+1;});
    const vChips=Object.entries(vCounts).map(([v,n])=>`<span style="background:${verdClr[v]}22;color:${verdClr[v]};padding:2px 8px;border-radius:5px;font-size:11px;font-weight:700;margin-right:4px">${n} ${v}</span>`).join("");
    const bPrior=brRows.reduce((s,r)=>s+r.priorSpend,0),bRec=brRows.reduce((s,r)=>s+roundTo10(r.rec),0),bHist=brRows.reduce((s,r)=>s+r.histTotal,0);
    const bDelta=bRec-Math.round(bPrior);
    const bDeltaTxt=bDelta>0?`<span style="color:#22C55E">+${fmtAEDTip(bDelta)}</span>`:bDelta<0?`<span style="color:#EF4444">${fmtAEDTip(bDelta)}</span>`:`<span style="color:${T.muted}">—</span>`;
    // v316: font sizes raised throughout this table per Nikhil's readability complaint — was
    // 9.5-11.5px, now 12-13px body / 11px labels, matching the mockup he approved.
    const summaryRow=`<tr onclick="const el=document.getElementById('${rid}');const open=el.style.display!=='none';el.style.display=open?'none':'table-row-group';this.querySelector('.chev').textContent=open?'▸':'▾'" style="cursor:pointer;background:rgba(15,23,42,.02);border-bottom:1px solid ${T.border}"><td style="padding:9px 7px;width:18px;color:${T.label}" class="chev">▾</td><td style="padding:9px 7px;color:${bClr};font-weight:800;font-size:13px">${brand}</td><td style="padding:9px 7px;color:${T.muted};font-size:12px">${brRows.length} outlet${brRows.length===1?"":"s"}</td><td style="padding:9px 7px">${vChips}</td><td style="padding:9px 7px;text-align:right;color:${T.label};font-size:12px">${fmtAEDTip(bPrior)}</td><td style="padding:9px 7px;text-align:right;color:#fbbf24;font-weight:800;font-size:13px">${fmtAEDTip(bRec)}</td><td style="padding:9px 7px;text-align:right;font-size:12px">${bDeltaTxt}</td><td colspan="3"></td><td style="padding:9px 7px;text-align:right;color:${T.label};font-size:11.5px">${fmtAEDTip(bHist)}</td></tr>`;
    const detailRows=brRows.map(r=>{
      const roasTxt=r.latestROAS!=null?`<strong style="color:${r.latestROAS>=cpcPlanBE(ag,r.brand)?'#22C55E':'#EF4444'}">${r.latestROAS.toFixed(2)}×</strong>`:`<span style="color:${T.muted}">no data</span>`;
      const recRounded=roundTo10(r.rec);
      const delta=recRounded-Math.round(r.priorSpend);
      const deltaTxt=delta>0?`<span style="color:#22C55E">+${fmtAEDTip(delta)}</span>`:delta<0?`<span style="color:#EF4444">${fmtAEDTip(delta)}</span>`:`<span style="color:${T.muted}">—</span>`;
      const recCell=r.surplusAlloc>0
        ?`<div style="color:#fbbf24;font-weight:800">${fmtAEDTip(recRounded)}</div><div style="font-size:10.5px;color:#22C55E;margin-top:1px">base ${fmtAEDTip(roundTo10(r.baseRec))} + <strong>${fmtAEDTip(roundTo10(r.surplusAlloc))}</strong> redistributed</div>`
        :`<span style="color:#fbbf24;font-weight:800">${fmtAEDTip(recRounded)}</span>`;
      let bidCol="";
      if(r.bidOpt&&r.bidOpt.curBid&&r.bidOpt.direction){
        const holding=r.bidOpt.direction==="hold";
        const clr=r.bidOpt.direction==="raise"?"#22C55E":r.bidOpt.direction==="lower"?"#FBBF24":T.label;
        bidCol=`<span style="color:${T.muted};font-size:11.5px" title="Best ROAS-volume month: ${r.bidOpt.bestMonth||"?"} at ${r.bidOpt.bestRoas?r.bidOpt.bestRoas.toFixed(2)+"×":"?"} ROAS">Bid: <strong style="color:${T.secondary}">AED ${r.bidOpt.curBid.toFixed(2)}</strong> → ${holding?"hold at":""} <strong style="color:${clr}">AED ${r.bidOpt.suggestedBid.toFixed(2)}</strong> for ${nextMonthShort}${!holding?(r.bidOpt.direction==="raise"?" ↑":" ↓"):""}</span>`;
      }else if(r.bidOpt&&r.bidOpt.suggestedBid){
        bidCol=`<span style="color:${T.muted};font-size:11.5px" title="Best historical bid (no current bid to compare)">Target for ${nextMonthShort}: <strong style="color:${T.label}">AED ${r.bidOpt.suggestedBid.toFixed(2)}</strong></span>`;
      }
      const histTxt=r.histTotal>0?`<span style="color:${T.label};font-size:11.5px">${fmtAEDTip(r.histTotal)}</span>`:`<span style="color:${T.muted};font-size:11px">none</span>`;
      const momHtml=cpcMoMSnippet(r.brand,ag,r.outlet,"CPC",r.latestROAS,r.cpcRow?r.cpcRow.orders:null,priorMonth);
      // v316: two new CTO comparison columns, per Nikhil's request. augCto comes straight off
      // the already-attached current-month row (r.cpcRow); julCto needs its own lookup via the
      // same cpcRowForMonth() used elsewhere for month-specific comparisons — its fallback
      // branch was silently missing .cto until this build (fixed above), so this column would
      // have shown blanks for any row sourced from the model fallback rather than raw cpcData.
      const augCto=r.cpcRow&&r.cpcRow.cto!=null?r.cpcRow.cto:null;
      const julRow=cpcRowForMonth(r.brand,ag,r.outlet,"CPC",prevMonthForCTO);
      const julCto=julRow&&julRow.cto!=null?julRow.cto:null;
      const ctoTrendClr=(augCto!=null&&julCto!=null)?(augCto>=julCto?"#22C55E":"#EF4444"):T.muted;
      const julCtoTxt=julCto!=null?`${julCto.toFixed(1)}%`:"—";
      const augCtoTxt=augCto!=null?`${augCto.toFixed(1)}%`:"—";
      // v327: organic sales trend badge — deliberately styled distinctly from the CPC verdict
      // badge (different icon, muted-blue vs the verdict's red/green/yellow) so it reads as a
      // separate signal, never mistaken for a second opinion on the same thing. Per Nikhil's
      // explicit choice: informational only, never changes the verdict or the recommended spend.
      const salesTrendBadge=r.salesTrend?(()=>{
        const st=r.salesTrend;
        const clr=st.direction==="up"?"#60A5FA":st.direction==="down"?"#F59E0B":T.muted;
        const icon=st.direction==="up"?"📈":st.direction==="down"?"📉":"➖";
        const sign=st.salesDeltaPct>=0?"+":"";
        return ` <span title="Outlet's TOTAL Deliveroo sales trend (all orders, not just CPC-attributed) — a separate signal from the CPC verdict above, informational only" style="background:${clr}18;color:${clr};padding:2px 7px;border-radius:5px;font-size:10.5px;font-weight:700;margin-left:4px">${icon} ${sign}${st.salesDeltaPct.toFixed(0)}% overall sales</span>`;
      })():"";
      return`<tr data-sort-roas="${r.latestROAS??-999}" data-sort-prior="${r.priorSpend}" data-sort-rec="${recRounded}" data-sort-delta="${delta}" data-sort-julcto="${julCto??-999}" data-sort-augcto="${augCto??-999}" data-sort-outlet="${r.outlet}" style="background:${verdBg[r.verdict]};border-bottom:none"><td></td><td style="padding:8px 7px 2px 22px;color:${T.text};font-size:13px">↳ ${r.outlet}</td><td style="padding:8px 7px 2px;font-size:12px" colspan="2">${roasTxt} <span style="background:${verdClr[r.verdict]}22;color:${verdClr[r.verdict]};padding:2px 8px;border-radius:5px;font-size:11px;font-weight:800;letter-spacing:.3px;margin-left:5px">${r.verdict}</span>${salesTrendBadge}</td><td style="padding:8px 7px 2px;text-align:right;color:${T.label};font-size:12px">${fmtAEDTip(r.priorSpend)}</td><td style="padding:8px 7px 2px;text-align:right">${recCell}</td><td style="padding:8px 7px 2px;text-align:right;font-size:12px">${deltaTxt}</td><td style="padding:8px 7px 2px;text-align:right;color:${T.label};font-size:12px">${julCtoTxt}</td><td style="padding:8px 7px 2px;text-align:right;color:${ctoTrendClr};font-size:12px;font-weight:700">${augCtoTxt}</td><td style="padding:8px 7px 2px;text-align:right">${bidCol}</td><td style="padding:8px 7px 2px;text-align:right">${histTxt}</td></tr><tr style="background:${verdBg[r.verdict]};border-bottom:1px solid ${T.border}"><td></td><td colspan="9" style="padding:2px 7px 9px 22px">${momHtml}</td></tr>`;
    }).join("");
    return summaryRow+`<tbody id="${rid}" style="display:table-row-group">${detailRows}</tbody>`;
  }).join("");
  const totalRec=rows.reduce((s,r)=>s+r.rec,0); // exact — used for mandate-match comparison below
  const totalRecRounded=rows.reduce((s,r)=>s+roundTo10(r.rec),0); // for display — matches what's shown per outlet
  const totalPrior=rows.reduce((s,r)=>s+r.priorSpend,0);
  const totalBase=rows.reduce((s,r)=>s+r.baseRec,0);
  const lowerBidCount=rows.filter(r=>r.bidOpt&&r.bidOpt.direction==="lower").length;
  // Total-cell color: green if matching mandate within 2%, amber otherwise
  const totalMatchesMandate=mandate>0&&Math.abs(totalRec-mandate)/mandate<0.02;
  const totalClr=totalMatchesMandate?"#22C55E":(mandate>0&&totalRec<mandate?"#FBBF24":"#22C55E");
  const totalLabel=mandate>0?`<span style="font-size:10px;color:${T.muted}">vs mandate ${fmtAEDTip(mandate)}</span>`:"";
  // v150: cache the FINAL rows (post mandate-trim/surplus reconciliation) for export — guarantees
  // the exported CSV always matches exactly what's on screen, without recomputing anything.
  window._cpcExportCache=window._cpcExportCache||{};
  window._cpcExportCache.deliveroo={rows,priorMonth,mandate};
  return`<div class="card">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px"><div><div style="font-size:15px;font-weight:800;color:${AC.Deliveroo}">🛵 Deliveroo Per-Outlet Allocation</div><div style="font-size:12px;color:${T.label};margin-top:3px">Mandatory floor: AED ${floor}/outlet · 2% group GMV obligation · <strong style="color:#fbbf24">Bids are in our control</strong> — adjust to extend coverage on degrowing listings</div></div><div style="display:flex;align-items:center;gap:14px"><button onclick="cpcCheckGrowthOpportunity('Deliveroo','${priorMonth}')" style="background:transparent;color:#60A5FA;border:1px solid #60A5FA;border-radius:8px;padding:9px 16px;font-size:13px;font-weight:700;cursor:pointer">📈 Check for growth opportunities</button><button onclick="cpcExportDeliveroo()" style="background:#0F172A;color:#fff;border:none;border-radius:8px;padding:9px 16px;font-size:13px;font-weight:700;cursor:pointer">⬇ Export CSV</button><div style="text-align:right"><div style="font-size:12px;color:${T.secondary}">Total recommended: <strong style="color:${totalClr};font-size:15px">${fmtAEDTip(totalRecRounded)}</strong></div>${totalLabel?`<div style="margin-top:2px">${totalLabel}</div>`:""}</div></div></div>
    <div id="growth-opp-Deliveroo"></div>
    ${cpcActivePlanBanner("Deliveroo")}
    ${surplusBanner}
    ${lowerBidCount>0?`<div style="background:${_darkPage?"rgba(217,119,6,.12)":"#FFFBEB"};border:1px solid ${_darkPage?"rgba(217,119,6,.4)":"#FDE68A"};border-left:5px solid #D97706;border-radius:10px;padding:14px 18px;margin-bottom:16px;display:flex;align-items:center;gap:12px"><span style="font-size:20px">📉</span><div><div style="font-size:14px;font-weight:800;color:#D97706">${lowerBidCount} outlet${lowerBidCount===1?"":"s"} show bid-reduction signals</div><div style="font-size:12px;color:${T.label};margin-top:1px">Overspent vs. their best-ROAS month — lowering bids preserves budget for the full month</div></div></div>`:""}
    <div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr id="deliv-hdr-row" style="border-bottom:1px solid ${T.border};color:${T.muted};font-size:11px;text-transform:uppercase;letter-spacing:.4px"><th></th><th data-sortcol="outlet" onclick="cpcSortDelivTable(this,'outlet','string')" style="padding:8px 7px;text-align:left;cursor:pointer">Brand</th><th style="padding:8px 7px;text-align:left">Outlet</th><th data-sortcol="roas" onclick="cpcSortDelivTable(this,'roas','number')" style="padding:8px 7px;text-align:left;cursor:pointer">Latest ROAS</th><th data-sortcol="prior" onclick="cpcSortDelivTable(this,'prior','number')" style="padding:8px 7px;text-align:right;cursor:pointer">Prior Spend</th><th data-sortcol="rec" onclick="cpcSortDelivTable(this,'rec','number')" style="padding:8px 7px;text-align:right;cursor:pointer">Recommended</th><th data-sortcol="delta" onclick="cpcSortDelivTable(this,'delta','number')" style="padding:8px 7px;text-align:right;cursor:pointer">Δ vs Prior</th><th data-sortcol="julcto" onclick="cpcSortDelivTable(this,'julcto','number')" style="padding:8px 7px;text-align:right;cursor:pointer" title="July click-to-order rate — orders ÷ menu views">Jul CTO</th><th data-sortcol="augcto" onclick="cpcSortDelivTable(this,'augcto','number')" style="padding:8px 7px;text-align:right;cursor:pointer" title="August click-to-order rate — orders ÷ menu views">Aug CTO</th><th style="padding:8px 7px;text-align:right" title="Bid suggestion based on best historical ROAS-volume month">Bid Suggest</th><th style="padding:8px 7px;text-align:right">All-Time Spend</th></tr></thead>${tRows}<tfoot><tr style="border-top:2px solid ${T.border}"><td colspan="6" style="padding:9px 7px;color:${T.label};font-size:12px;font-weight:700">${rows.length} OUTLETS · base ${fmtAEDTip(roundTo10(totalBase))}${totalRecRounded!==roundTo10(totalBase)?` + ${fmtAEDTip(totalRecRounded-roundTo10(totalBase))} redistributed`:""}</td><td colspan="2"></td><td colspan="2" style="padding:9px 7px;text-align:right;color:${totalClr};font-weight:800">${fmtAEDTip(totalRecRounded)}</td><td></td></tr></tfoot></table></div>
    <div style="font-size:11px;color:${T.label};margin-top:7px">Click a brand row to expand outlet-level detail. Click a column header to sort within an expanded brand.</div>
    ${cpcVerdictGlossary()}</div>`;
}
// v316: sorts an expanded brand's outlet rows in place by the clicked column, reading the
// data-sort-* attributes already embedded on each row (see cpcDeliverooAllocCard) rather than
// recomputing anything. Toggles ascending/descending on repeat clicks of the same column.
function cpcSortDelivTable(th,key,type){
  const table=th.closest("table");
  if(!table)return;
  const dir=th.dataset.sortDir==="asc"?"desc":"asc";
  table.querySelectorAll("th[data-sortcol]").forEach(h=>{delete h.dataset.sortDir;h.style.color="";});
  th.dataset.sortDir=dir;
  table.querySelectorAll("tbody").forEach(tbody=>{
    const rows=[...tbody.querySelectorAll(`tr[data-sort-${key}]`)];
    if(!rows.length)return;
    // Each data row is immediately followed by its own MoM-detail sibling row — keep them paired
    // when reordering rather than sorting the detail rows independently of their parent.
    const pairs=rows.map(r=>[r,r.nextElementSibling]);
    pairs.sort((a,b)=>{
      let av=a[0].dataset[`sort${key.charAt(0).toUpperCase()+key.slice(1)}`],bv=b[0].dataset[`sort${key.charAt(0).toUpperCase()+key.slice(1)}`];
      if(type==="number"){av=parseFloat(av);bv=parseFloat(bv);}
      const cmp=av<bv?-1:av>bv?1:0;
      return dir==="asc"?cmp:-cmp;
    });
    pairs.forEach(([row,detail])=>{tbody.appendChild(row);if(detail)tbody.appendChild(detail);});
  });
}
// v150: reads the cache populated by the last render of cpcDeliverooAllocCard — guarantees the
// export matches exactly what's on screen, including the mandate trim and MoM data.
function cpcExportDeliveroo(){
  const cache=window._cpcExportCache&&window._cpcExportCache.deliveroo;
  if(!cache){alert("No Deliveroo allocation data loaded yet.");return;}
  const{rows,priorMonth}=cache;
  const prevMonth=monthBefore(priorMonth);
  const header=["Brand","Outlet","Latest ROAS","Break-Even","Verdict","Prior Spend (AED)","Recommended (AED)","Δ vs Prior (AED)","Bid Suggestion","All-Time Spend (AED)",
    `${cpcMonthLabel(prevMonth)} ROAS`,`${cpcMonthLabel(prevMonth)} Orders`,`${cpcMonthLabel(priorMonth)} Orders`,"Orders Δ%",`${cpcMonthLabel(prevMonth)} CTO %`,`${cpcMonthLabel(priorMonth)} CTO %`];
  const csvRows=rows.map(r=>{
    const beVal=cpcPlanBE("Deliveroo",r.brand);
    const prevRow=cpcRowForMonth(r.brand,"Deliveroo",r.outlet,"CPC",prevMonth);
    const prevROAS=prevRow&&prevRow.sales>0&&prevRow.budgetSpent>0?prevRow.sales/prevRow.budgetSpent:null;
    const prevOrders=prevRow?prevRow.orders||0:null;
    const curOrders=r.cpcRow?r.cpcRow.orders:null;
    const ordersDeltaPct=(prevOrders&&curOrders!=null)?(((curOrders-prevOrders)/prevOrders)*100).toFixed(1)+"%":"";
    // v316: Jul/Aug CTO columns, matching the two new columns added to the on-screen table.
    const prevCto=prevRow&&prevRow.cto!=null?prevRow.cto.toFixed(1)+"%":"";
    const curCto=r.cpcRow&&r.cpcRow.cto!=null?r.cpcRow.cto.toFixed(1)+"%":"";
    return[r.brand,r.outlet,r.latestROAS!=null?r.latestROAS.toFixed(2):"",beVal.toFixed(2),r.verdict,r.priorSpend.toFixed(2),roundTo10(r.rec).toFixed(2),(roundTo10(r.rec)-r.priorSpend).toFixed(2),
      r.bidOpt&&r.bidOpt.suggestedBid?r.bidOpt.suggestedBid.toFixed(2):"",r.histTotal.toFixed(2),
      prevROAS!=null?prevROAS.toFixed(2):"",prevOrders??"",curOrders??"",ordersDeltaPct,prevCto,curCto];
  });
  cpcExportCSV(`deliveroo_allocation_${priorMonth}.csv`,header,csvRows);
}

// Talabat per-outlet allocation. Marked CONDITIONAL since deal hasn't been signed.
// "Tested" column references historical CPC spend — addresses Nikhil's "we have invested in
// Talabat for Lollorosso and Smokeys" concern.
// Talabat per-outlet allocation. Marked CONDITIONAL since deal hasn't been signed.
// Since Jun 2026, Talabat campaigns can run as CPC, Keywords (min AED 875/listing), or both
// simultaneously. We compute each lever's ROAS independently and recommend CPC-only,
// Keywords-only, or a combination based on which lever (or both) clears break-even.
function cpcTalabatRows(priorMonth){
  const ag="Talabat";
  const floor=CPC_MIN_PER_OUTLET[ag];
  const kwFloor=CPC_MIN_KEYWORDS_PER_LISTING;
  const combos=new Set();
  allData.filter(r=>r.aggregator===ag&&recMonth(r)===priorMonth&&r.sales>0).forEach(r=>combos.add(`${r.brand}|${r.branch}`));
  if(!combos.size)return{rows:[],noData:true,floor:CPC_MIN_PER_OUTLET[ag],kwFloor:CPC_MIN_KEYWORDS_PER_LISTING,ag};
  const rows=[...combos].map(k=>{
    const[brand,outlet]=k.split("|");
    const cpcRow=cpcLatestRow(brand,ag,outlet); // adType="CPC" specifically
    const kwRow=cpcLatestRowByType(brand,ag,outlet,"Keywords");
    const cpcROAS=cpcRow&&cpcRow.budgetSpent>0?cpcRow.sales/cpcRow.budgetSpent:null;
    const kwROAS=kwRow&&kwRow.budgetSpent>0?kwRow.sales/kwRow.budgetSpent:null;
    const beVal=cpcPlanBE(ag,brand);
    const cpcVerdict=cpcPlanVerdict(brand,ag,cpcROAS,cpcRow?cpcRow.orders:null);
    const kwVerdict=cpcPlanVerdict(brand,ag,kwROAS,kwRow?kwRow.orders:null);
    const cpcPriorSpend=cpcRow?cpcRow.budgetSpent:0;
    const kwPriorSpend=kwRow?kwRow.budgetSpent:0;
    const cpcRec=TALABAT_DEAL_SIGNED?cpcRecBudget(cpcVerdict,cpcPriorSpend,floor):0;
    const kwRec=TALABAT_DEAL_SIGNED&&kwROAS!=null&&kwROAS>=beVal?Math.max(kwFloor,Math.round(kwPriorSpend*1.1)):0;
    const histTotal=cpcHistoricalSpend(brand,ag,outlet); // CPC-only, for "tested" flag
    const kwHistTotal=cpcHistoricalSpend(brand,ag,outlet,"Keywords");
    const tested=cpcEverTested(brand,ag,outlet);
    const kwTested=kwHistTotal>0;
    // Recommendation lever: CPC-only / Keywords-only / Both / Neither (pause)
    let lever="—",leverColor=cpcTheme().label;
    const cpcGood=cpcROAS!=null&&cpcROAS>=beVal;
    const kwGood=kwROAS!=null&&kwROAS>=beVal;
    if(cpcGood&&kwGood){lever="Both — CPC + Keywords";leverColor="#22C55E";}
    else if(cpcGood&&!kwTested){lever="CPC (Keywords untested)";leverColor="#86EFAC";}
    else if(cpcGood){lever="CPC only";leverColor="#86EFAC";}
    else if(kwGood){lever="Keywords only";leverColor="#86EFAC";}
    else if(!tested&&!kwTested){lever="Test CPC first";leverColor="#FBBF24";}
    else{lever="Neither clears BE — hold";leverColor="#EF4444";}
    return{brand,outlet,cpcROAS,kwROAS,beVal,cpcVerdict,kwVerdict,cpcPriorSpend,kwPriorSpend,cpcRec,kwRec,histTotal,kwHistTotal,tested,kwTested,lever,leverColor};
  }).sort((a,b)=>{
    if(a.brand!==b.brand)return a.brand.localeCompare(b.brand);
    const order={SCALE:0,INVEST:1,MONITOR:2,UNTESTED:3,FLOOR:4,EXCLUDE:5};
    return(order[a.cpcVerdict]||5)-(order[b.cpcVerdict]||5);
  });
  return{rows,floor,kwFloor,ag,noData:false};
}

function cpcTalabatAllocCard(priorMonth,brandFilter){
  const T=cpcTheme();
  const{rows:allRows,floor,kwFloor,ag,noData}=cpcTalabatRows(priorMonth);
  if(noData)return`<div class="card" style="border:1px dashed rgba(251,191,36,.4);background:rgba(251,191,36,.04)"><div style="font-size:13px;font-weight:800;color:${AC.Talabat||'#FF5A00'}">🍔 Talabat Per-Outlet Allocation — Conditional</div><div style="color:${T.label};font-size:11px;margin-top:6px">No prior-month Talabat sales found. ${TALABAT_DEAL_SIGNED?"":"Deal not yet signed."}</div></div>`;
  // v153: brandFilter (optional) scopes rendering to one brand — used by Investment Plan Level 3.
  const rows=brandFilter?allRows.filter(r=>r.brand===brandFilter):allRows;
  const verdClr={SCALE:"#22C55E",INVEST:"#86EFAC",MONITOR:"#FBBF24",FLOOR:"#EF4444",EXCLUDE:"#94A3B8",UNTESTED:T.label};
  // v148: same restructuring as Deliveroo — rows/computation unchanged, only the final
  // rendering groups by brand with click-to-expand.
  const brandGroups={};
  rows.forEach(r=>{(brandGroups[r.brand]=brandGroups[r.brand]||[]).push(r);});
  let gi=0;
  const tRows=Object.entries(brandGroups).map(([brand,brRows])=>{
    gi++;
    const rid=`talRows_${gi}_${Math.random().toString(36).slice(2,7)}`;
    const bClr=BMAP[brand]?.c||"#fff";
    const bCPCRec=brRows.reduce((s,r)=>s+roundTo10(r.cpcRec),0),bKWRec=brRows.reduce((s,r)=>s+roundTo10(r.kwRec),0);
    const leverCounts={};brRows.forEach(r=>{leverCounts[r.lever]=(leverCounts[r.lever]||0)+1;});
    const leverSummary=Object.entries(leverCounts).map(([l,n])=>`${n}× ${l}`).join(", ");
    const summaryRow=`<tr onclick="const el=document.getElementById('${rid}');const open=el.style.display!=='none';el.style.display=open?'none':'table-row-group';this.querySelector('.chev').textContent=open?'▸':'▾'" style="cursor:pointer;background:rgba(15,23,42,.02);border-bottom:1px solid ${T.border}"><td style="padding:8px 6px;width:16px;color:${T.label}" class="chev">▾</td><td style="padding:8px 6px;color:${bClr};font-weight:800;font-size:12px">${brand}</td><td style="padding:8px 6px;color:${T.muted};font-size:11px">${brRows.length} outlet${brRows.length===1?"":"s"}</td><td colspan="2" style="padding:8px 6px;color:${T.label};font-size:10.5px">${leverSummary}</td><td style="padding:8px 6px;text-align:right">${TALABAT_DEAL_SIGNED?`<span style="color:#fbbf24;font-weight:800;font-size:11px">CPC ${fmtAEDTip(bCPCRec)}</span>${bKWRec>0?`<br/><span style="color:#86EFAC;font-weight:700;font-size:10.5px">KW ${fmtAEDTip(bKWRec)}</span>`:""}`:`<span style="color:${T.muted}">AED 0</span>`}</td></tr>`;
    const detailRows=brRows.map(r=>{
      const cpcRoasTxt=r.cpcROAS!=null?`<strong style="color:${r.cpcROAS>=r.beVal?'#22C55E':'#EF4444'}">${r.cpcROAS.toFixed(2)}×</strong>`:`<span style="color:${T.muted};font-size:10.5px">no data</span>`;
      const kwRoasTxt=r.kwROAS!=null?`<strong style="color:${r.kwROAS>=r.beVal?'#22C55E':'#EF4444'}">${r.kwROAS.toFixed(2)}×</strong>`:r.kwTested?`<span style="color:${T.muted};font-size:10.5px">no spend</span>`:`<span style="color:${T.muted};font-size:10.5px">untested</span>`;
      const recTxt=TALABAT_DEAL_SIGNED
        ?`<span style="color:#fbbf24;font-weight:700;font-size:11px">CPC ${fmtAEDTip(roundTo10(r.cpcRec))}</span>${r.kwRec>0?`<br/><span style="color:#86EFAC;font-weight:700;font-size:11px">KW ${fmtAEDTip(roundTo10(r.kwRec))}</span>`:''}`
        :`<span style="color:${T.muted}">AED 0</span>`;
      const curCPCRow=cpcLatestRowByType(r.brand,"Talabat",r.outlet,"CPC");
      const momHtml=cpcMoMSnippet(r.brand,"Talabat",r.outlet,"CPC",r.cpcROAS,curCPCRow?curCPCRow.orders:null,priorMonth);
      return`<tr style="border-bottom:none"><td></td><td style="padding:7px 6px 2px 20px;color:${T.text};font-size:11.5px">↳ ${r.outlet}</td><td style="padding:7px 6px 2px;font-size:11px">${cpcRoasTxt}</td><td style="padding:7px 6px 2px;font-size:11px">${kwRoasTxt}</td><td style="padding:7px 6px 2px;font-size:10.5px"><span style="color:${r.leverColor};font-weight:700">${r.lever}</span></td><td style="padding:7px 6px 2px;text-align:right">${recTxt}</td></tr><tr style="border-bottom:1px solid ${T.border}"><td></td><td colspan="5" style="padding:2px 6px 8px 20px">${momHtml}</td></tr>`;
    }).join("");
    return summaryRow+`<tbody id="${rid}" style="display:table-row-group">${detailRows}</tbody>`;
  }).join("");
  const totalCPCRec=rows.reduce((s,r)=>s+roundTo10(r.cpcRec),0),totalKWRec=rows.reduce((s,r)=>s+roundTo10(r.kwRec),0);
  window._cpcExportCache=window._cpcExportCache||{};
  window._cpcExportCache.talabat={rows,priorMonth};
  return`<div class="card" style="border:1px dashed rgba(255,90,0,.4);background:rgba(255,90,0,.03)">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px"><div><div style="font-size:13px;font-weight:800;color:${AC.Talabat||'#FF5A00'}">🍔 Talabat Per-Outlet Allocation — CPC + Keywords ${TALABAT_DEAL_SIGNED?"":"<span style='color:#fbbf24;font-size:10px;font-weight:700;background:rgba(251,191,36,.12);padding:2px 8px;border-radius:4px;margin-left:6px'>⚠ DEAL PENDING</span>"}</div><div style="font-size:10.5px;color:${T.label};margin-top:2px">${TALABAT_DEAL_SIGNED?`Active — AED 20K group obligation, AED ${floor}/outlet CPC floor, AED ${kwFloor}/listing Keywords floor`:`Recommendations frozen until AED 20K deal signed · Keywords lever (min AED ${kwFloor}/listing) tracked separately from CPC since Jun 2026`}</div></div><div style="display:flex;align-items:center;gap:12px"><button onclick="cpcExportTalabat()" style="background:#0F172A;color:#fff;border:none;border-radius:8px;padding:9px 16px;font-size:13px;font-weight:700;cursor:pointer">⬇ Export CSV</button>${TALABAT_DEAL_SIGNED?`<div style="text-align:right;font-size:11px;color:${T.secondary}">CPC: <strong style="color:#fbbf24">${fmtAEDTip(totalCPCRec)}</strong> · Keywords: <strong style="color:#86EFAC">${fmtAEDTip(totalKWRec)}</strong></div>`:""}</div></div>
    <div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:11.5px"><thead><tr style="border-bottom:1px solid ${T.border};color:${T.muted};font-size:10px;text-transform:uppercase;letter-spacing:.4px"><th></th><th style="padding:6px;text-align:left">Brand</th><th style="padding:6px;text-align:left">Outlet</th><th style="padding:6px;text-align:left">CPC ROAS</th><th style="padding:6px;text-align:left">Keywords ROAS</th><th style="padding:6px;text-align:left">Break-Even / Lever</th><th style="padding:6px;text-align:right">Rec. Budget</th></tr></thead>${tRows}</table></div>
    <div style="font-size:10px;color:${T.label};margin-top:6px">Click a brand row to expand outlet-level detail</div></div>`;
}
// v150: reads the cache populated by the last render — matches what's on screen exactly.
function cpcExportTalabat(){
  const cache=window._cpcExportCache&&window._cpcExportCache.talabat;
  if(!cache){alert("No Talabat allocation data loaded yet.");return;}
  const{rows,priorMonth}=cache;
  const prevMonth=monthBefore(priorMonth);
  const header=["Brand","Outlet","CPC ROAS","Keywords ROAS","Break-Even","Lever","CPC Rec (AED)","Keywords Rec (AED)",
    `${cpcMonthLabel(prevMonth)} CPC ROAS`,`${cpcMonthLabel(prevMonth)} CPC Orders`,`${cpcMonthLabel(priorMonth)} CPC Orders`,"Orders Δ%"];
  const csvRows=rows.map(r=>{
    const curCPCRow=cpcLatestRowByType(r.brand,"Talabat",r.outlet,"CPC");
    const prevRow=cpcRowForMonth(r.brand,"Talabat",r.outlet,"CPC",prevMonth);
    const prevROAS=prevRow&&prevRow.sales>0&&prevRow.budgetSpent>0?prevRow.sales/prevRow.budgetSpent:null;
    const prevOrders=prevRow?prevRow.orders||0:null;
    const curOrders=curCPCRow?curCPCRow.orders:null;
    const ordersDeltaPct=(prevOrders&&curOrders!=null)?(((curOrders-prevOrders)/prevOrders)*100).toFixed(1)+"%":"";
    return[r.brand,r.outlet,r.cpcROAS!=null?r.cpcROAS.toFixed(2):"",r.kwROAS!=null?r.kwROAS.toFixed(2):"",r.beVal.toFixed(2),r.lever,
      roundTo10(r.cpcRec).toFixed(2),roundTo10(r.kwRec).toFixed(2),prevROAS!=null?prevROAS.toFixed(2):"",prevOrders??"",curOrders??"",ordersDeltaPct];
  });
  cpcExportCSV(`talabat_allocation_${priorMonth}.csv`,header,csvRows);
}

// Noon + Careem brand-pool allocation (pool not per-outlet for these). Reads from cpcModel.byAgg
// rather than raw cpcData — the model has already done the aggregator/brand-name normalization
// and accumulated current-month totals (curSpent / curSales / curInvested) at the brand level.
function cpcPoolRows(ag,priorMonth){
  const floor=CPC_MIN_PER_OUTLET[ag];
  const gmv=cpcProjectedGroupGMV(priorMonth,ag).value;
  const contractualMand=cpcMandatoryBudget(ag,gmv);
  // v325: applies an approved growth-opportunity plan on top of the contractual mandate, if one
  // is active for this aggregator+month. "original" or no stored decision falls back to the
  // plain contractual figure — approving is reversible at any time via cpcSwitchPlan, never a
  // one-way commitment.
  let mand=contractualMand;
  try{
    const stored=JSON.parse(localStorage.getItem(cpcGrowthOppKey(ag,priorMonth)));
    if(stored&&stored.decision&&stored.decision!=="original"&&stored.result&&stored.result.options&&stored.result.options[stored.decision]){
      mand=contractualMand+stored.result.options[stored.decision].amount;
    }
  }catch(e){}
  const A=(cpcModel&&cpcModel.byAgg)?cpcModel.byAgg[ag]:null;
  // Per-brand prior GMV (sales side) — keep this even when CPC model has no entries for the brand
  // so we still show a row indicating untested
  const brands=BR.filter(b=>allData.some(r=>r.aggregator===ag&&recMonth(r)===priorMonth&&r.brand===b.n&&r.sales>0));
  const rows=brands.map(b=>{
    const bGMV=allData.filter(r=>r.aggregator===ag&&recMonth(r)===priorMonth&&r.brand===b.n).reduce((s,r)=>s+(r.sales||0),0);
    const brandShare=gmv>0?bGMV/gmv:0;
    // v323: brandMand kept ONLY as informational context (what a proportional split of the group
    // mandate WOULD look like) — per Nikhil's explicit correction, the 2%/4% obligation is a
    // GROUP-LEVEL total, not a per-brand requirement. Deliveroo's own contract doesn't require
    // Oregano to hit 2% of Oregano's own GMV specifically; the group total is the only real
    // constraint, and there's no rule against concentrating it unevenly across brands. This was
    // previously used to DRIVE the recommendation (see the old brandTiles rec:roundTo10(r.brandMand)
    // at the Investment Plan summary level) — a genuine bug, not just a display quirk: a brand
    // with strong real ROAS could get a LOWER recommendation than a weak one purely because it
    // had less historical GMV share. Fixed below.
    const brandMand=mand*brandShare;
    // Pool figures from cpcModel — uses current-month accumulators if present, otherwise all-time
    const B=A&&A.brands?A.brands[b.n]:null;
    // Use current-month figures when there's any current-month activity; else fall back to all-time
    // so the table still surfaces something useful even if month rolled over and no CPC posted yet.
    const hasCurrent=B&&((B.curSpent||0)>0||(B.curInvested||0)>0);
    const poolSales=B?(hasCurrent?B.curSales:B.sales)||0:0;
    const poolSpent=B?(hasCurrent?B.curSpent:B.spent)||0:0;
    const poolAlloc=B?(hasCurrent?B.curInvested:B.invested)||0:0;
    const poolROAS=poolSpent>0?poolSales/poolSpent:null;
    const util=poolAlloc>0?poolSpent/poolAlloc*100:null;
    const poolOrders=B?(hasCurrent?B.curOrders:B.orders)||0:0;
    const verdict=cpcPlanVerdict(b.n,ag,poolROAS,poolOrders);
    const trend=cpcTrendSignal(b.n,ag,null,priorMonth); // brand-level pool has no single outlet — null outlet arg is fine, cpcRowForMonth will simply find nothing and return null, which is the correct "no trend data at this granularity" outcome
    // v323: baseRec now comes from the brand's OWN verdict + prior spend via cpcRecBudget — the
    // same bottom-up logic Deliveroo's outlets already use — NOT the GMV-proportional split.
    const baseRec=cpcRecBudget(verdict,poolSpent,floor);
    return{brand:b.n,bGMV,brandShare,brandMand,poolSpent,poolAlloc,poolROAS,util,verdict,hasCurrent,hasAnyHistory:!!B,baseRec,rec:baseRec,trend};
  });
  // ── GROUP-LEVEL RECONCILIATION — the only hard constraint, checked at the end ──────────────
  // v323: if the bottom-up total (every brand's own real recommendation, summed) falls short of
  // the group mandate, distribute the shortfall — per Nikhil's explicit instruction: "mix of 1
  // and 2" — proportionally among brands that ALREADY show real INVEST/SCALE signal (not brands
  // sitting at FLOOR/EXCLUDE/UNTESTED, which have no case for MORE budget just to plug a gap),
  // further weighted toward brands with an improving trend. This deliberately does NOT
  // concentrate everything into the single strongest-ROAS brand — Nikhil was explicit that
  // brands earlier in their growth curve still need support, not to be starved in favor of
  // whichever brand currently tests best.
  const bottomUpTotal=rows.reduce((s,r)=>s+r.baseRec,0);
  let groupShortfall=mand-bottomUpTotal;
  if(groupShortfall>1){
    const growthPool=rows.filter(r=>r.verdict==="INVEST"||r.verdict==="SCALE");
    if(growthPool.length){
      const weight=r=>{
        const w=r.poolROAS!=null?Math.max(0.1,r.poolROAS-cpcPlanBE(ag,r.brand)):0.1;
        return(r.trend&&r.trend.direction==="improving")?w*1.15:w; // small nudge, not a dominant factor — matches the same "nudge, don't override" principle as the trim-priority fix
      };
      const totalWeight=growthPool.reduce((s,r)=>s+weight(r),0);
      if(totalWeight>0){
        growthPool.forEach(r=>{
          const share=weight(r)/totalWeight;
          r.rec=r.baseRec+Math.round(groupShortfall*share);
        });
      }
    }
    // If NO brand shows INVEST/SCALE at all (everything is FLOOR/EXCLUDE/UNTESTED), the
    // shortfall genuinely can't be responsibly placed anywhere — surfaced as groupUnplaceable
    // for the UI to show honestly rather than forcing it onto a brand with no real case for it.
  }else if(groupShortfall<-1){
    // v324: fixes a real gap Nikhil caught with exact numbers — Noon's brands summed to AED
    // 19,200 against a AED 12,400 mandate (55% over), because this branch never existed: the
    // shortfall path above only ever ADDED up to the mandate, nothing brought brands back DOWN
    // when their own real verdicts already exceed it on their own. Per Nikhil's explicit
    // instruction, no brand's total should go above its share of the mandate right now — that's
    // deliberately deferred to the growth-opportunity approve/deny feature being designed
    // separately, not decided implicitly here. Trims proportionally back to the mandate, weakest
    // real upside first — same trimScore-style priority already used for Deliveroo's mandate
    // reconciliation, so a brand barely at FLOOR isn't cut before a strongly-scaling one.
    const surplus=-groupShortfall;
    const trimPool=[...rows].filter(r=>r.baseRec>floor).sort((a,b)=>{
      const scoreOf=r=>{
        const base=r.poolROAS!=null?r.poolROAS-cpcPlanBE(ag,r.brand):-999;
        return(r.trend&&r.trend.direction==="declining")?base+0.3:(r.trend&&r.trend.direction==="improving")?base-0.3:base;
      };
      return scoreOf(a)-scoreOf(b);
    });
    let remaining=surplus;
    for(const r of trimPool){
      if(remaining<=0)break;
      const capacity=Math.max(0,r.rec-floor);
      const cut=Math.min(capacity,remaining);
      if(cut>0){r.rec=r.rec-cut;remaining-=cut;}
    }
  }
  const finalTotal=rows.reduce((s,r)=>s+r.rec,0);
  const groupUnplaceable=Math.max(0,mand-finalTotal);
  return{rows,floor,mand,gmv,ag,A,bottomUpTotal,groupShortfall:Math.max(0,groupShortfall),groupUnplaceable};
}

// v325: growth-opportunity detection, built per Nikhil's explicit multi-part spec across several
// messages. Core principle from his own words: "getting additional budgets from Finance is quite
// hard... on paper the ROAS and sales would look good, but profitability will be low" — so ROAS
// alone is NEVER sufficient to recommend spend above the contractual mandate. Every brand must
// clear a genuine profitability check (contribution margin holding or improving, not just gross
// sales/ROAS) using the SAME computeProfitability logic the rest of the dashboard already relies
// on for real numbers — not a new, unverified profitability heuristic invented just for this
// feature.
// v334: generalized per Nikhil's explicit request — this used to call cpcPoolRows() internally,
// hardwiring it to the Careem/Noon pooled-brand model only. Now takes rows/mand/bottomUpTotal as
// parameters so the SAME safety-gated logic (profitability check, not just ROAS) works for
// Deliveroo's per-outlet rows too, not just brand-pooled ones — same trustworthy gate, applied
// at whatever granularity the caller's rows represent.
function cpcGrowthOpportunityCheck(ag,priorMonth,rows,mand,bottomUpTotal,gmv){
  if(bottomUpTotal<mand)return{eligible:false,reason:"Bottom-up total doesn't yet exceed the mandate — no surplus headroom to evaluate."};
  const prevMonth=monthBefore(priorMonth);
  const eligible=[],excluded=[];
  for(const r of rows){
    const label=r.outlet?`${r.brand} · ${r.outlet}`:r.brand;
    if(r.verdict!=="SCALE"&&r.verdict!=="INVEST"){excluded.push({brand:label,reason:`${r.verdict} verdict — no real growth signal to build a case on`});continue;}
    // Real profitability check: contribution for this brand(+outlet if given)+aggregator,
    // current month vs prior, using computeProfitability — the same function the rest of the
    // dashboard already trusts.
    const outletFilter=r.outlet?(x=>x.branch===r.outlet):(()=>true);
    const curRecords=allData.filter(x=>x.aggregator===ag&&x.brand===r.brand&&recMonth(x)===priorMonth&&outletFilter(x));
    const prevRecords=allData.filter(x=>x.aggregator===ag&&x.brand===r.brand&&recMonth(x)===prevMonth&&outletFilter(x));
    if(!curRecords.length||!prevRecords.length){excluded.push({brand:label,reason:"Not enough history to verify profitability trend — excluded rather than assumed safe."});continue;}
    const curProf=computeProfitability(curRecords,priorMonth+"-28");
    const prevProf=computeProfitability(prevRecords,prevMonth+"-28");
    const curMargin=curProf.gross>0?curProf.contribution/curProf.gross:null;
    const prevMargin=prevProf.gross>0?prevProf.contribution/prevProf.gross:null;
    if(curMargin==null||prevMargin==null){excluded.push({brand:label,reason:"Couldn't compute a reliable margin for one of the two months — excluded rather than assumed safe."});continue;}
    const marginDeltaPct=prevMargin>0?((curMargin-prevMargin)/prevMargin)*100:null;
    // The actual gate: real ROAS strength is necessary but not sufficient — contribution margin
    // must be holding (allowing a small 5% tolerance for normal noise) or improving. A brand
    // whose margin genuinely eroded — the exact "aggressive campaign, discount burn up, profit
    // down" scenario Nikhil described — gets excluded even with a strong SCALE verdict.
    if(marginDeltaPct!=null&&marginDeltaPct<-5){
      excluded.push({brand:label,reason:`Real ROAS is strong, but contribution margin fell ${Math.abs(marginDeltaPct).toFixed(0)}% ${cpcMonthLabel(prevMonth)}→${cpcMonthLabel(priorMonth)} — likely discount-driven, not something more ad spend should chase.`});
      continue;
    }
    eligible.push({...r,curMargin,prevMargin,marginDeltaPct});
  }
  return{eligible,excluded,bottomUpTotal,mand,gmv,priorMonth,prevMonth};
}
// v325: builds the two concrete spend options from cpcGrowthOpportunityCheck's eligible brands.
// Per Nikhil's explicit spec: option amounts are Claude's to propose (not user-supplied), ranked
// by outlet using BOTH real ROAS and the trend signal already built (cpcTrendSignal) — not ROAS
// alone — and projected using the account's own historical ROAS (no decay/discount factor,
// per his explicit instruction to use "our historical ROAS based math" as-is).
// v334: generalized alongside cpcGrowthOpportunityCheck — accepts the same rows/mand/
// bottomUpTotal so this works for Deliveroo's per-outlet model, not just the pooled one.
// isPerOutlet distinguishes the two real shapes: pooled rows are brand-level and need their
// real outlets derived separately (as before); Deliveroo rows already ARE outlets, so no
// further derivation step is needed or correct — using the brand-derivation path on
// already-per-outlet data would silently look up the wrong thing.
function cpcGrowthOpportunityOptions(ag,priorMonth,rows,mand,bottomUpTotal,gmv,isPerOutlet){
  const check=cpcGrowthOpportunityCheck(ag,priorMonth,rows,mand,bottomUpTotal,gmv);
  if(!check.eligible||!check.eligible.length)return{...check,options:null};
  // Conservative step: roughly a quarter of the current mandate, rounded to a clean figure.
  // Aggressive step: roughly double the conservative step. Both are proposals, not fixed rules —
  // genuinely reasonable planning increments given the mandate's own scale, not arbitrary.
  const conservativeAmt=Math.round(check.mand*0.15/100)*100;
  const aggressiveAmt=Math.round(check.mand*0.28/100)*100;
  function buildOption(totalAmt){
    // Weight each eligible row (brand for pooled, outlet for Deliveroo) by margin-strength +
    // trend, same principle already used for the shortfall redistribution — no single row's
    // growth story dominates purely because it's largest.
    const weight=r=>{
      const w=Math.max(0.1,r.curMargin!=null?r.curMargin*10:1);
      return(r.trend&&r.trend.direction==="improving")?w*1.15:w;
    };
    const totalWeight=check.eligible.reduce((s,r)=>s+weight(r),0);
    const outletRows=[];
    if(isPerOutlet){
      // Deliveroo: each eligible row already IS a real outlet — allocate directly, no
      // brand-then-outlet derivation needed.
      for(const r of check.eligible){
        const share=Math.round(totalAmt*(weight(r)/totalWeight));
        if(share<=0)continue;
        const projSales=Math.round(share*(r.latestROAS||0));
        outletRows.push({brand:r.brand,outlet:r.outlet,roas:r.latestROAS,trend:r.trend,add:share,projSales,curMargin:r.curMargin});
      }
    }else{
      const brandSplits=check.eligible.map(r=>({brand:r.brand,amt:Math.round(totalAmt*(weight(r)/totalWeight)),poolROAS:r.poolROAS,trend:r.trend}));
      // Within each brand, rank real outlets by ROAS + trend (per Nikhil's explicit instruction)
      // and allocate that brand's share top-down, largest chunk to the strongest real outlet.
      for(const bs of brandSplits){
        if(bs.amt<=0)continue;
        const outlets=[...new Set(allData.filter(rr=>rr.aggregator===ag&&rr.brand===bs.brand&&recMonth(rr)===priorMonth&&rr.branch&&rr.branch!=="(brand-level)").map(rr=>rr.branch))];
        const scored=outlets.map(outlet=>{
          const cpcRow=cpcLatestRowByType(bs.brand,ag,outlet,"CPC");
          const oROAS=cpcRow&&cpcRow.budgetSpent>0?cpcRow.sales/cpcRow.budgetSpent:null;
          const trend=cpcTrendSignal(bs.brand,ag,outlet,priorMonth);
          const score=(oROAS!=null?oROAS:0)+(trend&&trend.direction==="improving"?1:trend&&trend.direction==="declining"?-1:0);
          return{outlet,oROAS,trend,score,cpcRow};
        }).filter(o=>o.oROAS!=null).sort((a,b)=>b.score-a.score);
        if(!scored.length)continue;
        // Split this brand's share across its top real outlets, weighted by score, capped at the
        // top 3 so the split stays legible rather than smearing pennies across every outlet.
        const top=scored.slice(0,3);
        const topWeight=top.reduce((s,o)=>s+Math.max(0.1,o.score),0);
        let remaining=bs.amt;
        top.forEach((o,i)=>{
          const share=i===top.length-1?remaining:Math.round(bs.amt*(Math.max(0.1,o.score)/topWeight));
          remaining-=share;
          if(share<=0)return;
          // Historical-ROAS projection, exactly as Nikhil specified: incremental sales = extra
          // spend × this outlet's own real ROAS. No decay factor applied.
          const projSales=Math.round(share*o.oROAS);
          outletRows.push({brand:bs.brand,outlet:o.outlet,roas:o.oROAS,trend:o.trend,add:share,projSales});
        });
      }
    }
    const totalProjSales=outletRows.reduce((s,o)=>s+o.projSales,0);
    // Contribution projection: apply the relevant margin (already verified to be holding, per
    // the safety gate) to the incremental sales — not a flat assumption.
    const totalProjContrib=outletRows.reduce((s,o)=>{
      if(o.curMargin!=null)return s+o.projSales*o.curMargin; // per-outlet margin already attached (Deliveroo path)
      const br=check.eligible.find(e=>e.brand===o.brand);
      return s+(br&&br.curMargin!=null?o.projSales*br.curMargin:0);
    },0);
    return{amount:totalAmt,outletRows,totalProjSales,totalProjContrib};
  }
  return{...check,options:{conservative:buildOption(conservativeAmt),aggressive:buildOption(aggressiveAmt)}};
}
// v325: growth-opportunity UI layer — button-triggered per Nikhil's explicit instruction (points
// 3 and 4 of his spec: "it should be my choice on whether i should go look for it or not"),
// never automatic. Persisted via localStorage, same pattern already used elsewhere in this file
// (sidebar collapse, rating alerts, last-seen-version) rather than inventing new storage.
function cpcGrowthOppKey(ag,month){return `oregano_growth_opp_${ag}_${month}`;}
function cpcCheckGrowthOpportunity(ag,priorMonth){
  const container=document.getElementById(`growth-opp-${ag}`);
  if(!container)return;
  container.innerHTML=`<div style="display:flex;align-items:center;gap:8px;padding:12px 0;color:#94A3B8;font-size:12px"><div class="dot"></div>Checking real ROAS, trend, and profitability across every ${ag==="Deliveroo"?"outlet":"brand"}…</div>`;
  setTimeout(()=>{
    // v334: per Nikhil's explicit "all aggregators should have this option" — computes the
    // right row set for whichever aggregator's real model applies: Deliveroo is per-outlet
    // (cpcDeliverooRows), Careem/Noon are pooled per-brand (cpcPoolRows). Same underlying
    // safety-gated check either way, just fed the correct real data shape.
    let result;
    if(ag==="Deliveroo"){
      const{rows,mandate,floor}=cpcDeliverooRows(priorMonth);
      const bottomUpTotal=rows.reduce((s,r)=>s+r.baseRec,0);
      result=cpcGrowthOpportunityOptions(ag,priorMonth,rows,mandate,bottomUpTotal,null,true);
    }else{
      const{rows,mand,bottomUpTotal,gmv}=cpcPoolRows(ag,priorMonth);
      result=cpcGrowthOpportunityOptions(ag,priorMonth,rows,mand,bottomUpTotal,gmv,false);
    }
    // Cache the full result (not just the decision) so the comparison view can drill into
    // outlet-level detail for Original/A/B at any time, per Nikhil's explicit "drill down if
    // required" requirement — a single approved number alone wouldn't support that.
    try{localStorage.setItem(cpcGrowthOppKey(ag,priorMonth),JSON.stringify({result,checkedAt:new Date().toISOString(),decision:null}));}catch(e){}
    container.innerHTML=cpcGrowthOppHTML(ag,priorMonth,result);
  },500);
}
function cpcGrowthOppHTML(ag,priorMonth,result){
  const T=cpcTheme();
  if(!result.options){
    return `<div style="background:${T.panelBg||'rgba(148,163,184,.06)'};border:1px solid ${T.border};border-radius:10px;padding:12px 16px;margin-bottom:14px;font-size:12px;color:${T.label}">${result.reason||"No brand currently clears both the real-ROAS and profitability bar for additional investment above the mandate."}</div>`;
  }
  const excludedDetailId=`gopp-excl-${ag}-${Math.random().toString(36).slice(2,7)}`;
  // v336: fixes a real readability problem Nikhil flagged with a screenshot — every excluded
  // outlet's full reasoning was dumped inline as one unbroken paragraph, unreadable at a glance.
  // Collapsed to a one-line count with a click-to-expand detail list, same interaction pattern
  // already used for the mandate-trim "Details" toggle elsewhere on this page — consistent, and
  // doesn't introduce a new UI idiom just for this.
  const excludedNote=result.excluded&&result.excluded.length?`<div style="margin-bottom:10px">
    <div style="display:flex;align-items:center;gap:8px;cursor:pointer" onclick="const el=document.getElementById('${excludedDetailId}');el.style.display=el.style.display==='none'?'block':'none'">
      <span style="font-size:11px;color:${T.muted}">${result.excluded.length} outlet${result.excluded.length===1?"":"s"} excluded from this check</span>
      <span style="font-size:10px;color:${T.muted};font-weight:700">Details ▾</span>
    </div>
    <div id="${excludedDetailId}" style="display:none;margin-top:6px;padding:8px 10px;background:${T.panelBg||'rgba(148,163,184,.06)'};border-radius:6px;font-size:10.5px;color:${T.muted};line-height:1.7">
      ${result.excluded.map(e=>`<div style="margin-bottom:3px"><strong style="color:${T.text}">${e.brand}</strong> — ${e.reason}</div>`).join("")}
    </div>
  </div>`:"";
  const optCard=(key,opt,label,badge)=>{
    const cardId=`gopp-outlets-${ag}-${key}-${Math.random().toString(36).slice(2,7)}`;
    const rowHtml=o=>{
      const trendTxt=o.trend?(o.trend.direction==="improving"?`<span style="color:#22C55E">↑</span>`:o.trend.direction==="declining"?`<span style="color:#EF4444">↓</span>`:``):``;
      return `<div style="display:flex;justify-content:space-between;font-size:11px;color:${T.muted};margin-bottom:2px"><span>${o.brand} · ${o.outlet} ${o.roas.toFixed(2)}× ${trendTxt}</span><span style="color:${T.text}">+${fmtAEDTip(o.add)}</span></div>`;
    };
    // v336: caps the visible outlet list per card, per Nikhil's screenshot showing the same
    // density problem as the excluded-note wall of text — every eligible outlet rendered
    // unconditionally, up to 40+ rows on Deliveroo. Shows the top 6 by dollar amount (the ones
    // that actually matter for the decision) with the rest tucked behind a click-to-expand,
    // rather than a hard cutoff that silently hides real allocations.
    const sorted=[...opt.outletRows].sort((a,b)=>b.add-a.add);
    const visible=sorted.slice(0,6),rest=sorted.slice(6);
    const outletRows=visible.map(rowHtml).join("");
    const restHtml=rest.length?`<div id="${cardId}" style="display:none">${rest.map(rowHtml).join("")}</div><div onclick="const el=document.getElementById('${cardId}');const open=el.style.display!=='none';el.style.display=open?'none':'block';this.textContent=open?'+ ${rest.length} more outlet${rest.length===1?"":"s"} ▾':'Show fewer ▴'" style="font-size:10.5px;color:#60A5FA;cursor:pointer;margin-top:4px">+ ${rest.length} more outlet${rest.length===1?"":"s"} ▾</div>`:"";
    return `<div style="background:${T.panelBg||'#0F1729'};border:${badge?'2px solid #60A5FA':'1px solid '+T.border};border-radius:12px;padding:14px 16px;position:relative">
      ${badge?`<div style="position:absolute;top:-10px;left:12px;background:#60A5FA22;color:#60A5FA;font-size:10px;padding:2px 10px;border-radius:6px">Best ROI</div>`:""}
      <div style="font-size:11px;color:${T.muted};margin-top:${badge?"4px":"0"}">${label}</div>
      <div style="font-size:19px;font-weight:800;margin:4px 0">+${fmtAEDTip(opt.amount)}</div>
      <div style="font-size:11px;color:${T.muted};margin-bottom:8px">Projected sales <strong style="color:${T.text}">+${fmtAEDTip(opt.totalProjSales)}</strong> · contribution <strong style="color:#22C55E">+${fmtAEDTip(Math.round(opt.totalProjContrib))}</strong></div>
      <div style="border-top:1px dashed ${T.border};padding-top:8px;margin-top:8px">${outletRows}${restHtml}</div>
      <button onclick="cpcApproveGrowthOpp('${ag}','${priorMonth}','${key}')" style="width:100%;margin-top:10px;background:${badge?'#60A5FA':'transparent'};color:${badge?'#0F172A':T.text};border:${badge?'none':'1px solid '+T.border};border-radius:6px;padding:7px;font-size:12px;font-weight:700;cursor:pointer">Approve ${label.toLowerCase()}</button>
    </div>`;
  };
  return `<div style="background:rgba(34,197,94,.06);border:1px solid rgba(34,197,94,.3);border-radius:10px;padding:12px 16px;margin-bottom:10px">
    <div style="font-size:13px;font-weight:800;color:#22C55E">📈 ${ag} has real headroom above the mandate</div>
    <div style="font-size:11px;color:${T.label};margin-top:2px">Every eligible brand cleared both real ROAS and a profitability check — contribution margin is holding, not just gross sales.</div>
  </div>
  ${excludedNote}
  <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:10px">
    ${optCard("conservative",result.options.conservative,"Option A · conservative",false)}
    ${optCard("aggressive",result.options.aggressive,"Option B · aggressive",true)}
  </div>
  <div style="display:flex;justify-content:space-between;align-items:center;padding-top:8px;border-top:1px solid ${T.border};margin-bottom:10px"><span style="font-size:11px;color:${T.muted}">Neither fits right now?</span><button onclick="cpcDenyGrowthOpp('${ag}','${priorMonth}')" style="background:transparent;border:none;color:${T.muted};font-size:11px;text-decoration:underline;cursor:pointer">Keep the ${fmtAEDTip(result.mand)} contractual mandate</button></div>
  <div id="growth-opp-decision-${ag}"></div>`;
}
function cpcApproveGrowthOpp(ag,priorMonth,key){
  let stored;
  try{stored=JSON.parse(localStorage.getItem(cpcGrowthOppKey(ag,priorMonth)));}catch(e){}
  if(!stored)return;
  stored.decision=key;
  try{localStorage.setItem(cpcGrowthOppKey(ag,priorMonth),JSON.stringify(stored));}catch(e){}
  const T=cpcTheme();
  const opt=stored.result.options[key];
  const note=document.getElementById(`growth-opp-decision-${ag}`);
  if(note)note.innerHTML=`<div style="font-size:12px;color:${T.text};padding:10px;background:${T.panelBg||'#0F1729'};border-radius:8px;margin-top:6px">✓ Approved — plan set to ${fmtAEDTip(stored.result.mand+opt.amount)} for next month. Switch back anytime from the button below.</div>`;
  renderCPC();
}
function cpcDenyGrowthOpp(ag,priorMonth){
  let stored;
  try{stored=JSON.parse(localStorage.getItem(cpcGrowthOppKey(ag,priorMonth)));}catch(e){}
  if(!stored)return;
  stored.decision="original";
  try{localStorage.setItem(cpcGrowthOppKey(ag,priorMonth),JSON.stringify(stored));}catch(e){}
  renderCPC();
}
// v325: shows which plan (Original / Plan A / Plan B) is currently active for this aggregator's
// month, with a switcher to compare — per Nikhil's explicit follow-up: "if I want to go back to
// the original plan, how do I do that... or compare between original, plan A or plan B". Reads
// from the same cached result rather than recomputing, so the comparison is always against the
// exact numbers that were actually shown at approval time, not a fresh recalculation that could
// have silently drifted if new data arrived since.
function cpcActivePlanBanner(ag){
  const priorMonth=cpcPriorMonth();
  let stored;
  try{stored=JSON.parse(localStorage.getItem(cpcGrowthOppKey(ag,priorMonth)));}catch(e){}
  if(!stored||!stored.decision)return "";
  const T=cpcTheme();
  const activeLabel=stored.decision==="original"?"Original (contractual mandate)":stored.decision==="conservative"?"Plan A (conservative)":"Plan B (aggressive)";
  const plans=["original","conservative","aggressive"];
  const labels={original:"Original",conservative:"Plan A",aggressive:"Plan B"};
  return `<div style="background:rgba(96,165,250,.08);border:1px solid rgba(96,165,250,.3);border-radius:10px;padding:10px 16px;margin-bottom:14px;display:flex;justify-content:space-between;align-items:center">
    <div style="font-size:12px;color:${T.text}">Currently planning against: <strong style="color:#60A5FA">${activeLabel}</strong></div>
    <div style="display:flex;gap:4px">${plans.map(p=>`<button onclick="cpcSwitchPlan('${ag}','${priorMonth}','${p}')" style="padding:4px 10px;border-radius:6px;font-size:11px;font-weight:700;cursor:pointer;border:1px solid ${stored.decision===p?'#60A5FA':T.border};background:${stored.decision===p?'#60A5FA22':'transparent'};color:${stored.decision===p?'#60A5FA':T.label}">${labels[p]}</button>`).join("")}</div>
  </div>`;
}
function cpcSwitchPlan(ag,priorMonth,plan){
  let stored;
  try{stored=JSON.parse(localStorage.getItem(cpcGrowthOppKey(ag,priorMonth)));}catch(e){}
  if(!stored)return;
  stored.decision=plan;
  try{localStorage.setItem(cpcGrowthOppKey(ag,priorMonth),JSON.stringify(stored));}catch(e){}
  renderCPC();
}
function cpcPoolAllocCard(ag,priorMonth,brandFilter){
  const T=cpcTheme();
  const{rows:allRows,floor,mand,gmv,A,bottomUpTotal,groupShortfall,groupUnplaceable}=cpcPoolRows(ag,priorMonth);
  const verdClr={SCALE:"#22C55E",INVEST:"#86EFAC",MONITOR:"#FBBF24",FLOOR:"#EF4444",EXCLUDE:"#94A3B8",UNTESTED:T.label};
  // v153: brandFilter (optional) scopes rendering to one brand — used by Investment Plan Level 3.
  // Each brand's mandate share (brandMand = mand * brandShare) is already computed above using
  // the FULL group GMV, so filtering afterward doesn't change any brand's own numbers.
  const rows=brandFilter?allRows.filter(r=>r.brand===brandFilter):allRows;
  // v148: outlet-breakdown computation extracted into a per-brand helper (logic byte-for-byte
  // identical to before — same exclude-candidate threshold, same sort, same columns), so it can
  // be folded into each brand's expandable row instead of living in a separate always-visible
  // block underneath the whole table.
  function outletBreakdownFor(brand,poolSpent){
    if(!(ag==="Careem"||ag==="Noon"))return null;
    const beVal=cpcPlanBE(ag,brand);
    const outlets=[...new Set(allData.filter(rr=>rr.aggregator===ag&&rr.brand===brand&&recMonth(rr)===priorMonth&&rr.branch&&rr.branch!=="(brand-level)").map(rr=>rr.branch))];
    const outletRows=outlets.map(outlet=>{
      const cpcRow=cpcLatestRowByType(brand,ag,outlet,"CPC");
      const oROAS=cpcRow&&cpcRow.budgetSpent>0?cpcRow.sales/cpcRow.budgetSpent:null;
      const oSpent=cpcRow?cpcRow.budgetSpent:0;
      const oSales=cpcRow?cpcRow.sales:0;
      const oOrders=cpcRow?cpcRow.orders:null;
      const verdict=cpcPlanVerdict(brand,ag,oROAS,oOrders);
      const exclude=verdict==="EXCLUDE"||(oROAS!=null&&oROAS<beVal*0.8);
      const trend=cpcTrendSignal(brand,ag,outlet,priorMonth);
      const augCto=cpcRow&&cpcRow.cto!=null?cpcRow.cto:null;
      const julRow=cpcRowForMonth(brand,ag,outlet,"CPC",monthBefore(priorMonth));
      const julCto=julRow&&julRow.cto!=null?julRow.cto:null;
      const histTotal=cpcHistoricalSpend(brand,ag,outlet,"CPC");
      // v334: coverage-ranking score, per Nikhil's explicit Noon feedback — a pooled brand
      // budget (e.g. Smokeys' AED 1,500) is only actually enough to properly fund a HANDFUL of
      // outlets at the real per-listing floor (AED 1,000 on Noon), not all of them at once. Same
      // combined ROAS+trend signal already used for growth-opportunity outlet ranking, applied
      // here to rank which specific outlets are the realistic candidates to receive that budget.
      const coverageScore=(oROAS!=null?oROAS:-999)+(trend&&trend.direction==="improving"?1:trend&&trend.direction==="declining"?-1:0);
      return{outlet,oROAS,oSpent,oSales,exclude,verdict,trend,julCto,augCto,histTotal,coverageScore};
    }).sort((a,b)=>(b.oROAS||0)-(a.oROAS||0));
    if(!outletRows.length)return null;
    // v334: how many outlets the ACTUAL recommended brand-level budget can realistically fund at
    // the real per-listing floor — this is what turns "here are 15 outlets" into an honest
    // "here's the budget's real coverage, and which specific outlets should get it."
    const maxCoverage=Math.max(1,Math.floor(poolSpent/floor));
    const rankedForCoverage=[...outletRows].filter(o=>!o.exclude).sort((a,b)=>b.coverageScore-a.coverageScore);
    const recommendedOutlets=new Set(rankedForCoverage.slice(0,maxCoverage).map(o=>o.outlet));
    const excludeCount=outletRows.filter(o=>o.exclude).length;
    // v331: header relabeled "Prior Spend/Sales" to match Deliveroo's terminology exactly — both
    // tables show the same underlying month (the most recent complete/current month, used as the
    // basis for next month's plan); "This Month" vs "Prior Spend" was describing the identical
    // data with inconsistent labels, which is what looked like a real data gap in Nikhil's report
    // even though the underlying figure was already correct August data both places.
    const headerRow=`<tr style="background:rgba(15,23,42,.03)"><td></td><td data-sortcol="outlet" onclick="cpcSortDelivTable(this,'outlet','string')" style="padding:6px 7px;font-size:11px;color:${T.muted};font-weight:700;text-transform:uppercase;cursor:pointer">Outlet</td><td data-sortcol="roas" onclick="cpcSortDelivTable(this,'roas','number')" style="padding:6px 7px;font-size:11px;color:${T.muted};font-weight:700;text-transform:uppercase;cursor:pointer">ROAS</td><td data-sortcol="julcto" onclick="cpcSortDelivTable(this,'julcto','number')" style="padding:6px 7px;text-align:right;font-size:11px;color:${T.muted};font-weight:700;text-transform:uppercase;cursor:pointer">Jul CTO</td><td data-sortcol="augcto" onclick="cpcSortDelivTable(this,'augcto','number')" style="padding:6px 7px;text-align:right;font-size:11px;color:${T.muted};font-weight:700;text-transform:uppercase;cursor:pointer">Aug CTO</td><td data-sortcol="prior" onclick="cpcSortDelivTable(this,'prior','number')" style="padding:6px 7px;text-align:right;font-size:11px;color:${T.muted};font-weight:700;text-transform:uppercase;cursor:pointer">Prior Spend</td><td style="padding:6px 7px;text-align:right;font-size:11px;color:${T.muted};font-weight:700;text-transform:uppercase">Prior Sales</td><td data-sortcol="hist" onclick="cpcSortDelivTable(this,'hist','number')" style="padding:6px 7px;text-align:right;font-size:11px;color:${T.muted};font-weight:700;text-transform:uppercase;cursor:pointer">All-Time Spend</td><td colspan="2" style="padding:6px 7px;font-size:11px;color:${T.muted};font-weight:700;text-transform:uppercase">Status</td></tr>`;
    const rowsHtml=[...outletRows].sort((a,b)=>{
      const aRec=recommendedOutlets.has(a.outlet),bRec=recommendedOutlets.has(b.outlet);
      if(aRec!==bRec)return aRec?-1:1; // recommended-for-this-budget outlets float to the top
      return (b.oROAS||0)-(a.oROAS||0);
    }).map(o=>{
      const roasTxt=o.oROAS!=null?`<strong style="color:${o.oROAS>=beVal?'#22C55E':o.exclude?'#EF4444':'#FBBF24'}">${o.oROAS.toFixed(2)}×</strong>`:`<span style="color:${T.muted}">no spend</span>`;
      const trendTxt=o.trend?(o.trend.direction==="declining"?`<span style="color:#EF4444;font-size:10.5px">↓ declining</span>`:o.trend.direction==="improving"?`<span style="color:#22C55E;font-size:10.5px">↑ improving</span>`:`<span style="color:${T.muted};font-size:10.5px">flat</span>`):"";
      // v334: recommended-coverage badge, per Nikhil's explicit Noon feedback — a pooled budget
      // like AED 1,500 genuinely only funds a handful of outlets at the real floor, not all of
      // them. This makes that concrete: the specific outlets that would actually receive this
      // budget, ranked by real ROAS + trend, get a distinct green marker; the rest are still
      // shown (for context/history) but visually de-emphasized as "not funded at this budget."
      const coverageBadge=recommendedOutlets.has(o.outlet)
        ?`<span title="One of the outlets this month's actual recommended budget can realistically fund at the AED ${floor} floor" style="background:rgba(34,197,94,.15);color:#22C55E;padding:1px 6px;border-radius:4px;font-size:9.5px;font-weight:800;margin-left:6px">✓ FUNDED</span>`
        :(!o.exclude?`<span title="Real performer, but this month's budget doesn't stretch far enough to cover it at the floor" style="color:${T.muted};font-size:9.5px;margin-left:6px">· not funded this month</span>`:"");
      const tag=`<span style="background:${verdClr[o.verdict]}22;color:${verdClr[o.verdict]};padding:2px 8px;border-radius:5px;font-size:11px;font-weight:800;letter-spacing:.3px">${o.verdict}</span>${o.exclude&&o.verdict!=="EXCLUDE"?` <span style="color:#EF4444;font-size:10px">· exclude candidate</span>`:""}`;
      const julCtoTxt=o.julCto!=null?`${o.julCto.toFixed(1)}%`:"—";
      const augCtoTxt=o.augCto!=null?`${o.augCto.toFixed(1)}%`:"—";
      const ctoTrendClr=(o.augCto!=null&&o.julCto!=null)?(o.augCto>=o.julCto?"#22C55E":"#EF4444"):T.muted;
      const histTxt=o.histTotal>0?`<span style="color:${T.label};font-size:12px">${fmtAEDTip(o.histTotal)}</span>`:`<span style="color:${T.muted};font-size:11px">none</span>`;
      const cpcRow=cpcLatestRowByType(brand,ag,o.outlet,"CPC");
      const momHtml=cpcMoMSnippet(brand,ag,o.outlet,"CPC",o.oROAS,cpcRow?cpcRow.orders:null,priorMonth);
      // v334: rows for outlets NOT funded this month are visually de-emphasized (dimmed
      // background) rather than hidden — still real, verifiable data, just clearly secondary to
      // the budget's actual reach.
      const rowBg=recommendedOutlets.has(o.outlet)?"rgba(34,197,94,.04)":"transparent";
      return`<tr data-sort-outlet="${o.outlet}" data-sort-roas="${o.oROAS??-999}" data-sort-julcto="${o.julCto??-999}" data-sort-augcto="${o.augCto??-999}" data-sort-prior="${o.oSpent}" data-sort-hist="${o.histTotal}" style="border-bottom:none;background:${rowBg}"><td></td><td style="padding:7px 7px 2px 20px;color:${T.text};font-size:13px">↳ ${o.outlet} ${trendTxt}${coverageBadge}</td><td style="padding:7px 7px 2px;font-size:13px">${roasTxt}</td><td style="padding:7px 7px 2px;text-align:right;color:${T.label};font-size:12px">${julCtoTxt}</td><td style="padding:7px 7px 2px;text-align:right;color:${ctoTrendClr};font-size:12px;font-weight:700">${augCtoTxt}</td><td style="padding:7px 7px 2px;text-align:right;color:${T.label};font-size:12px">${fmtAEDTip(o.oSpent)}</td><td style="padding:7px 7px 2px;text-align:right;color:${T.label};font-size:12px">${fmtAEDTip(o.oSales)}</td><td style="padding:7px 7px 2px;text-align:right">${histTxt}</td><td colspan="2" style="padding:7px 7px 2px">${tag}</td></tr><tr style="border-bottom:1px solid ${T.border};background:${rowBg}"><td></td><td colspan="9" style="padding:2px 7px 8px 20px">${momHtml}</td></tr>`;
    }).join("");
    return{rowsHtml:headerRow+rowsHtml,count:outletRows.length,excludeCount,maxCoverage,recommendedCount:recommendedOutlets.size};
  }
  let gi=0;
  const tRows=rows.map(r=>{
    gi++;
    const beVal=cpcPlanBE(ag,r.brand);
    const roasTxt=r.poolROAS!=null?`<strong style="color:${r.poolROAS>=beVal?'#22C55E':'#EF4444'}">${r.poolROAS.toFixed(2)}×</strong>${r.hasCurrent?'':' <span style="color:#fbbf24;font-size:9.5px" title="No current-month CPC posted yet — showing all-time figures">all-time</span>'}`:r.hasAnyHistory?`<span style="color:${T.muted}">no spend</span>`:`<span style="color:${T.muted}">no data</span>`;
    const utilTxt=r.util!=null?`<span style="color:${r.util>=100?'#22C55E':r.util>=60?'#FBBF24':T.label}">${r.util.toFixed(0)}%</span>`:`<span style="color:${T.muted}">—</span>`;
    let signal="";
    if(r.util!=null){
      if(ag==="Careem"){
        if(r.util>120)signal=`<span style="color:#22C55E;font-size:10px">↑ raise budget</span>`;
        else if(r.util<40)signal=`<span style="color:#EF4444;font-size:10px">↓ cut, redirect</span>`;
        else signal=`<span style="color:${T.label};font-size:10px">maintain</span>`;
      }else if(ag==="Noon"){
        if(r.util>95)signal=`<span style="color:#22C55E;font-size:10px">↑ raise pool</span>`;
        else if(r.util<50)signal=`<span style="color:#FBBF24;font-size:10px">monitor</span>`;
        else signal=`<span style="color:${T.label};font-size:10px">maintain</span>`;
      }
    }else{
      signal=`<span style="color:${T.muted};font-size:10px">awaiting data</span>`;
    }
    const adTypeBreakdown=(()=>{
      const Blocal=A&&A.brands?A.brands[r.brand]:null;
      if(!Blocal||!Blocal.adTypes||Blocal.adTypes.size<2)return"";
      const types=[...Blocal.adTypes];
      const parts=types.map(t=>{
        const spent=cpcData.filter(rr=>rr.aggregator===ag&&rr.brand===r.brand&&rr.adType===t).reduce((s,rr)=>s+(rr.budgetSpent||0),0);
        return spent>0?`<span style="color:${T.label}">${t}: <strong style="color:${T.secondary}">${fmtAEDTip(spent)}</strong></span>`:null;
      }).filter(Boolean);
      return parts.length>1?`<div style="font-size:9.5px;margin-top:2px">${parts.join(" · ")}</div>`:"";
    })();
    const brk=outletBreakdownFor(r.brand,r.poolSpent);
    const rid=`poolRows_${gi}_${Math.random().toString(36).slice(2,7)}`;
    const chevCell=brk?`<td style="width:16px;cursor:pointer;color:${T.label}" class="chev">▾</td>`:`<td></td>`;
    const rowOnclick=brk?` onclick="const el=document.getElementById('${rid}');const open=el.style.display!=='none';el.style.display=open?'none':'table-row-group';this.querySelector('.chev').textContent=open?'▸':'▾'" style="cursor:pointer"`:'';
    const recBump=r.rec>r.baseRec?` <span style="color:#22C55E;font-size:9.5px" title="Includes a share of the group shortfall, redistributed to growing brands">+${fmtAEDTip(r.rec-r.baseRec)} growth share</span>`:"";
    const summaryRow=`<tr${rowOnclick}><td style="padding:7px 6px;color:${BMAP[r.brand]?.c||'#fff'};font-weight:700;font-size:11.5px">${r.brand}${adTypeBreakdown}</td><td style="padding:7px 6px;text-align:right;color:${T.secondary}">${fmtAEDTip(r.bGMV)}</td><td style="padding:7px 6px;text-align:right;color:${T.label};font-size:11px">${(r.brandShare*100).toFixed(0)}%</td><td style="padding:7px 6px;text-align:right;color:${T.muted};font-size:10.5px" title="What a GMV-proportional split of the group mandate would give this brand — reference only, not the recommendation">${fmtAEDTip(roundTo10(r.brandMand))}</td><td style="padding:7px 6px;text-align:right;color:#fbbf24;font-weight:700">${fmtAEDTip(roundTo10(r.rec))}${recBump}</td><td style="padding:7px 6px;font-size:11px">${roasTxt}</td><td style="padding:7px 6px"><span style="background:${verdClr[r.verdict]}22;color:${verdClr[r.verdict]};padding:2px 7px;border-radius:4px;font-size:10px;font-weight:800">${r.verdict}</span></td><td style="padding:7px 6px;text-align:center">${utilTxt}</td><td style="padding:7px 6px">${signal}</td>${chevCell}</tr>`;
    if(!brk)return`<tbody style="display:table-row-group">${summaryRow}</tbody>`;
    return summaryRow+`<tbody id="${rid}" style="display:none"><tr style="background:rgba(245,158,11,.04)"><td colspan="9" style="padding:7px 7px 7px 20px;font-size:11.5px;color:${T.label};font-weight:700">${brk.count} outlets total · <strong style="color:#22C55E">this month's budget covers ${brk.recommendedCount} of them</strong>${brk.excludeCount?` · <strong style="color:#EF4444">${brk.excludeCount} exclude candidate${brk.excludeCount===1?"":"s"}</strong>`:""} — budget is pooled at brand level; the funded outlets are ranked to the top and marked ✓ FUNDED below</td></tr>${brk.rowsHtml}</tbody>`;
  }).join("");
  const lockedNote=ag==="Careem"?` · <strong style="color:#fbbf24">Bids locked at AED 2.00</strong> — only lever is budget size`:ag==="Noon"?` · Minimum AED ${floor} to activate a brand pool`:"";
  window._cpcExportCache=window._cpcExportCache||{};
  window._cpcExportCache[ag.toLowerCase()]={rows,priorMonth,ag};
  return`<div class="card">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px"><div><div style="font-size:13px;font-weight:800;color:${AC[ag]||'#fff'}">${ag==="Noon"?"🌙":"🚕"} ${ag} Brand Pool Allocation</div><div style="font-size:10.5px;color:${T.label};margin-top:2px">4% group GMV obligation${lockedNote}</div></div><div style="display:flex;align-items:center;gap:12px"><button onclick="cpcCheckGrowthOpportunity('${ag}','${priorMonth}')" style="background:transparent;color:#60A5FA;border:1px solid #60A5FA;border-radius:8px;padding:9px 16px;font-size:13px;font-weight:700;cursor:pointer">📈 Check for growth opportunities</button><button onclick="cpcExportPool('${ag}')" style="background:#0F172A;color:#fff;border:none;border-radius:8px;padding:9px 16px;font-size:13px;font-weight:700;cursor:pointer">⬇ Export CSV</button><div style="font-size:11px;color:${T.secondary}">Group mandatory: <strong style="color:#22C55E;font-size:14px">${fmtAEDTip(mand)}</strong></div></div></div>
    <div id="growth-opp-${ag}"></div>
    ${cpcActivePlanBanner(ag)}
    <div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr style="border-bottom:1px solid ${T.border};color:${T.muted};font-size:11px;text-transform:uppercase;letter-spacing:.4px"><th style="padding:8px 7px;text-align:left">Brand</th><th style="padding:8px 7px;text-align:right">Prior GMV</th><th style="padding:8px 7px;text-align:right">Share</th><th style="padding:8px 7px;text-align:right" title="What a GMV-proportional split of the group mandate would give this brand — reference only, no brand is required to hit this">Proportional Ref.</th><th style="padding:8px 7px;text-align:right" title="This brand's own bottom-up recommendation, based on its real outlet performance — not tied to its GMV share">Recommended</th><th style="padding:8px 7px;text-align:left">Latest ROAS</th><th style="padding:8px 7px;text-align:left">Verdict</th><th style="padding:8px 7px;text-align:center">Last Util</th><th style="padding:8px 7px;text-align:left">Signal</th><th></th></tr></thead>${tRows}</table></div>
    ${bottomUpTotal!=null?`<div style="font-size:11.5px;color:${T.label};margin-top:8px">Group mandate: <strong style="color:#22C55E">${fmtAEDTip(mand)}</strong> · Bottom-up total (sum of each brand's own recommendation): <strong style="color:${T.text}">${fmtAEDTip(bottomUpTotal)}</strong>${groupShortfall>1?` · <strong style="color:#F59E0B">${fmtAEDTip(groupShortfall)} shortfall</strong> redistributed to growing brands (INVEST/SCALE) above, weighted by ROAS upside and trend`:bottomUpTotal>mand+1?` · <strong style="color:#60A5FA">${fmtAEDTip(bottomUpTotal-mand)} above mandate</strong> — real performance supports more, but recommendations are capped at the mandate for now (weakest-upside brands trimmed first); consider using the growth-opportunity check to approve investing above it`:" · already meets the group mandate on its own, no redistribution needed"}${groupUnplaceable>1?`<br><span style="color:#EF4444">⚠ ${fmtAEDTip(groupUnplaceable)} of the mandate has no brand with real INVEST/SCALE signal to place it in responsibly — consider whether the group mandate itself needs review, rather than forcing this into a brand with no real case for it.</span>`:""}</div>`:""}
    ${cpcVerdictGlossary()}
    <div style="font-size:11.5px;color:${T.label};margin-top:8px">${ag} budget is pooled at brand level — click a brand row with outlet data to see per-outlet ROAS and exclude candidates (outlets consistently &lt;80% of break-even)</div>
  </div>`;
}
// v150: reads the cache populated by the last render of cpcPoolAllocCard(ag,...) — one export
// function serves both Noon and Careem since they share the exact same data shape.
function cpcExportPool(ag){
  const cache=window._cpcExportCache&&window._cpcExportCache[ag.toLowerCase()];
  if(!cache){alert(`No ${ag} allocation data loaded yet.`);return;}
  const{rows,priorMonth}=cache;
  const prevMonth=monthBefore(priorMonth);
  const header=["Brand","Prior GMV (AED)","Share %","Proportional Reference (AED)","Recommended (AED)","Latest ROAS","Verdict","Last Util %",
    `${cpcMonthLabel(prevMonth)} ROAS (brand-level)`];
  const csvRows=rows.map(r=>{
    // Brand-level MoM proxy: compare THIS brand's pool ROAS against its OWN value the prior
    // month, sourced the same way the outlet breakdown does (per-outlet CPC rows summed isn't
    // available at brand level here, so this uses the brand's own latest-vs-prior pool figures).
    const B=(cpcModel&&cpcModel.byAgg&&cpcModel.byAgg[ag]&&cpcModel.byAgg[ag].brands)?cpcModel.byAgg[ag].brands[r.brand]:null;
    let prevROASTxt="";
    if(B&&B.rows){
      const prevRows=B.rows.filter(rr=>rr.month===prevMonth);
      const prevSpent=prevRows.reduce((s,rr)=>s+(rr.budgetSpent||0),0),prevSales=prevRows.reduce((s,rr)=>s+(rr.sales||0),0);
      if(prevSpent>0)prevROASTxt=(prevSales/prevSpent).toFixed(2);
    }
    return[r.brand,r.bGMV.toFixed(2),(r.brandShare*100).toFixed(1)+"%",roundTo10(r.brandMand).toFixed(2),roundTo10(r.rec).toFixed(2),
      r.poolROAS!=null?r.poolROAS.toFixed(2):"",r.verdict,r.util!=null?r.util.toFixed(0)+"%":"",prevROASTxt];
  });
  cpcExportCSV(`${ag.toLowerCase()}_allocation_${priorMonth}.csv`,header,csvRows);
}

function cpcDecliningOutletsCard(){
  const T=cpcTheme();
  const declining=cpcDecliningOutlets(15);
  if(!declining.length)return`<div class="card"><div style="font-size:13px;font-weight:800;color:#22C55E;margin-bottom:6px">✅ No outlets in significant MoM decline</div><div style="color:${T.label};font-size:11px">All outlets within ±15% of prior month sales.</div></div>`;
  const priorMonth=cpcPriorMonth();
  const tRows=declining.slice(0,20).map(d=>{
    const aggStrength=cpcAreaAggStrength(d.outlet,priorMonth);
    const sortedAgs=Object.entries(aggStrength).sort((a,b)=>b[1]-a[1]).slice(0,3);
    const dominant=sortedAgs[0];
    const stack=sortedAgs.map(([ag,pct])=>`<span style="color:${AC[ag]||'#fff'};font-size:10px;font-weight:700">${ag} ${pct}%</span>`).join(" · ");
    const suggestion=dominant?`Boost <strong style="color:${AC[dominant[0]]||'#fff'}">${dominant[0]}</strong> visibility — ${dominant[1]}% of orders flow through it here`:"No clear dominant aggregator";
    return`<tr style="border-bottom:1px solid ${T.border}"><td style="padding:7px 6px;color:${BMAP[d.brand]?.c||'#fff'};font-weight:700;font-size:11.5px">${d.brand}</td><td style="padding:7px 6px;color:${T.text};font-size:11.5px">${d.outlet}</td><td style="padding:7px 6px;text-align:right;color:${T.label}">${fmtAEDTip(d.prior)}</td><td style="padding:7px 6px;text-align:right;color:${T.secondary}">${fmtAEDTip(d.cur)}</td><td style="padding:7px 6px;text-align:right;color:#EF4444;font-weight:800">${d.pct.toFixed(0)}%</td><td style="padding:7px 6px;font-size:11px">${stack}</td><td style="padding:7px 6px;color:${T.secondary};font-size:11px">${suggestion}</td></tr>`;
  }).join("");
  return`<div class="card" style="border:1px solid rgba(239,68,68,.25)">
    <div style="margin-bottom:10px"><div style="font-size:13px;font-weight:800;color:#fca5a5">📉 Declining Outlets — Visibility-Boost Candidates</div><div style="font-size:10.5px;color:${T.label};margin-top:2px">MoM decline > 15% · CPC boost on the dominant aggregator may help recover visibility · funded by redirecting from FLOOR-rated outlets above</div></div>
    <div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:11.5px"><thead><tr style="border-bottom:1px solid ${T.border};color:${T.muted};font-size:10px;text-transform:uppercase;letter-spacing:.4px"><th style="padding:6px;text-align:left">Brand</th><th style="padding:6px;text-align:left">Outlet</th><th style="padding:6px;text-align:right">Prior Sales</th><th style="padding:6px;text-align:right">Current Sales</th><th style="padding:6px;text-align:right">MoM Δ</th><th style="padding:6px;text-align:left">Aggregator Mix</th><th style="padding:6px;text-align:left">Suggestion</th></tr></thead><tbody>${tRows}</tbody></table></div>
  </div>`;
}

function cpcAreaStrengthCard(priorMonth){
  const T=cpcTheme();
  // Per-outlet aggregator share across all brands
  const outlets=[...new Set(allData.filter(r=>recMonth(r)===priorMonth&&r.sales>0).map(r=>r.branch))].filter(o=>o&&o!=="(brand-level)").sort();
  const aggs=["Deliveroo","Talabat","Careem","Noon","Keeta"];
  const tRows=outlets.map(o=>{
    const strength=cpcAreaAggStrength(o,priorMonth);
    const cells=aggs.map(ag=>{
      const pct=strength[ag]||0;
      if(!pct)return`<td style="padding:6px;text-align:center;color:${T.secondary};font-size:10.5px">—</td>`;
      const bgIntensity=Math.min(pct/100,0.4);
      return`<td style="padding:6px;text-align:center;background:${AC[ag]||'#888'}${Math.round(bgIntensity*255).toString(16).padStart(2,'0')};color:${pct>=40?'#fff':'#cbd5e1'};font-weight:${pct>=30?'800':'600'};font-size:11px">${pct}%</td>`;
    }).join("");
    return`<tr style="border-bottom:1px solid ${T.border}"><td style="padding:6px 8px;color:${T.text};font-weight:600;font-size:11.5px">${o}</td>${cells}</tr>`;
  }).join("");
  const headCells=aggs.map(ag=>`<th style="padding:6px;text-align:center;color:${AC[ag]||'#fff'};font-size:10px;text-transform:uppercase;letter-spacing:.3px">${ag}</th>`).join("");
  return`<div class="card">
    <div style="margin-bottom:10px"><div style="font-size:13px;font-weight:800;color:#fbbf24">🗺️ Aggregator Strength by Outlet</div><div style="font-size:10.5px;color:${T.label};margin-top:2px">% of orders by aggregator at each outlet · informs redirect decisions — boost CPC on the dominant aggregator where ROAS supports it</div></div>
    <div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:11px"><thead><tr style="border-bottom:1px solid ${T.border}"><th style="padding:6px 8px;text-align:left;color:${T.muted};font-size:10px;text-transform:uppercase">Outlet</th>${headCells}</tr></thead><tbody>${tRows}</tbody></table></div>
  </div>`;
}

function cpcHistoricalRefCard(){
  const T=cpcTheme();
  const aggs=["Deliveroo","Talabat","Careem","Noon"];
  const tRows=BR.map(b=>{
    const cells=aggs.map(ag=>{
      const total=cpcHistoricalSpend(b.n,ag,null);
      if(total===0)return`<td style="padding:7px 8px;text-align:right;color:${T.secondary};font-size:10.5px">none</td>`;
      const months=new Set(cpcData.filter(r=>r.brand===b.n&&r.aggregator===ag&&r.adType==="CPC"&&r.budgetSpent>0).map(r=>r.month)).size;
      return`<td style="padding:7px 8px;text-align:right;color:${AC[ag]||'#fff'};font-size:11px"><strong>${fmtAEDTip(total)}</strong><br/><span style="color:${T.muted};font-size:9.5px">${months}mo active</span></td>`;
    }).join("");
    return`<tr style="border-bottom:1px solid ${T.border}"><td style="padding:7px 8px;color:${b.c};font-weight:700;font-size:11.5px">${b.n}</td>${cells}</tr>`;
  }).join("");
  const headCells=aggs.map(ag=>`<th style="padding:6px 8px;text-align:right;color:${AC[ag]||'#fff'};font-size:10px;text-transform:uppercase;letter-spacing:.3px">${ag}</th>`).join("");
  return`<div class="card">
    <div style="margin-bottom:10px"><div style="font-size:13px;font-weight:800;color:${T.label}">📜 Historical Investment Reference</div><div style="font-size:10.5px;color:${T.label};margin-top:2px">All-time CPC spend per brand × aggregator · shows tested vs untested combinations · click <strong>Drill-Down</strong> for outlet-level history</div></div>
    <div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:11.5px"><thead><tr style="border-bottom:1px solid ${T.border}"><th style="padding:6px 8px;text-align:left;color:${T.muted};font-size:10px;text-transform:uppercase">Brand</th>${headCells}</tr></thead><tbody>${tRows}</tbody></table></div>
  </div>`;
}

// ═══════════════════════════════════════════════════════════════
// END INVESTMENT PLAN MODULE
// ═══════════════════════════════════════════════════════════════

// ═══════════════════════════════════════════════════════════════
// AD INVESTMENT HISTORY MODULE
// ═══════════════════════════════════════════════════════════════
// Browsable, filterable view of every row in the CPC sheet — lets the user audit exactly which
// raw rows feed into a brand/aggregator total (e.g. verifying that separately-entered Noon line
// items grouped correctly, or that a combined-pool row didn't get double counted) without going
// back to the Google Sheet. Also doubles as "previous months" reference since cpcData holds the
// full history, not just the current month.

function cpcHistUniqueVals(field){
  return[...new Set(cpcData.map(r=>r[field]).filter(Boolean))].sort();
}
// Brand filter must only ever show real brand names. parseCPCSheet falls back to the raw,
// un-matched text as `brand` when a sheet row's Brand-Location cell doesn't contain a "-"
// separator (e.g. a row entered as just "Reem" instead of "Oregano - Al Reem") — that raw text
// would otherwise leak into this dropdown looking like a 6th "brand". Filter to BR only.
function cpcHistBrandOptions(){
  const real=new Set(BR.map(b=>b.n));
  return cpcHistUniqueVals("brand").filter(b=>real.has(b));
}
// Count of CPC rows whose brand didn't resolve to a real brand — surfaced as a small warning so
// data-quality issues in the sheet are visible instead of silently vanishing from the filter.
function cpcHistUnmappedBrandRows(){
  const real=new Set(BR.map(b=>b.n));
  return cpcData.filter(r=>r.brand&&!real.has(r.brand));
}
// Maps a raw cpcData outlet value to its canonical display form — used so the Outlet filter
// dropdown and the actual row-matching logic agree on what counts as the same outlet. Without
// this, selecting "Al Quoz" from the dropdown wouldn't match rows still tagged "AQ" in the raw
// data. Canonicalizes independent of refresh timing — works even before BRANCH_ALIASES updates
// get picked up by the next data parse.
// v244: same brand-scoping fix applied to discRecComputeRows — a global outlet list across all
// brands is unsafe when two brands share a generic name (confirmed: Oregano/Lollorosso/Smokeys
// all have plain "DIP", Fyoozhen has "DIP (Fyoozhen)"). Accepts an optional brand for a properly
// scoped resolution; falls back to the old global behavior only if no brand is available.
function cpcHistCanonicalOutlet(raw,brand){
  if(!raw)return raw;
  const pool=brand?allData.filter(r=>r.brand===brand):allData;
  const canonicalOutlets=[...new Set(pool.map(r=>r.branch).filter(b=>b&&b!=="(brand-level)"))];
  return resolveBranchName(raw,canonicalOutlets)||raw;
}

function cpcRenderHistory(){
  try{
    const T=cpcTheme();
    if(!cpcData||!cpcData.length)return`<div class="card">No CPC data loaded.</div>`;
    const months=cpcHistUniqueVals("month").sort().reverse();
    const brands=cpcHistBrandOptions();
    const aggs=cpcHistUniqueVals("aggregator").sort();
    const adTypes=cpcHistUniqueVals("adType").sort();
    // Outlets list depends on the currently selected brand (avoids showing irrelevant outlets),
    // canonicalized so abbreviations like "AQ" collapse into "Al Quoz" instead of appearing twice.
    const outletPool=cpcHistFilters.brand!=="all"?cpcData.filter(r=>r.brand===cpcHistFilters.brand):cpcData;
    const outletSeen=new Map();
    outletPool.forEach(r=>{
      if(!r.branch)return;
      const resolved=cpcHistCanonicalOutlet(r.branch,r.brand);
      const key=resolved.toLowerCase();
      if(!outletSeen.has(key))outletSeen.set(key,resolved);
    });
    const outlets=[...outletSeen.values()].sort();

    const selectHtml=(label,key,opts,curVal)=>{
      const optsHtml=['<option value="all">All</option>',...opts.map(o=>`<option value="${o}" ${curVal===o?"selected":""}>${key==='month'?cpcMonthLabel(o):o}</option>`)].join("");
      return`<div style="display:flex;flex-direction:column;gap:2px"><label style="font-size:9.5px;color:${T.muted};text-transform:uppercase;font-weight:700;font-weight:700">${label}</label><select onchange="cpcHistSetFilter('${key}',this.value)" style="background:${T.panelBg};border:1px solid ${T.border};border-radius:5px;color:${T.text};padding:5px 8px;font-size:11.5px;min-width:120px;color-scheme:${_darkPage?'dark':'light'}">${optsHtml}</select></div>`;
    };

    const compareToggleBtn=`<button onclick="cpcHistToggleCompare()" style="background:${cpcHistCompare?'rgba(245,158,11,.15)':'transparent'};border:1px solid ${cpcHistCompare?'#f59e0b':T.border};color:${cpcHistCompare?'#f59e0b':T.label};border-radius:6px;padding:6px 14px;font-size:11px;cursor:pointer;font-weight:700;white-space:nowrap">⚖️ ${cpcHistCompare?"Comparing":"Compare"}</button>`;

    // In compare mode, each side gets its own independent filter panel (built inside
    // cpcHistCompareView) — so the shared filter bar here is replaced with a slim header.
    // In table mode, the shared filter bar is the only filter UI.
    const filterBar=cpcHistCompare
      ?`<div class="card" style="padding:10px 14px;display:flex;justify-content:space-between;align-items:center"><span style="font-size:11px;color:${T.label}">Comparing two independent slices of the Ad Investment data — set each side's filters below.</span>${compareToggleBtn}</div>`
      :`<div class="card" style="padding:12px 14px">
      <div style="display:flex;gap:10px;flex-wrap:wrap;align-items:flex-end">
        ${selectHtml("Month",'month',months,cpcHistFilters.month)}
        ${selectHtml("Brand",'brand',brands,cpcHistFilters.brand)}
        ${selectHtml("Aggregator",'aggregator',aggs,cpcHistFilters.aggregator)}
        ${selectHtml("Outlet",'outlet',outlets,cpcHistFilters.outlet)}
        ${selectHtml("Ad Type",'adType',adTypes,cpcHistFilters.adType)}
        <div style="margin-left:auto">${compareToggleBtn}</div>
      </div>
    </div>`;

    // Data-quality note: rows whose Brand-Location cell didn't parse into a real brand (e.g.
    // entered as just "Reem" instead of "Oregano - Al Reem"). These are excluded from the Brand
    // filter and from all totals/comparisons — surfaced here so they don't silently vanish.
    const unmapped=cpcHistUnmappedBrandRows();
    const unmappedNote=unmapped.length?(()=>{
      const byVal={};unmapped.forEach(r=>{byVal[r.brand]=(byVal[r.brand]||0)+1;});
      const top=Object.entries(byVal).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([v,c])=>`"${v}" (${c})`).join(", ");
      return`<div class="card" style="padding:9px 14px;border-left:3px solid #FBBF24;background:rgba(251,191,36,.05)"><span style="color:#FBBF24;font-weight:700;font-size:11px">⚠ ${unmapped.length} row${unmapped.length===1?"":"s"} excluded</span> <span style="color:${T.label};font-size:11px">— Brand-Location cell didn't parse into a known brand: ${top}. Check these rows in the sheet use the "Brand - Outlet" format (e.g. "Oregano - Al Reem").</span></div>`;
    })():"";

    if(cpcHistCompare){
      return filterBar+unmappedNote+cpcHistCompareView(months);
    }
    return filterBar+unmappedNote+cpcHistTableView();
  }catch(e){
    console.error("[Ad History] render failed:",e);
    return`<div class="card" style="border:1px solid rgba(239,68,68,.4)"><div style="color:#ef4444;font-weight:800;margin-bottom:6px">⚠️ History view failed</div><div style="color:#475569;font-size:11.5px">${(e&&e.message)||"unknown error"}</div></div>`;
  }
}

// Apply the current filter set to cpcData. Outlet matching goes through canonicalization so
// selecting "Al Quoz" from the dropdown also matches raw rows still tagged "AQ".
function cpcHistFilteredRows(){
  return cpcData.filter(r=>
    (cpcHistFilters.month==="all"||r.month===cpcHistFilters.month)&&
    (cpcHistFilters.brand==="all"||r.brand===cpcHistFilters.brand)&&
    (cpcHistFilters.aggregator==="all"||r.aggregator===cpcHistFilters.aggregator)&&
    (cpcHistFilters.outlet==="all"||cpcHistCanonicalOutlet(r.branch,r.brand)===cpcHistFilters.outlet)&&
    (cpcHistFilters.adType==="all"||r.adType===cpcHistFilters.adType)
  );
}

// Default (non-compare) table view: every row matching filters, sorted newest-first, with a
// totals strip. Surfaces budgetType (combined/separate) and updateDate/remarks so the user can
// audit grouping accuracy directly against what they entered in the sheet.
function cpcHistTableView(){
  const T=cpcTheme();
  const rows=cpcHistFilteredRows().sort((a,b)=>(b.startDate||"").localeCompare(a.startDate||""));
  if(!rows.length)return`<div class="card" style="margin-top:12px"><div style="color:${T.label};font-size:12px">No rows match the current filters.</div></div>`;
  const totalAlloc=rows.reduce((s,r)=>s+(r.budgetAlloc||0),0);
  const totalSpent=rows.reduce((s,r)=>s+(r.budgetSpent||0),0);
  const totalSales=rows.reduce((s,r)=>s+(r.sales||0),0);
  const totalOrders=rows.reduce((s,r)=>s+(r.orders||0),0);
  const totalROAS=totalSpent>0?totalSales/totalSpent:null;
  const summaryStrip=`<div class="card" style="padding:10px 14px;display:flex;gap:22px;flex-wrap:wrap;align-items:center">
    <div><div style="font-size:9.5px;color:${T.muted};text-transform:uppercase;font-weight:700">Rows</div><div style="font-size:15px;font-weight:800;color:${T.text}">${rows.length}</div></div>
    <div><div style="font-size:9.5px;color:${T.muted};text-transform:uppercase;font-weight:700">Budget Allocated</div><div style="font-size:15px;font-weight:800;color:#fbbf24">${fmtAEDTip(totalAlloc)}</div></div>
    <div><div style="font-size:9.5px;color:${T.muted};text-transform:uppercase;font-weight:700">Budget Spent</div><div style="font-size:15px;font-weight:800;color:${T.secondary}">${fmtAEDTip(totalSpent)}</div></div>
    <div><div style="font-size:9.5px;color:${T.muted};text-transform:uppercase;font-weight:700">Sales</div><div style="font-size:15px;font-weight:800;color:#22C55E">${fmtAEDTip(totalSales)}</div></div>
    <div><div style="font-size:9.5px;color:${T.muted};text-transform:uppercase;font-weight:700">Orders</div><div style="font-size:15px;font-weight:800;color:${T.text}">${totalOrders.toLocaleString()}</div></div>
    <div><div style="font-size:9.5px;color:${T.muted};text-transform:uppercase;font-weight:700">Blended ROAS</div><div style="font-size:15px;font-weight:800;color:${totalROAS!=null?'#86EFAC':T.muted}">${totalROAS!=null?totalROAS.toFixed(2)+"×":"—"}</div></div>
  </div>`;
  const tRows=rows.map(r=>{
    const roas=r.budgetSpent>0?r.sales/r.budgetSpent:null;
    const roasTxt=roas!=null?`<strong style="color:${roas>=r.be?'#22C55E':'#EF4444'}">${roas.toFixed(2)}×</strong>`:`<span style="color:${T.muted};font-size:10.5px">—</span>`;
    const poolTag=r.budgetType==="combined"?`<span style="background:rgba(96,165,250,.12);color:#60A5FA;padding:1px 5px;border-radius:3px;font-size:9px;font-weight:700">POOL</span>`:`<span style="background:rgba(148,163,184,.1);color:${T.label};padding:1px 5px;border-radius:3px;font-size:9px;font-weight:700">SEPARATE</span>`;
    const fundedTag=/funded\s+by\s+noon/i.test(r.remarks||"")?`<span style="background:rgba(34,197,94,.12);color:#22C55E;padding:1px 5px;border-radius:3px;font-size:9px;font-weight:700;margin-left:4px">FUNDED BY NOON</span>`:"";
    return`<tr style="border-bottom:1px solid ${T.border}"><td style="padding:6px 8px;color:${BMAP[r.brand]?.c||'#fff'};font-weight:700;font-size:11px">${r.brand}</td><td style="padding:6px 8px;color:${T.text};font-size:11px">${r.branch||"—"}</td><td style="padding:6px 8px;color:${AC[r.aggregator]||'#fff'};font-size:11px">${r.aggregator}</td><td style="padding:6px 8px;color:${T.label};font-size:10.5px">${r.adType}</td><td style="padding:6px 8px;color:${T.label};font-size:10.5px">${r.startDate||"?"} → ${r.endDate||"?"}</td><td style="padding:6px 8px;text-align:right;color:${T.label};font-size:11px">${fmtAEDTip(r.budgetAlloc)}</td><td style="padding:6px 8px;text-align:right;color:${T.secondary};font-size:11px">${fmtAEDTip(r.budgetSpent)}</td><td style="padding:6px 8px;text-align:right;color:#22C55E;font-size:11px">${fmtAEDTip(r.sales)}</td><td style="padding:6px 8px;text-align:right">${roasTxt}</td><td style="padding:6px 8px">${poolTag}</td><td style="padding:6px 8px;color:${T.label};font-size:10px">${r.updateDate||"—"}${fundedTag}</td></tr>`;
  }).join("");
  return summaryStrip+`<div class="card" style="margin-top:12px"><div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:11px"><thead><tr style="border-bottom:1px solid ${T.border};color:${T.muted};font-size:9.5px;text-transform:uppercase;letter-spacing:.3px"><th style="padding:6px 8px;text-align:left">Brand</th><th style="padding:6px 8px;text-align:left">Outlet</th><th style="padding:6px 8px;text-align:left">Aggregator</th><th style="padding:6px 8px;text-align:left">Ad Type</th><th style="padding:6px 8px;text-align:left">Period</th><th style="padding:6px 8px;text-align:right">Allocated</th><th style="padding:6px 8px;text-align:right">Spent</th><th style="padding:6px 8px;text-align:right">Sales</th><th style="padding:6px 8px;text-align:right">ROAS</th><th style="padding:6px 8px;text-align:left">Budget Type</th><th style="padding:6px 8px;text-align:left">Last Updated</th></tr></thead><tbody>${tRows}</tbody></table></div></div>`;
}

// Compare view: two fully independent filter panels (Month, Brand, Aggregator, Outlet, Ad Type),
// mirroring the main Compare page's A/B ergonomics — each side can be scoped completely
// differently (e.g. A = Noon all brands in May, B = Talabat Oregano-only in June). Aggregation
// is single-pass per side (one forEach building a Map keyed by brand|aggregator) instead of
// re-filtering the full row array once per unique key, which is what made the old "two months,
// shared filter" version slow as the dataset grew.
function cpcHistCompareView(months){
  const T=cpcTheme();
  const brandsOpt=cpcHistBrandOptions(),aggsOpt=cpcHistUniqueVals("aggregator").sort(),adTypesOpt=cpcHistUniqueVals("adType").sort();
  const outletsOpt=(side)=>{
    const f=side==="A"?cpcCompA:cpcCompB;
    const pool=f.brand!=="all"?cpcData.filter(r=>r.brand===f.brand):cpcData;
    const seen=new Map();
    pool.forEach(r=>{if(!r.branch)return;const resolved=cpcHistCanonicalOutlet(r.branch,r.brand);const k=resolved.toLowerCase();if(!seen.has(k))seen.set(k,resolved);});
    return[...seen.values()].sort();
  };
  const sel=(side,label,key,opts,curVal)=>{
    const optsHtml=['<option value="all">All</option>',...opts.map(o=>`<option value="${o}" ${curVal===o?"selected":""}>${key==='month'?cpcMonthLabel(o):o}</option>`)].join("");
    return`<div style="display:flex;flex-direction:column;gap:2px"><label style="font-size:9px;color:${T.muted};text-transform:uppercase;font-weight:700;font-weight:700">${label}</label><select onchange="cpcCompSet('${side}','${key}',this.value)" style="background:${T.panelBg};border:1px solid ${T.border};border-radius:5px;color:${T.text};padding:5px 7px;font-size:11px;min-width:105px">${optsHtml}</select></div>`;
  };
  const panel=(side,f,accent)=>`<div style="flex:1;min-width:260px;border:1px solid ${accent}44;border-radius:8px;padding:10px;background:${accent}0a">
    <div style="font-size:11px;font-weight:800;color:${accent};margin-bottom:8px">${side==="A"?"A":"B"}</div>
    <div style="display:flex;gap:8px;flex-wrap:wrap">
      ${sel(side,"Month",'month',months,f.month)}
      ${sel(side,"Brand",'brand',brandsOpt,f.brand)}
      ${sel(side,"Aggregator",'aggregator',aggsOpt,f.aggregator)}
      ${sel(side,"Outlet",'outlet',outletsOpt(side),f.outlet)}
      ${sel(side,"Ad Type",'adType',adTypesOpt,f.adType)}
    </div>
  </div>`;
  const picker=`<div class="card" style="padding:12px 14px;margin-top:12px"><div style="display:flex;gap:12px;flex-wrap:wrap;align-items:flex-start">${panel("A",cpcCompA,"#60A5FA")}<div style="display:flex;align-items:center;padding-top:24px;color:${T.muted};font-weight:700;font-size:12px">vs</div>${panel("B",cpcCompB,"#F59E0B")}</div></div>`;

  // Single-pass aggregation per side: one forEach building a Map<brand|ag, totals> instead of
  // O(keys × rows) repeated filtering.
  const aggregate=(f)=>{
    const matches=r=>(f.month==="all"||r.month===f.month)&&(f.brand==="all"||r.brand===f.brand)&&(f.aggregator==="all"||r.aggregator===f.aggregator)&&(f.outlet==="all"||cpcHistCanonicalOutlet(r.branch,r.brand)===f.outlet)&&(f.adType==="all"||r.adType===f.adType);
    const map=new Map();
    for(const r of cpcData){
      if(!matches(r))continue;
      const k=`${r.brand}|${r.aggregator}`;
      if(!map.has(k))map.set(k,{brand:r.brand,ag:r.aggregator,spent:0,sales:0,rowCount:0});
      const o=map.get(k);
      o.spent+=r.budgetSpent||0;o.sales+=r.sales||0;o.rowCount++;
    }
    return map;
  };
  const mapA=aggregate(cpcCompA),mapB=aggregate(cpcCompB);
  const allKeys=new Set([...mapA.keys(),...mapB.keys()]);
  const compRows=[...allKeys].map(k=>{
    const a=mapA.get(k)||{spent:0,sales:0,rowCount:0};
    const b=mapB.get(k)||{spent:0,sales:0,rowCount:0};
    const[brand,ag]=k.split("|");
    const aROAS=a.spent>0?a.sales/a.spent:null,bROAS=b.spent>0?b.sales/b.spent:null;
    return{brand,ag,aSpent:a.spent,bSpent:b.spent,aSales:a.sales,bSales:b.sales,aROAS,bROAS,aRowCount:a.rowCount,bRowCount:b.rowCount,deltaSpent:b.spent-a.spent};
  }).filter(r=>r.aSpent>0||r.bSpent>0).sort((a,b)=>a.brand.localeCompare(b.brand)||a.ag.localeCompare(b.ag));

  if(!compRows.length)return picker+`<div class="card" style="margin-top:12px;color:${T.label};font-size:12px">No rows match either side's filters.</div>`;

  const tRows=compRows.map(r=>{
    const deltaTxt=r.deltaSpent>0?`<span style="color:#22C55E">+${fmtAEDTip(r.deltaSpent)}</span>`:r.deltaSpent<0?`<span style="color:#EF4444">${fmtAEDTip(r.deltaSpent)}</span>`:`<span style="color:${T.muted}">—</span>`;
    // Row-count mismatch is a grouping signal: if A had 1 row (combined) and B has 3 (separate),
    // or vice versa, flag it so the user can verify that's intentional.
    const rowCountFlag=r.aRowCount!==r.bRowCount?`<span style="color:#FBBF24;font-size:9.5px" title="Number of sheet rows feeding this total changed — check if entries were grouped/split differently">⚠ ${r.aRowCount}→${r.bRowCount} rows</span>`:`<span style="color:${T.muted};font-size:9.5px">${r.aRowCount} rows</span>`;
    return`<tr style="border-bottom:1px solid ${T.border}"><td style="padding:7px 8px;color:${BMAP[r.brand]?.c||'#fff'};font-weight:700;font-size:11.5px">${r.brand}</td><td style="padding:7px 8px;color:${AC[r.ag]||'#fff'};font-size:11.5px">${r.ag}</td><td style="padding:7px 8px;text-align:right;color:#60A5FA;font-size:11px">${fmtAEDTip(r.aSpent)}</td><td style="padding:7px 8px;text-align:right;color:#F59E0B;font-size:11px">${fmtAEDTip(r.bSpent)}</td><td style="padding:7px 8px;text-align:right;font-size:11px">${deltaTxt}</td><td style="padding:7px 8px;text-align:right;color:#60A5FA;font-size:11px">${r.aROAS!=null?r.aROAS.toFixed(2)+"×":"—"}</td><td style="padding:7px 8px;text-align:right;color:#F59E0B;font-size:11px">${r.bROAS!=null?r.bROAS.toFixed(2)+"×":"—"}</td><td style="padding:7px 8px;text-align:center">${rowCountFlag}</td></tr>`;
  }).join("");
  const totA=compRows.reduce((s,r)=>s+r.aSpent,0),totB=compRows.reduce((s,r)=>s+r.bSpent,0);
  return picker+`<div class="card" style="margin-top:12px">
    <div style="margin-bottom:10px"><div style="font-size:12px;font-weight:800;color:${T.text}">Brand × Aggregator — A vs B</div><div style="font-size:10.5px;color:${T.label};margin-top:2px">Each side uses its own independent filters above. Row-count column flags when the number of underlying sheet entries differs — useful for catching unintended grouping/splitting.</div></div>
    <div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:11.5px"><thead><tr style="border-bottom:1px solid ${T.border};color:${T.muted};font-size:10px;text-transform:uppercase;letter-spacing:.4px"><th style="padding:6px 8px;text-align:left">Brand</th><th style="padding:6px 8px;text-align:left">Aggregator</th><th style="padding:6px 8px;text-align:right">A Spent</th><th style="padding:6px 8px;text-align:right">B Spent</th><th style="padding:6px 8px;text-align:right">Δ Spent</th><th style="padding:6px 8px;text-align:right">A ROAS</th><th style="padding:6px 8px;text-align:right">B ROAS</th><th style="padding:6px 8px;text-align:center">Sheet Rows</th></tr></thead><tbody>${tRows}</tbody><tfoot><tr style="border-top:2px solid ${T.border}"><td colspan="2" style="padding:8px;color:${T.label};font-size:11px;font-weight:700">TOTAL</td><td style="padding:8px;text-align:right;color:#60A5FA;font-weight:800">${fmtAEDTip(totA)}</td><td style="padding:8px;text-align:right;color:#F59E0B;font-weight:800">${fmtAEDTip(totB)}</td><td colspan="4"></td></tr></tfoot></table></div>
  </div>`;
}

// ═══════════════════════════════════════════════════════════════
// END AD INVESTMENT HISTORY MODULE
// ═══════════════════════════════════════════════════════════════

// Dispatcher: when 'All' is selected and the brand has more than one ad type (e.g. CPC + Banners,
// CPC + Keywords), render a SEPARATE headlined section per ad type instead of blending their
// budget/spend/ROAS into one merged figure. A single-type brand (the common case) is unaffected —
// goes straight to the single-type renderer exactly as before.
function cpcRenderOutletLevel(ag,brand){
  const T=cpcTheme();
  const A=cpcModel.byAgg[ag];if(!A||!A.brands[brand])return `<div class="card">No data</div>`;
  const B=A.brands[brand];
  // Fixed reading order: CPC always first, then Keywords, then Banners, then anything else —
  // independent of Set insertion order (which follows raw sheet row order and isn't reliable).
  const TYPE_ORDER={CPC:0,Keywords:1,Banners:2};
  const aggAdTypes=[...B.adTypes].sort((a,b)=>(TYPE_ORDER[a]??99)-(TYPE_ORDER[b]??99));
  if(cpcAdTypeFilter!=='all'||aggAdTypes.length<=1){
    return cpcRenderOutletLevelSingle(ag,brand,false);
  }
  // Build toggle at the dispatcher level with 'All' correctly highlighted
  const clr=AGG_LOGO_CLR[ag]||T.label;
  const adToggle=`<div style="display:flex;gap:6px;margin-bottom:14px;align-items:center"><span style="font-size:10px;color:${T.muted};font-weight:700;text-transform:uppercase">Ad Type</span>${['all',...aggAdTypes].map(t=>`<button onclick="cpcSetAdType('${t}')" style="padding:4px 12px;border-radius:6px;border:1px solid ${cpcAdTypeFilter===t?clr:T.border};background:${cpcAdTypeFilter===t?clr+'22':'transparent'};color:${cpcAdTypeFilter===t?clr:T.label};font-size:11px;font-weight:600;cursor:pointer">${t==='all'?'All':t}</button>`).join('')}</div>`;
  // Split into one section per ad type. Temporarily pin cpcAdTypeFilter to each type while
  // capturing that section's HTML, then restore 'all' so the real app state is unchanged.
  const savedFilter=cpcAdTypeFilter;
  const sections=aggAdTypes.map(t=>{
    cpcAdTypeFilter=t;
    const html=cpcRenderOutletLevelSingle(ag,brand,true);
    const headline=`<div style="display:flex;align-items:center;gap:8px;margin:18px 0 8px 0"><span style="font-size:14px;font-weight:800;color:${AC[ag]||'#f59e0b'}">📌 ${brand} on ${ag} — ${t} Campaigns</span><div style="flex:1;height:1px;background:${T.border}"></div></div>`;
    return headline+html;
  });
  cpcAdTypeFilter=savedFilter; // restore 'all' — this loop must never leak a pinned filter into global state
  return adToggle+sections.join("");
}

function cpcRenderOutletLevelSingle(ag,brand,skipToggle){
  const T=cpcTheme();
  const A=cpcModel.byAgg[ag];if(!A||!A.brands[brand])return `<div class="card">No data</div>`;
  const B=A.brands[brand];
  const aggAdTypes=[...B.adTypes];
  const effAdType=(cpcAdTypeFilter!=='all'&&aggAdTypes.includes(cpcAdTypeFilter))?cpcAdTypeFilter:'all';
  let rows=B.rows;if(effAdType!=='all')rows=rows.filter(r=>r.adType===effAdType);
  const today=cpcRealToday();
  const curMonthStr=cpcModel.curMonth;
  // Months that have ads for this aggregator+brand (current first, then previous up to 6)
  const monthsAvail=[...new Set(rows.map(r=>r.month).filter(Boolean))].sort().reverse(); // v096: no cap — every month reachable
  // Default selected month = current month (if it has ads) else most recent available
  let selMonth=cpcMonthFilter;
  // Default to current month. Pre-v082 this fell back to the most recent month WITH data when
  // the current month had none — showing June's numbers when July had no CPC investment. That's
  // misleading because the user thinks they're seeing current-month performance. Now we always
  // default to current month; if there's no data, we show a clear empty state ("No CPC data for
  // July 2026") rather than silently presenting stale figures. Users can still click a prior-
  // month button to see historical data explicitly.
  if(selMonth==='all'||!selMonth){selMonth=curMonthStr;}
  const hasDataForSelected=monthsAvail.includes(selMonth);
  const isCurrentMonth=selMonth===curMonthStr;

  // Month/Year picker on the RIGHT
  // v096: first 7 months as buttons, anything older in an "Older…" dropdown so long histories
  // (2025+) don't turn the control bar into a wall of buttons.
  const monthsBtnList=monthsAvail.slice(0,7);
  const monthsOlder=monthsAvail.slice(7);
  const monthBtns=monthsBtnList.map(m=>{const isCur=m===curMonthStr;const act=selMonth===m;return `<button onclick="cpcSetMonth('${m}')" style="padding:4px 11px;border-radius:6px;border:1px solid ${act?'#f59e0b':'rgba(15,23,42,.6)'};background:${act?'rgba(245,158,11,.12)':'transparent'};color:${act?'#f59e0b':T.label};font-size:11px;font-weight:600;cursor:pointer">${cpcMonthLabel(m)}${isCur?' •':''}</button>`;}).join('')
    +(monthsOlder.length?`<select onchange="if(this.value)cpcSetMonth(this.value)" style="padding:4px 9px;border-radius:6px;border:1px solid ${monthsOlder.includes(selMonth)?'#f59e0b':'rgba(15,23,42,.6)'};background:${monthsOlder.includes(selMonth)?'rgba(245,158,11,.12)':T.panelBg};color:${monthsOlder.includes(selMonth)?'#f59e0b':T.label};font-size:11px;font-weight:600;cursor:pointer"><option value="">Older… (${monthsOlder.length})</option>${monthsOlder.map(m=>`<option value="${m}" ${selMonth===m?'selected':''}>${cpcMonthLabel(m)}</option>`).join('')}</select>`:'');
  const adToggle=(!skipToggle&&aggAdTypes.length>1)?`<div style="display:flex;gap:6px;align-items:center"><span style="font-size:10px;color:${T.muted};font-weight:700;text-transform:uppercase">Ad Type</span>${['all',...aggAdTypes].map(tp=>`<button onclick="cpcSetAdType('${tp}')" style="padding:4px 12px;border-radius:6px;border:1px solid ${effAdType===tp?'#f59e0b':'rgba(15,23,42,.6)'};background:${effAdType===tp?'rgba(245,158,11,.12)':'transparent'};color:${effAdType===tp?'#f59e0b':T.label};font-size:11px;font-weight:600;cursor:pointer">${tp==='all'?'All':tp}</button>`).join('')}</div>`:'';
  const controlBar=`<div style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:12px">${adToggle||'<div></div>'}<div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap"><span style="font-size:10px;color:${T.muted};font-weight:700;text-transform:uppercase">Month</span>${monthBtns}</div></div>`;

  // Build per-outlet rows for the selected month
  if(!hasDataForSelected){
    // No data for selected month — show clear empty state with month buttons to navigate to prior months.
    // BUG FIX (found by tracing the "brand cards not clickable" report): this branch used to do
    // `tgt.innerHTML = ...; return;` but `tgt` was never defined anywhere in this function — every
    // other branch in cpcRenderOutletLevelSingle RETURNS an HTML string (that's how the caller
    // consumes it), so this leftover DOM-write pattern threw "ReferenceError: tgt is not defined"
    // the instant a brand had no data for the current month+ad-type (e.g. a brand that only runs
    // Keywords ads this month, no CPC). The click into the brand card technically worked and
    // navigated, but the destination page crashed silently while rendering — looking exactly like
    // "nothing happened when I clicked." Fixed to return the HTML string like every other branch.
    const emptyMonthLabel=cpcMonthLabel(selMonth);
    const allMonthBtns=[selMonth,...monthsAvail.filter(m=>m!==selMonth)].map(m=>{const isCur=m===curMonthStr;const act=selMonth===m;return `<button onclick="cpcSetMonth('${m}')" style="padding:4px 11px;border-radius:6px;border:1px solid ${act?'#f59e0b':'rgba(15,23,42,.6)'};background:${act?'rgba(245,158,11,.12)':'transparent'};color:${act?'#f59e0b':T.label};font-size:11px;font-weight:600;cursor:pointer">${cpcMonthLabel(m)}${isCur?' •':''}</button>`;}).join('');
    const emptyControlBar=`<div style="display:flex;justify-content:flex-end;align-items:center;gap:6px;flex-wrap:wrap;margin-bottom:12px"><span style="font-size:10px;color:${T.muted};font-weight:700;text-transform:uppercase">Month</span>${allMonthBtns}</div>`;
    return `${emptyControlBar}<div class="card" style="text-align:center;padding:40px 20px"><div style="font-size:40px;margin-bottom:12px">📭</div><div style="font-size:16px;font-weight:700;color:${T.text};margin-bottom:6px">No CPC investment data for ${emptyMonthLabel}</div><div style="font-size:13px;color:${T.muted};line-height:1.6">No ad spend has been recorded for ${brand} on ${ag} in ${emptyMonthLabel}.<br>If ads are running this month, they'll appear here once the CPC data sheet is updated.${monthsAvail.length>0?`<br><br>Historical data available for: <strong>${monthsAvail.map(cpcMonthLabel).join(', ')}</strong> — click a month button above to view.`:''}</div></div>`;
  }
  const outlets={};rows.forEach(r=>{if(!outlets[r.branch])outlets[r.branch]=[];outlets[r.branch].push(r);});
  const adTypeOf=effAdType==='all'?'CPC':effAdType;
  let tableRows=Object.entries(outlets).map(([outlet,orows])=>{
    const monthRows=orows.filter(r=>r.month===selMonth);
    const disp=cpcCombineRows(monthRows,brand,ag);
    if(!disp||(!disp.spent&&!disp.alloc))return null;
    // MoM vs prior calendar month
    let momChg=null,momLabel='';
    const prevMonth=cpcPrevMonth(selMonth);
    const prev=cpcCombineRows(orows.filter(r=>r.month===prevMonth),brand,ag);
    if(prev&&prev.roi!=null&&disp.roi!=null){momChg=pctOf(disp.roi,prev.roi);momLabel='vs '+cpcMonthLabel(prevMonth);}
    // vs 2026 year
    const yr=cpcModel.yearROI.get(`${brand}|${ag}|${adTypeOf}|${outlet}`);
    let yoyChg=null;if(yr&&yr.roi!=null&&disp.roi!=null)yoyChg=pctOf(disp.roi,yr.roi);
    // Calculated avg bid = spent / clicks
    const calcBid=disp.views>0?disp.spent/disp.views:null;
    // Representative live row (for invest rec + bid opt)
    const liveRow=monthRows.find(r=>r.status==="Active")||monthRows[monthRows.length-1];
    return {outlet,disp,momChg,momLabel,yoyChg,yearROI:yr?.roi,rows:orows,monthRows,calcBid,liveRow};
  }).filter(Boolean);

  const brandCTOs=tableRows.map(t=>t.disp.cto).filter(c=>c!=null);
  const brandAvgCTO=brandCTOs.length?brandCTOs.reduce((a,b)=>a+b,0)/brandCTOs.length:null;

  // sort
  const sc=cpcSort.col,sd=cpcSort.dir;
  const getVal=(t)=>{const d=t.disp;switch(sc){case'clicks':return d.views||0;case'orders':return d.orders||0;case'sales':return d.sales||0;case'aov':return d.aov||0;case'cto':return d.cto||0;case'budget':return d.alloc||0;case'spent':return d.spent||0;case'leftover':return d.leftover||0;case'roas':return d.roi||0;case'bid':return t.calcBid||0;case'ftu':return d.ftu||0;default:return d.roi||0;}};
  tableRows.sort((a,b)=>(getVal(a)-getVal(b))*sd);

  // Determine whether this brand has pooled rows, separate rows, or a mix of both.
  // Mixed brands (e.g. Oregano on Noon where Jumeirah is separate but the rest are pooled) need
  // both treatments: separate rows show per-outlet budget normally, pooled rows show "—", and the
  // TOTAL row sums separate budgets + pool total (once, not split per outlet).
  const hasSomePooled=tableRows.some(t=>{const bt=(t.liveRow&&t.liveRow.budgetType)||"separate";return bt==="combined";});
  const hasSomeSeparate=tableRows.some(t=>{const bt=(t.liveRow&&t.liveRow.budgetType)||"separate";return bt!=="combined";});
  const isAllPooled=hasSomePooled&&!hasSomeSeparate;
  const isMixed=hasSomePooled&&hasSomeSeparate;

  const arrow=(col)=>cpcSort.col===col?(cpcSort.dir<0?' ▼':' ▲'):'';
  const th=(col,lbl)=>`<th style="cursor:pointer;text-align:right" onclick="cpcSetSort('${col}')">${lbl}${arrow(col)}</th>`;

  // Show the Invest/Bid column whenever we're on the current month. Previously this was hidden
  // for Careem because all Careem budgets were assumed pooled — but now per-row budgetType
  // controls the display ("+AED" for separate, "🔒 pool" for combined), so the column stays
  // visible for every aggregator and the user can see exceptions.
  const showInvestCol=isCurrentMonth;

  // Totals accumulators. tInvestPool comes from the POOL aggregate computed once below
  // (not from summing per-outlet amounts); tInvestSep comes from per-outlet calculations.
  let tClicks=0,tOrders=0,tSales=0,tBudget=0,tSpent=0,tLeftover=0,tFtu=0,tInvest=0,tInvestPool=0,tInvestSep=0;

  // ── POOL-LEVEL CALCULATION ─────────────────────────────────────────────────
  // For "Combined Per Brand" outlets, individual rows can show "exhausted" or "leftover ≤ 0"
  // even when the brand-pool still has budget. The pool is what actually controls when ads stop.
  // We aggregate the pooled rows' alloc/spent/burn once here and use that for the pool status
  // every pooled row displays. Separate-budget rows keep their per-outlet calculation.
  const pooledTableRows=tableRows.filter(t=>t.liveRow&&t.liveRow.budgetType==="combined");
  const poolRec=(isCurrentMonth&&pooledTableRows.length)?cpcPoolInvestRec(pooledTableRows):null;
  // Pool verdict: do we have any pooled outlet with a worthwhile ROAS? If the entire pool is
  // below break-even, don't recommend restart even if exhausted.
  const poolHasSomeGoodVerdict=pooledTableRows.some(t=>t.disp.verdict==="SCALE"||t.disp.verdict==="INVEST");
  if(poolRec&&poolRec.additional>0&&poolHasSomeGoodVerdict){
    tInvestPool=poolRec.additional;
    tInvest+=poolRec.additional;
  }

  // For brands with ANY pooled rows: compute the pool total from the brand-model's POOLED rows
  // only (not separate rows, which are counted individually in the per-row loop below). This
  // correctly handles the mixed case where e.g. 12 outlets share a pool and 2 have their own
  // separate budgets — pool total + separate totals = correct grand total.
  let poolTotalAlloc=0,poolTotalSpent=0;
  if(hasSomePooled&&tableRows.length){
    const bModel=cpcModel.byAgg[ag]&&cpcModel.byAgg[ag].brands[brand];
    // Filter by BOTH budgetType AND the effective ad-type filter, so viewing "CPC only" doesn't
    // include Keywords/Banners pool budget in the pool banner.
    const poolRows=bModel
      ?bModel.rows.filter(r=>r.month===selMonth&&r.budgetType==="combined"&&(effAdType==='all'||r.adType===effAdType))
      :rows.filter(r=>r.month===selMonth&&r.budgetType==="combined"&&(effAdType==='all'||r.adType===effAdType));
    poolTotalAlloc=poolRows.reduce((s,r)=>s+(r.budgetAlloc||0),0);
    poolTotalSpent=poolRows.reduce((s,r)=>s+(r.budgetSpent||0),0);
  }

  const body=(()=>{
    // Sort: separate-budget outlets first, pooled outlets grouped together at the bottom
    const sorted=[...tableRows].sort((a,b)=>{
      const aPooled=((a.liveRow&&a.liveRow.budgetType)||"separate")==="combined"?1:0;
      const bPooled=((b.liveRow&&b.liveRow.budgetType)||"separate")==="combined"?1:0;
      if(aPooled!==bPooled)return aPooled-bPooled; // separate first
      return 0; // preserve existing sort within each group
    });
    let poolBannerEmitted=false;
    const colCount=showInvestCol?14:13; // total columns in the table
    return sorted.map(t=>{
    const d=t.disp;const vClr=d.verdict?CPC_VC[d.verdict]:T.muted;
    const budgetType=(t.liveRow&&t.liveRow.budgetType)||"separate";
    const isPooled=budgetType==="combined";
    // For pooled outlets: per-outlet budget/leftover are NOT added to the running total (the pool
    // total is added once outside this loop). Per-outlet spent IS accumulated because it's real.
    if(!isPooled){tBudget+=d.alloc||0;tLeftover+=d.leftover||0;}
    tClicks+=d.views||0;tOrders+=d.orders||0;tSales+=d.sales||0;tSpent+=d.spent||0;tFtu+=d.ftu||0;
    // CTO relative
    let ctoTag='';
    if(d.cto!=null&&brandAvgCTO){const rel=d.cto/brandAvgCTO;ctoTag=rel>=1.2?`<span style="color:#22C55E;font-weight:700">▲</span>`:rel<=0.8?`<span style="color:#EF4444;font-weight:700">▼</span>`:'';}
    const imp=cpcModel.postImpact.get(t.rows[t.rows.length-1]);
    const impTag=imp&&imp.salesChg<-15?` <span title="Sales fell ${fmtPct(imp.salesChg)} after CPC ended" style="font-size:9px;color:#EF4444;cursor:help">📉</span>`:'';
    // "Funded by Noon" detection — surfaces in the drilldown table (not just the History tab).
    // Checks every row contributing to this outlet's current display (monthRows, falling back to
    // all rows if month-filtered set is empty) for the remark, case-insensitive.
    const fundedSource=(t.monthRows&&t.monthRows.length?t.monthRows:t.rows)||[];
    const isFundedByNoon=fundedSource.some(rr=>/funded\s+by\s+noon/i.test(rr.remarks||""));
    const fundedTag=isFundedByNoon?` <span title="This campaign is funded by Noon, not 100% merchant cost." style="background:rgba(34,197,94,.15);color:#22C55E;padding:1px 6px;border-radius:4px;font-size:9px;font-weight:800;vertical-align:middle">FUNDED BY NOON</span>`:'';
    // Lock badge for pooled outlets (tooltip explains why no per-outlet recommendation)
    const poolTag=isPooled?` <span title="Budget pooled with other ${brand} outlets on ${ag} — can't be topped up individually." style="font-size:9px;color:#60A5FA;cursor:help">🔒</span>`:'';
    // Investment + bid recommendation (current month only)
    let recCell=`<span style="color:${T.secondary};font-size:10px">—</span>`;
    if(isCurrentMonth){
      const bidOpt=cpcDeliverooBidOpt(ag,brand,t.outlet,t.liveRow,t.calcBid);
      const parts=[];
      if(isPooled){
        // Pooled row: show POOL-level status, identical for every pooled outlet in this brand.
        // The individual outlet's leftover/exhausted state is misleading because spend continues
        // from the pool regardless.
        if(poolRec){
          if(poolRec.mode==="active"){
            if(poolRec.additional>0&&poolHasSomeGoodVerdict){
              const dryClr=poolRec.daysUntilDry<=3?'#EF4444':poolRec.daysUntilDry<=7?'#FBBF24':T.label;
              parts.push(`<div style="font-size:10px;color:${dryClr};font-weight:700" title="Pool will run dry in ${poolRec.daysUntilDry} day(s) at current burn rate. Top-up shown in the summary below.">🔒 pool: dry in ${poolRec.daysUntilDry}d</div>`);
            }else if(poolRec.additional<=0){
              parts.push(`<div style="font-size:10px;color:#22C55E" title="Pool's remaining budget covers projected burn through month-end.">🔒 pool: covers month</div>`);
            }
          }else if(poolRec.mode==="restart"){
            if(poolHasSomeGoodVerdict){
              parts.push(`<div style="font-size:10px;color:#22C55E;font-weight:700" title="Pool budget exhausted. Restart amount shown in summary below.">🔒 pool: exhausted</div>`);
            }else{
              parts.push(`<div style="font-size:10px;color:#EF4444" title="Pool exhausted AND all outlets in pool are below break-even — don't restart.">🔒 pool: don't restart (below BE)</div>`);
            }
          }
        }else{
          parts.push(`<div style="font-size:10px;color:${T.label}">🔒 pooled</div>`);
        }
      }else{
        // Separate row: per-outlet calculation as before
        const inv=cpcInvestRec(ag,brand,t.outlet,t.liveRow,bidOpt);
        const goodVerdict=d.verdict==="SCALE"||d.verdict==="INVEST";
        const poorVerdict=d.verdict==="WITHDRAW";
        if(inv){
          if(inv.mode==="active"){
            if(inv.additional>0&&goodVerdict){
              tInvest+=inv.additional;tInvestSep+=inv.additional;
              const dryClr=inv.daysUntilDry<=3?'#EF4444':inv.daysUntilDry<=7?'#FBBF24':T.label;
              parts.push(`<div style="font-size:10px;color:${dryClr};font-weight:700">dry in ${inv.daysUntilDry}d · +${fmtAEDTip(inv.additional)}</div>`);
            }else if(inv.additional>0&&poorVerdict){
              parts.push(`<div style="font-size:10px;color:#EF4444;font-weight:700">dry in ${inv.daysUntilDry}d · hold (below BE)</div>`);
            }else if(inv.additional<=0){
              const pace=cpcPacingRec(ag,d,t.calcBid);
              if(pace&&pace.goodROI){
                parts.push(`<div style="font-size:10px;color:#F59E0B;font-weight:800" title="Only ~${pace.pacePct}% of the budget will be spent by month-end at the current burn — ~AED ${pace.projUnspent} would go unused. ROAS ${d.roi?d.roi.toFixed(1):'—'}×${pace.strongCTO?` and CTO ${d.cto.toFixed(0)}%`:''} support buying more impressions.${pace.capped?' Suggested bid is capped at 2× as a step — raise, re-check pace in 3–4 days, then step again if still underpacing.':''}">⚡ Budget pacing: underpacing ${pace.pacePct}%${pace.suggestedBid?` — raise bid to AED ${pace.suggestedBid.toFixed(2)}`:' — raise bid / visibility'}</div>`);
              }else if(pace){
                parts.push(`<div style="font-size:10px;color:${T.label}" title="Only ~${pace.pacePct}% of the budget will be spent by month-end, and ROI here is modest — rather than forcing spend into a weak outlet, consider reallocating ~AED ${pace.projUnspent} to higher-ROAS outlets.">Budget pacing: underpacing ${pace.pacePct}% · reallocate ~${fmtAEDTip(pace.projUnspent)}</div>`);
              }else{
                parts.push(`<div style="font-size:10px;color:#22C55E">✓ Budget pacing: on pace</div>`);
              }
            }
          }else if(inv.mode==="restart"){
            if(goodVerdict&&inv.additional>0){
              tInvest+=inv.additional;tInvestSep+=inv.additional;
              parts.push(`<div style="font-size:10px;color:#22C55E;font-weight:700">exhausted · restart +${fmtAEDTip(inv.additional)}</div>`);
            }else if(poorVerdict){
              parts.push(`<div style="font-size:10px;color:#EF4444">exhausted · don't restart (ROAS ${d.roi?d.roi.toFixed(2):'—'}×)</div>`);
            }
          }
        }
      }
      // Bid recommendation (Deliveroo only) — applies to BOTH pooled and separate rows.
      if(bidOpt&&bidOpt.suggestedBid&&ag==="Deliveroo"&&bidOpt.direction!=='hold'){
        const bClr=bidOpt.direction==='raise'?'#22C55E':'#EF4444';
        const action=bidOpt.direction==='raise'?'Raise':'Lower';
        // Show BOTH the target AND the current bid so the direction can't be misread. Previously
        // we just showed "bid ↓ AED 2.70" which was ambiguous — users saw a lower number they
        // were "supposed to move to" but couldn't tell whether the arrow meant "your current bid
        // is going down" or "we suggest a lower bid than what you have now".
        const fromTxt=bidOpt.curBid!=null?` <span style="color:${T.label};font-weight:400">(from ${bidOpt.curBid.toFixed(2)})</span>`:'';
        parts.push(`<div style="font-size:10px;color:${bClr}" title="Best balance of ROAS & volume was ${cpcMonthLabel(bidOpt.bestMonth)} at this bid. Independent of this month's budget pacing above — this looks at 6 months of history, not what's needed to spend out the current budget.">Historical optimal: ${action} bid to AED ${bidOpt.suggestedBid.toFixed(2)}${fromTxt}</div>`);
      }
      if(parts.length)recCell=parts.join('');
    }
    // Pool banner: emitted once, right before the first pooled outlet row. Shows the total pool
    // budget in a highlighted row spanning the full table width, so the user sees at a glance
    // "these outlets below share this pool" instead of seeing scattered "—" cells.
    let bannerRow='';
    if(isPooled&&!poolBannerEmitted){
      poolBannerEmitted=true;
      const poolLeft=Math.max(0,poolTotalAlloc-poolTotalSpent);
      const poolPct=poolTotalAlloc>0?Math.round(poolTotalSpent/poolTotalAlloc*100):0;
      bannerRow=`<tr><td colspan="${colCount}" style="padding:0"><div style="margin:12px 0 6px 0;padding:10px 14px;background:linear-gradient(135deg,rgba(96,165,250,.08),rgba(96,165,250,.02));border:1px solid rgba(96,165,250,.25);border-radius:8px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px"><div style="display:flex;align-items:center;gap:8px"><span style="font-size:14px">🔒</span><div><div style="font-size:12px;font-weight:800;color:#60A5FA">Pooled Budget — ${pooledTableRows.length} outlets share this pool</div><div style="font-size:10px;color:${T.label};margin-top:2px">${ag} auto-distributes spend across these outlets. Per-outlet budget is not controllable individually.</div></div></div><div style="display:flex;gap:16px;align-items:center"><div style="text-align:center"><div style="font-size:9px;color:${T.muted};text-transform:uppercase;font-weight:700">Allocated</div><div style="font-size:15px;font-weight:800;color:#fbbf24">${fmtAEDTip(poolTotalAlloc)}</div></div><div style="text-align:center"><div style="font-size:9px;color:${T.muted};text-transform:uppercase;font-weight:700">Spent</div><div style="font-size:15px;font-weight:800;color:${T.secondary}">${fmtAEDTip(poolTotalSpent)}</div></div><div style="text-align:center"><div style="font-size:9px;color:${T.muted};text-transform:uppercase;font-weight:700">Remaining</div><div style="font-size:15px;font-weight:800;color:${poolLeft>0?'#22C55E':'#EF4444'}">${fmtAEDTip(poolLeft)}</div></div><div style="text-align:center"><div style="font-size:9px;color:${T.muted};text-transform:uppercase;font-weight:700">Burn</div><div style="font-size:15px;font-weight:800;color:${T.label}">${poolPct}%</div></div></div></div></td></tr>`;
    }
    const row=`<tr style="cursor:pointer" onclick="cpcOpenOutletDetail('${ag}','${brand}','${encodeURIComponent(t.outlet)}')"><td><strong style="font-size:12px;color:${T.text}">${t.outlet}</strong>${impTag}${poolTag}${fundedTag}</td><td><span style="padding:3px 9px;border-radius:8px;background:${CPC_VB[d.verdict]||'rgba(100,116,139,.1)'};color:${vClr};font-size:10px;font-weight:800">${d.verdict||'—'}</span></td><td style="text-align:right">${(d.views||0).toLocaleString()}</td><td style="text-align:right">${(d.orders||0).toLocaleString()}</td><td style="text-align:right">${fmtAEDExact(d.sales)}</td><td style="text-align:right">${d.aov?d.aov.toFixed(0):'—'}</td><td style="text-align:right">${d.cto!=null?d.cto.toFixed(1)+'%':'—'} ${ctoTag}</td><td style="text-align:right">${isPooled?'<span style="color:#60A5FA;font-size:10px">pool</span>':fmtAEDExact(d.alloc)}</td><td style="text-align:right">${fmtAEDExact(d.spent)}</td><td style="text-align:right">${isPooled?'<span style="color:#60A5FA;font-size:10px">pool</span>':fmtAEDExact(d.leftover)}</td><td style="text-align:right;font-weight:800;color:${vClr}">${d.roi?d.roi.toFixed(2)+'×':'—'}<div style="font-size:8px;color:${t.momChg==null?T.secondary:pctClr(t.momChg)}">${t.momChg!=null?'MoM '+fmtPct(t.momChg):''}</div></td><td style="text-align:right">${t.calcBid!=null?'AED '+t.calcBid.toFixed(2):'—'}</td><td style="text-align:right">${d.ftu||0}</td>${showInvestCol?`<td style="text-align:right">${recCell}</td>`:''}</tr>`;
    return bannerRow+row;
  }).join('');
  })();

  // For brands with ANY pooled rows: add the ACTUAL pool total (computed once above) to the
  // running totals. Separate rows already added their own budgets during the loop. This correctly
  // handles pure-pooled, pure-separate, AND mixed brands.
  if(hasSomePooled){
    tBudget+=poolTotalAlloc;
    tLeftover+=Math.max(0,poolTotalAlloc-poolTotalSpent);
  }

  // Capture the table data for export (raw numbers, exactly what's filtered on screen).
  cpcExportData={
    ag,brand,month:cpcMonthLabel(selMonth),
    rows:tableRows.map(t=>({
      outlet:t.outlet,verdict:t.disp.verdict||"",
      clicks:t.disp.views||0,orders:t.disp.orders||0,sales:Math.round(t.disp.sales||0),
      aov:t.disp.aov?Math.round(t.disp.aov):"",cto:t.disp.cto!=null?t.disp.cto.toFixed(1):"",
      budget:Math.round(t.disp.alloc||0),spent:Math.round(t.disp.spent||0),leftover:Math.round(t.disp.leftover||0),
      roas:t.disp.roi?t.disp.roi.toFixed(2):"",mom:t.momChg!=null?t.momChg.toFixed(1):"",vsYear:t.yoyChg!=null?t.yoyChg.toFixed(1):"",
      bid:t.calcBid!=null?t.calcBid.toFixed(2):"",ftu:t.disp.ftu||0,
      rec:(()=>{if(!isCurrentMonth)return"";const bidOpt=cpcDeliverooBidOpt(ag,brand,t.outlet,t.liveRow,t.calcBid);const isPooled=(t.liveRow&&t.liveRow.budgetType==="combined");const bits=[];if(isPooled){if(poolRec){if(poolRec.mode==='active'&&poolRec.additional>0&&poolHasSomeGoodVerdict)bits.push(`Pool dry in ${poolRec.daysUntilDry}d — top up +AED ${poolRec.additional} at brand level`);else if(poolRec.mode==='restart'&&poolHasSomeGoodVerdict)bits.push(`Pool exhausted — restart +AED ${poolRec.additional} at brand level`);else if(poolRec.mode==='active'&&poolRec.additional<=0)bits.push("Pool covers month");else if(poolRec.mode==='restart'&&!poolHasSomeGoodVerdict)bits.push("Pool below BE — don't restart");}}else{const inv=cpcInvestRec(ag,brand,t.outlet,t.liveRow,bidOpt);if(inv){if(inv.mode==="active"&&inv.additional>0&&(t.disp.verdict==="SCALE"||t.disp.verdict==="INVEST"))bits.push(`Top up AED ${inv.additional}`);else if(inv.mode==="restart"&&(t.disp.verdict==="SCALE"||t.disp.verdict==="INVEST")&&inv.additional>0)bits.push(`Restart AED ${inv.additional}`);else if(t.disp.verdict==="WITHDRAW")bits.push("Below BE — don't add");if(inv&&inv.mode==="active"&&inv.additional<=0){const pace=cpcPacingRec(ag,t.disp,t.calcBid);if(pace&&pace.goodROI)bits.push(`Underpacing ${pace.pacePct}% — raise bid${pace.suggestedBid?` to AED ${pace.suggestedBid.toFixed(2)}`:''} to use full budget`);else if(pace)bits.push(`Underpacing ${pace.pacePct}% — consider reallocating ~AED ${pace.projUnspent}`);}}}if(bidOpt&&bidOpt.suggestedBid&&ag==="Deliveroo"&&bidOpt.direction!=='hold')bits.push(`Bid ${bidOpt.direction} to AED ${bidOpt.suggestedBid.toFixed(2)}`);return bits.join("; ");})()
    })),
    totals:null // filled after totals computed below
  };

  // Totals row (weighted ROAS/AOV/CTO/bid)
  const totRoas=tSpent>0?(tSales/tSpent):null;
  const totAov=tOrders>0?(tSales/tOrders):null;
  const totCto=tClicks>0?((tOrders/tClicks)*100):null;
  const totBid=tClicks>0?(tSpent/tClicks):null;
  // Fill export totals now that they're computed
  if(cpcExportData)cpcExportData.totals={label:"TOTAL",clicks:tClicks,orders:tOrders,sales:Math.round(tSales),aov:totAov?Math.round(totAov):"",cto:totCto!=null?totCto.toFixed(1):"",budget:Math.round(tBudget),spent:Math.round(tSpent),leftover:Math.round(tLeftover),roas:totRoas?totRoas.toFixed(2):"",bid:totBid!=null?totBid.toFixed(2):"",ftu:tFtu,invest:isCurrentMonth&&tInvest>0?tInvest:""};
  const totalsRow=`<tr style="border-top:2px solid rgba(245,158,11,.4);background:rgba(245,158,11,.04);font-weight:800"><td style="color:#f59e0b">${isAllPooled?"BRAND POOL TOTAL":isMixed?"TOTAL (incl. pool)":"TOTAL"}</td><td></td><td style="text-align:right;color:${T.text}">${tClicks.toLocaleString()}</td><td style="text-align:right;color:${T.text}">${tOrders.toLocaleString()}</td><td style="text-align:right;color:${T.text}">${fmtAEDExact(tSales)}</td><td style="text-align:right;color:${T.text}">${totAov?totAov.toFixed(0):'—'}</td><td style="text-align:right;color:${T.text}">${totCto!=null?totCto.toFixed(1)+'%':'—'}</td><td style="text-align:right;color:${T.text}">${fmtAEDExact(tBudget)}</td><td style="text-align:right;color:${T.text}">${fmtAEDExact(tSpent)}</td><td style="text-align:right;color:${T.text}">${fmtAEDExact(tLeftover)}</td><td style="text-align:right;color:#f59e0b">${totRoas?totRoas.toFixed(2)+'×':'—'}</td><td style="text-align:right;color:${T.text}">${totBid!=null?'AED '+totBid.toFixed(2):'—'}</td><td style="text-align:right;color:${T.text}">${tFtu.toLocaleString()}</td>${showInvestCol?`<td style="text-align:right">${isCurrentMonth&&tInvest>0?`<span style="color:#22C55E;font-weight:800">+${fmtAEDExact(tInvest)}</span>`:''}</td>`:''}</tr>`;

  // Investment summary: when both pool-level and per-outlet top-ups exist, show them split
  // so the user can act on each independently. Pool top-ups go to brand-level (single edit on
  // the aggregator's portal); per-outlet top-ups can be applied row-by-row.
  let investSummary='';
  // Helper to show pool aggregate numbers inline (Alloc / Spent / Leftover) so user can SEE
  // the actual pool state instead of trying to read it across multiple "🔒 pool" row indicators.
  const fmtPoolAgg=()=>{
    if(!poolRec)return'';
    const{poolAlloc,poolSpent,poolLeftover}=poolRec;
    return `<div style="font-size:10px;color:${T.muted};margin-top:3px">Pool: alloc <strong style="color:${T.secondary}">${fmtAEDExact(poolAlloc)}</strong> · spent <strong style="color:${T.secondary}">${fmtAEDExact(poolSpent)}</strong> · leftover <strong style="color:${poolLeftover>0?'#22C55E':'#EF4444'}">${fmtAEDExact(poolLeftover)}</strong></div>`;
  };
  if(isCurrentMonth&&(tInvestPool>0||tInvestSep>0||(poolRec&&poolRec.mode==='active'&&poolRec.additional<=0))){
    const monthLbl=cpcMonthLabel(selMonth);
    const bidAdjNote=ag==='Deliveroo'?' (adjusted for any suggested bid changes)':'';
    const lines=[];
    if(poolRec){
      // Always show the pool row when pooled outlets exist for this brand+ag — even if no
      // top-up is needed (so the user sees the healthy pool state and knows it's covered).
      if(poolRec.additional>0&&poolHasSomeGoodVerdict){
        const label=poolRec.mode==='restart'?'Brand-pool restart needed':'Brand-pool top-up';
        lines.push(`<div style="display:flex;justify-content:space-between;align-items:center;gap:14px;padding:6px 0;border-bottom:1px solid rgba(96,165,250,.15)"><div style="flex:1"><div style="font-size:11px;color:#60A5FA;font-weight:700">🔒 ${label}</div><div style="font-size:10.5px;color:${T.label};margin-top:2px">Edit at the ${ag} brand level — applies to all ${pooledTableRows.length} pooled ${brand} outlets together.</div>${fmtPoolAgg()}</div><div style="font-size:18px;font-weight:800;color:#60A5FA;white-space:nowrap">+${fmtAEDTip(poolRec.additional)}</div></div>`);
      }else{
        // Pool is healthy / covers month → still surface the state so user knows it was considered.
        const stateLbl=poolRec.mode==='restart'
          ?(poolHasSomeGoodVerdict?'Pool needs restart':'Pool exhausted (below BE — don\'t restart)')
          :'Pool covers month';
        const stateClr=poolRec.mode==='restart'?'#EF4444':'#22C55E';
        lines.push(`<div style="display:flex;justify-content:space-between;align-items:center;gap:14px;padding:6px 0;border-bottom:1px solid rgba(96,165,250,.15)"><div style="flex:1"><div style="font-size:11px;color:${stateClr};font-weight:700">🔒 ${stateLbl}</div><div style="font-size:10.5px;color:${T.label};margin-top:2px">${pooledTableRows.length} pooled ${brand} outlets share this budget.</div>${fmtPoolAgg()}</div><div style="font-size:14px;font-weight:700;color:${stateClr};white-space:nowrap">${poolRec.mode==='restart'?'—':'✓'}</div></div>`);
      }
    }
    if(tInvestSep>0){
      lines.push(`<div style="display:flex;justify-content:space-between;align-items:center;gap:14px;padding:6px 0"><div><div style="font-size:11px;color:#22C55E;font-weight:700">Per-outlet top-ups</div><div style="font-size:10.5px;color:${T.label};margin-top:2px">Sum of individually-editable outlet budgets shown in the table above.</div></div><div style="font-size:18px;font-weight:800;color:#22C55E;white-space:nowrap">+${fmtAEDTip(tInvestSep)}</div></div>`);
    }
    const hasBoth=tInvestPool>0&&tInvestSep>0;
    const grandTotal=tInvestPool+tInvestSep;
    const grandRow=hasBoth?`<div style="display:flex;justify-content:space-between;align-items:center;gap:14px;padding-top:8px;margin-top:6px;border-top:1px dashed rgba(34,197,94,.4)"><div style="font-size:11px;color:#86EFAC;font-weight:700;text-transform:uppercase;letter-spacing:.6px">💰 Total additional investment</div><div style="font-size:24px;font-weight:800;color:#22C55E;white-space:nowrap">+${fmtAEDTip(grandTotal)}</div></div>`:'';
    const introBlurb=hasBoth
      ?`<div style="font-size:11px;color:${T.label};margin-bottom:4px">${brand} on ${ag} has BOTH pooled and per-outlet budgets — actions are split below. Recommendations cover through ${monthLbl}${bidAdjNote}.</div>`
      :tInvestPool>0
        ?`<div style="font-size:11px;color:${T.label};margin-bottom:4px">Brand-level pooled budget for ${brand} on ${ag}. Top up the pool by this amount to keep campaigns running through ${monthLbl}.</div>`
        :tInvestSep>0
          ?`<div style="font-size:11px;color:${T.label};margin-bottom:4px">Per-outlet top-ups to keep all under-funded ${brand} outlets on ${ag} running through ${monthLbl}${bidAdjNote}.</div>`
          :`<div style="font-size:11px;color:${T.label};margin-bottom:4px">${brand} on ${ag} — pool status shown below. All separate-budget outlets cover the month.</div>`;
    investSummary=`<div style="margin-top:12px;padding:12px 16px;background:linear-gradient(135deg,rgba(34,197,94,.08),rgba(34,197,94,.02));border:1px solid rgba(34,197,94,.3);border-radius:10px">${introBlurb}${lines.join('')}${grandRow}</div>`;
  }

  // Contextual note above the table. If the brand on this aggregator has any pooled rows, mention it.
  // Uses the actual data mix rather than hardcoding by aggregator.
  const rowsHavePool=tableRows.some(t=>t.liveRow&&t.liveRow.budgetType==="combined");
  const rowsHaveSep =tableRows.some(t=>t.liveRow&&t.liveRow.budgetType==="separate");
  const poolNote=rowsHavePool
    ?`<div style="font-size:11px;color:${T.label};margin-bottom:12px;padding:8px 12px;background:rgba(96,165,250,.06);border-left:3px solid #60A5FA;border-radius:4px">ℹ️ ${rowsHaveSep?`Some ${brand} outlets on ${ag} have <strong>pooled budgets</strong> (🔒) — those can only be topped up at brand level. Others are <strong>individually editable</strong>.`:`${brand} budgets on ${ag} are <strong>pooled at brand level</strong>. Per-outlet budget/spent are indicative; the brand total is the real budget. Per-outlet <strong>results</strong> (orders, sales, ROAS, CTO) are exact.`}</div>`
    :'';
  const bidNote=ag==="Deliveroo"?`<div style="font-size:11px;color:${T.label};margin-bottom:10px">Bid suggestions analyze the past 6 months and target the bid with the best balance of ROAS and order volume. Changing the bid shifts the burn rate proportionally, and the extra budget needed is recalculated accordingly.</div>`:`<div style="font-size:11px;color:${T.label};margin-bottom:10px">${ag} uses auto-bidding, so only budget recommendations are shown. 📉 = sales dropped after a CPC ended.</div>`;

  return controlBar+poolNote+`<div class="card"><div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px;flex-wrap:wrap"><div class="ct" style="margin-bottom:0">${brand} on ${ag} — Outlet Performance · ${cpcMonthLabel(selMonth)}${isCurrentMonth?' (current month)':''}</div><div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap"><span style="font-size:10px;color:${T.muted}" title="Most recent date in the underlying sales data. Reinvestment figures recompute live based on today's real calendar date, so re-render the page just before you act on a recommendation.">📅 Data as of ${fmtShort(latest)}${isCurrentMonth?` · live (recalculated from today's date)`:''}</span><button onclick="cpcExportTable()" style="background:rgba(34,197,94,.1);border:1px solid rgba(34,197,94,.35);border-radius:6px;color:#22C55E;padding:5px 12px;font-size:11px;cursor:pointer;font-weight:600;white-space:nowrap;display:inline-flex;align-items:center;gap:5px">⬇ Export to Excel</button></div></div><div style="margin-top:8px">${bidNote}</div><div style="overflow-x:auto"><table class="tbl"><thead><tr><th style="cursor:pointer" onclick="cpcSetSort('outlet')">Outlet${arrow('outlet')}</th><th>Verdict</th>${th('clicks','Clicks')}${th('orders','Orders')}${th('sales','Sales')}${th('aov','AOV')}${th('cto','CTO')}${th('budget','Budget')}${th('spent','Spent')}${th('leftover','Leftover')}${th('roas','ROAS')}${th('bid','Avg Bid')}${th('ftu','FTU')}${showInvestCol?`<th style="text-align:right">Invest / Bid</th>`:''}</tr></thead><tbody>${body}${totalsRow}</tbody></table></div>${investSummary}</div>`;
}

// Combine multiple CPC rows into one record (Σsales/Σspent for ROI, Σorders/Σclicks for CTO)
function cpcCombineRows(rows,brand,ag){
  if(!rows||!rows.length)return null;
  let sales=0,spent=0,orders=0,views=0,ftu=0,alloc=0,leftover=0;
  rows.forEach(r=>{sales+=r.sales;spent+=r.budgetSpent;orders+=r.orders;views+=r.views;ftu+=r.ftu;alloc+=r.budgetAlloc;leftover+=r.leftover;});
  const be=cpcBE(brand,ag);
  const roi=spent>0?sales/spent:null;
  return{sales,spent,orders,views,ftu,alloc,leftover,be,roi,cto:views>0?(orders/views)*100:null,aov:orders>0?sales/orders:null,verdict:cpcVerdict(roi,be)};
}
function cpcPrevMonth(m){const [y,mo]=m.split("-").map(Number);const d=new Date(y,mo-2,1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`;}
function cpcMonthLabel(m){if(!m)return '';const [y,mo]=m.split("-").map(Number);const names=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];return `${names[mo-1]} ${String(y).slice(2)}`;}

// Outlet detail modal-ish view (full history)
let cpcOutletDetail=null;
function cpcOpenOutletDetail(ag,brand,outletEnc){
  const outlet=decodeURIComponent(outletEnc);
  cpcOutletDetail={ag,brand,outlet};
  renderCPCOutletDetail();
}
function cpcCloseOutletDetail(){cpcOutletDetail=null;renderCPC();}
function renderCPCOutletDetail(){
  const pg=document.getElementById("page-cpc");if(!pg||!cpcOutletDetail)return;
  const T=cpcTheme();
  const {ag,brand,outlet}=cpcOutletDetail;
  const rows=cpcData.filter(r=>r.aggregator===ag&&r.brand===brand&&r.branch===outlet).sort((a,b)=>(b.startDate||'').localeCompare(a.startDate||'')); // NEW → OLD
  const histRows=rows.map(r=>{
    const vClr=r.verdict?CPC_VC[r.verdict]:T.muted;
    const imp=cpcModel.postImpact.get(r);
    const impCell=imp?`<span style="color:${pctClr(imp.salesChg)};font-weight:700">${fmtPct(imp.salesChg)}</span>`:`<span style="color:${T.secondary}">—</span>`;
    return `<tr><td style="font-size:10px">${r.adType}</td><td style="font-size:10px">${cpcMonthLabel(r.month)}</td><td style="font-size:10px">${r.startDate} → ${r.endDate}</td><td style="text-align:right">${fmtAEDTip(r.budgetAlloc)}</td><td style="text-align:right">${fmtAEDTip(r.budgetSpent)}</td><td style="text-align:right">${fmtAEDTip(r.sales)}</td><td style="text-align:right">${r.orders}</td><td style="text-align:right">${r.cto.toFixed(1)}%</td><td style="text-align:right;font-weight:800;color:${vClr}">${r.roi?r.roi.toFixed(2)+'×':'—'}</td><td><span style="padding:2px 7px;border-radius:6px;background:${CPC_VB[r.verdict]||'rgba(100,116,139,.1)'};color:${vClr};font-size:9px;font-weight:700">${r.verdict||'—'}</span></td><td style="text-align:right">${impCell}</td></tr>`;
  }).join('');
  const bClr=BMAP[brand]?.c||'#f59e0b';
  const header=`<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;padding-bottom:12px;border-bottom:1px solid ${T.border}"><div><div style="font-size:9px;color:#FBBF24;font-weight:800;letter-spacing:1.5px;text-transform:uppercase">Outlet Deep Dive</div><div style="font-size:18px;font-weight:800;color:${bClr};margin-top:4px">${brand} · ${outlet}</div><div style="font-size:11px;color:${T.label};margin-top:2px"><span style="color:${AGG_LOGO_CLR[ag]||'#888'};font-weight:700">${ag}</span> · ${rows.length} CPC cycle${rows.length>1?'s':''} (newest first)</div></div><button onclick="cpcCloseOutletDetail()" style="background:none;border:1px solid ${T.border};border-radius:6px;color:${T.label};padding:5px 12px;font-size:11px;cursor:pointer">← Back</button></div>`;
  pg.innerHTML=cpcShell(header+`<div class="card"><div class="ct">📜 CPC History — Newest to Oldest</div><div style="overflow-x:auto"><table class="tbl"><thead><tr><th>Type</th><th>Month</th><th>Window</th><th style="text-align:right">Budget</th><th style="text-align:right">Spent</th><th style="text-align:right">Sales</th><th style="text-align:right">Orders</th><th style="text-align:right">CTO</th><th style="text-align:right">ROAS</th><th>Verdict</th><th style="text-align:right">Post Δ</th></tr></thead><tbody>${histRows}</tbody></table></div></div>`);
}


// ── LOCAL BRIEF (always works, even off Claude.ai) ──
// Computes wins/issues directly from the data so the morning brief is never blank.
function computeLocalBrief(){
  const ld=getLD(),pd=getPD(),ls=sumR(ld),ps=sumR(pd);
  const oc=pctOf(ls.orders,ps.orders),sc=pctOf(ls.sales,ps.sales);
  const cm=mkMap(ld,r=>`${r.brand}|${r.branch}|${r.aggregator}`),pm=mkMap(pd,r=>`${r.brand}|${r.branch}|${r.aggregator}`);
  const changes=Object.values(cm).map(c=>{const[brand,branch,aggregator]=c.k.split("|");const pv=pm[c.k];return{brand,branch,aggregator,orders:c.orders,sales:c.sales,oc:pv?pctOf(c.orders,pv.orders):null};});
  const wins=[...changes].filter(x=>x.oc!=null&&x.orders>=3).sort((a,b)=>b.oc-a.oc).slice(0,3);
  const issues=[...changes].filter(x=>x.oc!=null&&x.oc<-15&&x.orders>=2).sort((a,b)=>a.oc-b.oc).slice(0,3);
  const zeros=Object.keys(pm).filter(k=>pm[k].orders>=3&&!cm[k]).map(k=>k.split("|")).slice(0,3);
  const byBrand=BR.map(b=>{const c=sumR(ld.filter(r=>r.brand===b.n));const p=sumR(pd.filter(r=>r.brand===b.n));return{n:b.n,o:c.orders,oc:pctOf(c.orders,p.orders)};}).filter(b=>b.o>0);
  const bestBrand=[...byBrand].filter(b=>b.oc!=null).sort((a,b)=>b.oc-a.oc)[0];
  const worstBrand=[...byBrand].filter(b=>b.oc!=null).sort((a,b)=>a.oc-b.oc)[0];
  return{ls,ps,oc,sc,wins,issues,zeros,bestBrand,worstBrand};
}
function localBriefHTML(){
  const b=computeLocalBrief();
  const dirWord=b.oc==null?"flat":b.oc>=0?"up":"down";
  const headline=`Group ${dirWord} ${fmtPct(b.oc)} on orders, ${fmtPct(b.sc)} on Net Sales vs ${getCompShort().replace('vs ','')}.`;
  const winLines=b.wins.length?b.wins.map(w=>`<div style="font-size:12px;margin-bottom:4px;line-height:1.5">• <strong>${w.brand} ${w.branch}</strong> on ${w.aggregator}: ${fmtPct(w.oc)} (${w.orders} orders)</div>`).join(""):`<div style="font-size:12px;color:#475569;font-weight:600">No standout gainers in this window.</div>`;
  const issueLines=(b.issues.length||b.zeros.length)?[...b.issues.map(w=>`<div style="font-size:12px;margin-bottom:4px;line-height:1.5">• <strong>${w.brand} ${w.branch}</strong> on ${w.aggregator}: ${fmtPct(w.oc)}</div>`),...b.zeros.map(z=>`<div style="font-size:12px;margin-bottom:4px;line-height:1.5">• <strong>${z[0]} ${z[1]}</strong> on ${z[2]}: <span style="color:#EF4444;font-weight:700">ZERO orders</span> (had sales last period)</div>`)].join(""):`<div style="font-size:12px;color:#22C55E">Nothing alarming — no major drops or zero-order outlets.</div>`;
  const brandLine=b.bestBrand&&b.worstBrand?`Best brand: <strong style="color:${BMAP[b.bestBrand.n]?.c}">${b.bestBrand.n}</strong> ${fmtPct(b.bestBrand.oc)}. Weakest: <strong style="color:${BMAP[b.worstBrand.n]?.c}">${b.worstBrand.n}</strong> ${fmtPct(b.worstBrand.oc)}.`:"";
  return `<div style="font-size:15px;font-weight:700;color:#FCD34D;margin-bottom:12px;line-height:1.4">${headline}</div>
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px;margin-bottom:12px">
      <div><div style="font-size:10px;font-weight:700;color:#22C55E;text-transform:uppercase;letter-spacing:.8px;margin-bottom:6px">✅ What Worked</div>${winLines}</div>
      <div><div style="font-size:10px;font-weight:700;color:#EF4444;text-transform:uppercase;letter-spacing:.8px;margin-bottom:6px">⚠️ Needs Attention</div>${issueLines}</div>
    </div>
    ${brandLine?`<div style="background:rgba(245,158,11,.07);border:1px solid rgba(245,158,11,.2);border-radius:6px;padding:8px 12px;font-size:12px;color:#FDE68A;line-height:1.6">💡 ${brandLine}</div>`:""}`;
}

// LOCAL BRIEF — computed instantly from your data, no API calls
async function genBrief(){
  const el=document.getElementById("brief-content");if(!el)return;
  el.innerHTML=localBriefHTML();
}
async function runAskAI(){
  const input=document.getElementById('ai-ask-input'),btn=document.getElementById('ai-ask-btn'),answer=document.getElementById('ai-ask-answer');
  if(!input||!answer)return;const q=input.value.trim();if(!q)return;
  if(btn){btn.textContent='⏳';btn.disabled=true;}
  answer.innerHTML=`<div style="margin-top:10px;font-size:11px;color:#94a3b8;font-style:italic">🤔 Thinking...</div>`;
  const ld=getLD(),pd=getPD(),ls=sumR(ld),ps=sumR(pd);
  const byBrand=BR.map(b=>{const c=sumR(ld.filter(r=>r.brand===b.n));const p=sumR(pd.filter(r=>r.brand===b.n));return`${b.n}: ${c.orders} orders AED ${c.sales.toFixed(0)} (WoW ${fmtPct(pctOf(c.orders,p.orders))})`;}).join('; ');
  const byPlat=AGGS.map(a=>{const c=sumR(ld.filter(r=>r.aggregator===a));return`${a}: ${c.orders} orders`;}).join('; ');
  const prompt=`BD analyst for Oregano Restaurants UAE. DATA ${getPeriodLabel()} vs ${getCompLabel()}: Total ${ls.orders} orders AED ${ls.sales.toFixed(0)} (WoW orders ${fmtPct(pctOf(ls.orders,ps.orders))}). BY BRAND: ${byBrand}. BY PLATFORM: ${byPlat}. QUESTION: ${q}. Answer in 2-4 sentences with specific numbers. No preamble.`;
  try{
    const r=await fetch("https://api.anthropic.com/v1/messages",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({model:"claude-sonnet-4-20250514",max_tokens:500,messages:[{role:"user",content:prompt}]})});
    if(!r.ok)throw new Error('cors');const j=await r.json();if(j.error)throw new Error(j.error.message);
    const ans=(j.content?.[0]?.text||'').trim();
    answer.innerHTML=`<div style="margin-top:10px;padding:10px 12px;background:rgba(96,165,250,.08);border:1px solid rgba(96,165,250,.25);border-radius:6px;line-height:1.6;font-size:12px"><div style="font-size:10px;color:#60A5FA;font-weight:700;margin-bottom:5px">💬 ${q}</div><div style="white-space:pre-wrap;color:#0F172A">${ans.replace(/</g,'&lt;')}</div></div>`;
    input.value='';
  }catch(e){answer.innerHTML=`<div style="margin-top:10px;padding:10px 12px;background:rgba(239,68,68,.05);border:1px solid rgba(239,68,68,.2);border-radius:6px;font-size:12px;color:#94a3b8">⚠️ AI chat only works in Claude.ai (CORS restriction on external hosts). The morning brief above is computed locally and always works.</div>`;}
  if(btn){btn.textContent='Ask →';btn.disabled=false;}
}

// ── CAMPAIGN MANAGER ──────────────────────────────────────────────────────
const CAMPAIGN_GID="1647275459";
let campaignData=[],campLoaded=false,campTab='browse',selCamp=null;
// v332: switched from multi-select to exclusive (single-select) status filtering, per Nikhil's
// explicit choice on the Campaigns-page speed options — viewing Active+Upcoming+History
// simultaneously meant every visible campaign across all three sections ran campAnalysisV2
// synchronously before the page painted anything; with 30+ active campaigns typical this
// session, that's real, avoidable first-paint cost. Since realistically one section is viewed
// at a time anyway, this cuts the typical synchronous work by up to two-thirds with no loss of
// real functionality — clicking a status now shows only that one, like a tab, instead of
// toggling membership in a set.
let campStatusFilter=new Set(['active']);
function campToggleStatus(status){
  campStatusFilter=new Set([status]); // exclusive — replaces the whole selection, not a toggle
  campTab='browse';
  renderCampaigns();
}
// Campaign analysis cache — campAnalysisV2 scans allData repeatedly, so memoize per campaign.
// Keyed by campaign index + elasticity + latest date. Cleared when data reloads.
let campAnalysisCache=new Map();
// Memoization for observedCampaignRatio (v072) — significant campaign-page speed-up.
// Invalidated whenever an exact upload changes (each clearXxxData / merge already resets
// campAnalysisCache; we hook the same points to clear this cache too).
let _observedRatioCache=new Map();
let campModelBuilt=false,campModelBuilding=false;
let campReturnTab='browse'; // which tab to return to when leaving the deep-dive
// ── CPC INVESTMENTS STATE ──
const CPC_GID="2056065310";
let cpcData=[],cpcLoaded=false;
let campFBrands=new Set(),campFPlatforms=new Set(),campFStatuses=new Set(),campFBranches=new Set();
let campSearchQ='',campQuickFilter='all',campCardSort='contribution';
// Date and outlet-scope filters for the campaign list
let campFStartFrom="",campFStartTo="",campFOutletScope="all"; // outlet scope: all/dxb/auh/specific
let campSort={col:'startDate',dir:-1};
const BRAND_NORM={'oregano':'Oregano','lollorosso':'Lollorosso','lollo rosso':'Lollorosso','lollarosso':'Lollorosso','smokeys':'Smokeys',"smokey's":'Smokeys','smokey':'Smokeys','smokeys pizzeria':'Smokeys','fyoozhen':'Fyoozhen','fyoo zhen':'Fyoozhen','fyoo-zhen':'Fyoozhen','fyooshen':'Fyoozhen','wicked wings':'Wicked Wings','wckd wings':'Wicked Wings','wkd wings':'Wicked Wings','all brands':'All Brands','all':'All Brands'};
const AGG_NORM={'deliveroo':'Deliveroo','talabat':'Talabat','noon':'Noon','careem':'Careem','keeta':'Keeta','smiles':'Smiles','instashop':'Instashop','insta shop':'Instashop','google maps':'Google Maps','google map':'Google Maps','google':'Google Maps'};
const EXCLUDED_BRANDS=new Set(['burgerstack','burger stack']);
function normBrand(s){
  if(!s)return'';
  const lc=s.trim().toLowerCase();
  if(BRAND_NORM[lc])return BRAND_NORM[lc];
  // Fuzzy: cell may contain the brand plus extra text (e.g. "Fyoozhen DIP", "FYOO", "Oregano Pizzeria").
  // Match against known brand keywords so a decorated header still resolves to the canonical brand.
  if(/\bfyoo/.test(lc))return'Fyoozhen';
  if(/\boregano\b/.test(lc))return'Oregano';
  if(/\blollo\s*rosso\b|\blollorosso\b|\blollo\b/.test(lc))return'Lollorosso';
  if(/\bsmokey/.test(lc))return'Smokeys';
  if(/\bwicked\b|\bwckd\b|\bwkd\b/.test(lc)&&/wing/.test(lc))return'Wicked Wings';
  return s.trim();
}
function normAgg(s){if(!s)return'';const cleaned=s.trim().replace(/[\s\-_]*\d{3,}\s*$/,"").trim();const lc=cleaned.toLowerCase();return AGG_NORM[lc]||cleaned;}
function parseCampaigns(csv){
  const rows=parseCSV(csv);if(rows.length<2)return[];
  const recs=[];
  for(let i=1;i<rows.length;i++){
    const row=rows[i];
    if(!row[0]?.trim()&&!row[1]?.trim())continue;
    if((row[7]?.trim()||'').toLowerCase()==='cancelled')continue;
    const brandRaw=(row[1]||'').trim();
    if(EXCLUDED_BRANDS.has(brandRaw.toLowerCase()))continue;
    const sd=parseDate(row[2]),ed=parseDate(row[3]);
    if(!sd||!ed)continue;
    const brandFinal=normBrand(brandRaw);
    let outletFinal=row[4]?.trim()||'All';
    if(brandFinal==='Fyoozhen'&&/^dip$/i.test(outletFinal))outletFinal='DIP (Fyoozhen)';
    recs.push({aggregator:normAgg(row[0]),brand:brandFinal,startDate:dk(sd),endDate:dk(ed),outlet:outletFinal,comments:row[5]?.trim()||'',name:row[6]?.trim()||'',status:row[7]?.trim()||'Completed',validity:row[8]?.trim()||'',addons:[]});
  }
  return mergeKeetaFDAddons(recs);
}
function mergeKeetaFDAddons(recs){
  // Detect Keeta "Free Delivery" campaigns that should be merged as addons to a parent
  // discount campaign. These are rows whose ENTIRE PURPOSE is the FD subsidy — NOT regular
  // discount campaigns that happen to mention "+ FD (AED 2)" as a cost-sharing footnote.
  //
  // Pre-v068 bug: the regex `\bFD\b` matched "50% OFF CAP 30 + FD (AED 2)" → silently
  // deleted 6 of 11 Keeta campaigns from campaignData. The comment footnote "FD (AED 2)"
  // means "this campaign also includes a free-delivery cost share of AED 2 per order" — it's
  // NOT a free-delivery campaign. Real FD-only campaigns have names like "Free Delivery" or
  // "FD" with nothing else substantive.
  //
  // New rule: a campaign is FD-only if its NAME (not comment) is essentially just "FD" or
  // "Free Delivery" — possibly with a brand suffix. Comment text is ignored for classification.
  const isFD=c=>{
    if(c.aggregator!=='Keeta')return false;
    const name=(c.name||'').trim().toLowerCase();
    // Match names that are purely about free delivery:
    //   "FD", "FD AED 2", "Free Delivery", "Keeta FD", etc.
    // Do NOT match: "50% OFF CAP 30", "25% OFF Select Items", "OFU Item Keeta", etc.
    return /^(keeta\s+)?f\.?d\.?(\s|$)/i.test(name) || /^free\s*delivery/i.test(name);
  };
  const fdRows=recs.filter(isFD),nonFD=recs.filter(c=>!isFD(c));
  fdRows.forEach(fd=>{const parent=nonFD.find(p=>p.aggregator==='Keeta'&&p.brand===fd.brand&&p.startDate<=fd.endDate&&p.endDate>=fd.startDate);if(parent){parent.addons=parent.addons||[];parent.addons.push({name:'FD AED 2',comments:fd.comments,startDate:fd.startDate,endDate:fd.endDate});}else{nonFD.push(fd);}});
  return nonFD;
}
function campStatus(c){
  const sheetStatus=(c.status||'').trim().toLowerCase();
  if(sheetStatus==='cancelled'||sheetStatus==='canceled')return'Cancelled';
  const today=dk(new Date());
  // An explicit "Completed" from the sheet is authoritative — the user marked it ended (handles
  // single-day campaigns whose start=end=today, which pure date math would call "Running").
  if(sheetStatus==='completed'||sheetStatus==='ended'||sheetStatus==='finished')return'Completed';
  // Otherwise compute from dates. A campaign past its end date is Completed even if the sheet
  // still says "Running" (the sheet status can be stale).
  if(c.startDate>today)return'Upcoming';
  if(c.endDate<today)return'Completed';
  return'Running';
}
// ── LOCATION-AWARE CAMPAIGN ANALYSIS ──
// Many campaigns target only specific locations (DXB = Dubai outlets, AUH = Abu Dhabi outlets,
// or a single branch like "NAS"). When that's the case we MUST compare those outlets vs only
// those same outlets in the baseline — comparing them to all-outlet totals would compare apples
// to oranges. campOutlets() resolves the outlet field on a campaign record to the set of actual
// branch names from allData that the campaign applies to.
const AUH_OUTLETS=new Set(["Al Forsan","Al Reem","Reem Island","WTC","Al Reef"]); // Abu Dhabi branches
// v261: Deliveract POS FD-inclusion adjustment — replaced the v260 flat "AED 2 x orders" guess
// with rates measured directly from real data: full Keeta "Recent Orders" statements (Apr 1 –
// Aug 9 2026, ~24,000 completed orders) cross-referenced day-by-day against the sheet's own
// Keeta discount figures for the same dates. Two things came out of that reconciliation:
//   1. The leakage was never a flat AED 2/order — it grew steadily as order volume migrated
//      from Grubtech to Deliveract, from ~AED 0.05-0.30/order in April to ~AED 1.8-2.3/order by
//      early August (right at the AED 2 FD ceiling, i.e. near-full migration), before the Aug
//      10 fix. The old flat guess badly OVER-corrected April-June (real leakage was under 15%
//      of AED 2 there) and slightly UNDER-corrected the last days before the fix.
//   2. Confirmed-unaffected brands (Fyoozhen, Wicked Wings) showed no consistent bias in the
//      same reconciliation — their variance was reconciliation noise (refund timing, day
//      cutoff), not a real leakage — confirming they're correctly excluded from this table.
// Rates are per calendar month, except August is split into "2026-08-pre" (Aug 1-9 only) so the
// mid-day Aug 10 cutover isn't diluted by averaging in the already-fixed days. Every rate below
// is a direct measured value from that reconciliation — not modeled or interpolated. A
// brand/month with no verified rate (including everything from Aug 10 onward, and any month
// outside this window) returns 0 — same "safer to under-correct than invent a number" principle
// as v260. This is a POS-level issue (affects what got reported to the sheet before it was even
// uploaded), not aggregator-specific, so the adjustment still applies uniformly across every
// aggregator being compared. Global (not scoped to one function) so both the Discrepancy-by-
// outlet table and the original Uncategorized Burn tile apply it consistently.
const DELIVERACT_FD_RATE_TABLE={
  "Oregano":{"2026-04":0.052,"2026-05":0.109,"2026-06":0.174,"2026-07":0.863,"2026-08-pre":1.817},
  "Lollorosso":{"2026-04":0.303,"2026-05":0.294,"2026-06":0.287,"2026-07":0.909,"2026-08-pre":2.117},
  "Smokeys":{"2026-04":0.274,"2026-05":0.964,"2026-06":1.656,"2026-07":0.506,"2026-08-pre":2.321}
};
const DELIVERACT_FD_CUTOFF='2026-08-10'; // confirmed clean from this date onward — see note above
function deliveractFdAdjustment(brand,date,orders){
  const byBrand=DELIVERACT_FD_RATE_TABLE[brand];
  if(!byBrand)return 0;
  if(date>=DELIVERACT_FD_CUTOFF)return 0;
  const ym=date.slice(0,7);
  const period=(ym==='2026-08')?'2026-08-pre':ym;
  const rate=byBrand[period];
  if(rate==null)return 0; // no verified rate for this month — assume clean rather than guess
  return rate*(orders||0);
}

// ── BRANCH ALIAS RESOLVER ──
// Common shortenings/typos users put in campaign comments. Maps a lowercased alias
// to a canonical token to look up in the brand's actual branch list. Resolution is
// case-insensitive and falls back to fuzzy contains-match if no alias hit.
const BRANCH_ALIASES={
  "dmc":"dmc","dubai media city":"dmc","media city":"dmc",
  "motorcity":"motorcity","motor city":"motorcity","mc":"motorcity",
  "mirdif":"mirdiff","mirdiff":"mirdiff",
  "tsqr":"town square","town square":"town square","tq":"town square",
  "fyoo dip":"dip (fyoozhen)","fyoozhen dip":"dip (fyoozhen)","fyoozhen-dip":"dip (fyoozhen)",
  "fyoo-dip":"dip (fyoozhen)","fyoo - dip":"dip (fyoozhen)","fyoodip":"dip (fyoozhen)",
  "reem":"al reem","reem island":"al reem","al reem":"al reem",
  "wtc":"wtc","al forsan":"al forsan","forsan":"al forsan",
  "al reef":"al reef","reef":"al reef",
  "nas":"nas","nad al sheba":"nas",
  "marina":"marina","dso":"dso","dubai silicon oasis":"dso",
  "furjan":"furjan","al quoz":"al quoz","quoz":"al quoz","qouz":"al quoz","al qouz":"al quoz","aq":"al quoz",
  "dip":"dip","villa":"villa","jumeirah":"jumeirah","jumearah":"jumeirah","jumierah":"jumeirah","wasl":"jumeirah","al wasl":"jumeirah",
  "ts":"town square","fj":"furjan","al furjan":"furjan"
};
// Tokens that frequently appear inside "Except X, Y, Z" lists but are NOT branch names —
// menu item types, customer segments, pricing rules, etc. Without this filter, every "Except
// Combos" / "FTU Only" / "MOV 50" trips a false "⚠ Needs clarification" warning on cards
// whose comment was actually perfectly clear (just not about branch exclusions).
// Compared lowercase, with punctuation stripped.
const NON_BRANCH_TOKENS=new Set([
  // Menu item categories
  "combos","combo","the combos","the combo","item","items","select items","high cost items",
  "high fcr items","high fcr","high cost","certain sides","sides","water","drinks","beverages",
  "burratas","burrata","byo salad","byo","salad","pizza","pasta","desserts",
  // Customer segments
  "ftu","ftu only","new customers","new customer","lapsed users","lapsed","d+ users","dplus",
  "first time","first time users","existing customers",
  // Pricing / order parameters
  "mov","max cap","cap","entire menu","entire menu)","whole menu",
  // Common trailing scraps from over-captured regex
  "is not an option","since","because"
]);
// Returns true if a token is shape-plausible as a branch name (will be looked up against
// brandBranches). Returns false for clear non-branch tokens so they're silently dropped
// from the parser's unresolved list — preventing false clarification warnings.
function isPlausibleBranchToken(token){
  if(!token)return false;
  const t=token.toLowerCase().trim().replace(/^[\s()[\].,;:]+|[\s()[\].,;:]+$/g,"").trim();
  if(!t||t.length<2)return false;
  if(NON_BRANCH_TOKENS.has(t))return false;
  // Has digits → almost certainly a pricing rule or count ("MOV 50", "AED 30", "10 Items")
  if(/\d/.test(t))return false;
  // Contains % or AED → pricing info
  if(/%|aed\b/i.test(t))return false;
  // More than 3 words → too long to be a branch name (real ones are ≤3 words: "Town Square",
  // "Al Quoz", "Al Reem Island"). Over-captured regex chunks like "All Locations Except Reem"
  // would otherwise leak into unresolved.
  if(t.split(/\s+/).length>3)return false;
  return true;
}
function resolveBranchName(token,brandBranches){
  if(!token)return null;
  // v244: fixed a real, widespread bug — the previous version blindly stripped a trailing ")"
  // (or leading "(") even when it was the closing half of a MEANINGFUL, balanced "(Brand)"
  // suffix like "DIP (Fyoozhen)", mangling it into "dip (fyoozhen" before the alias lookup ever
  // ran. That broken string then fuzzy-matched the wrong outlet ("DIP" instead of the correct
  // "DIP (Fyoozhen)") via a reverse substring check. Confirmed directly: traced through every
  // step of the original regex and reproduced the exact mismatch. Fix: only strip parens when
  // they're genuinely UNBALANCED in the token (the "Reem)" / "(Marina" stray-punctuation case
  // this was originally built for) — a balanced "(...)" is left alone, since removing it can
  // only ever destroy a meaningful qualifier, never a stray character.
  let pre=token.trim();
  const openCount=(pre.match(/\(/g)||[]).length,closeCount=(pre.match(/\)/g)||[]).length;
  if(openCount!==closeCount){
    // Genuinely unbalanced — safe to strip a stray leading/trailing paren, matching original intent
    pre=pre.replace(/^[()]+|[()]+$/g,"");
  }
  const tl=pre.replace(/^[\s[\].,;:]+|[\s[\].,;:]+$/g,"").toLowerCase().replace(/^\s*(only\s+)?(at\s+|in\s+)?/,"").replace(/\s+outlets?$/,"").replace(/\s+branch(es)?$/,"").trim();
  if(!tl)return null;
  const canonical=BRANCH_ALIASES[tl]||tl;
  // Exact match first against the brand's actual branches
  let m=brandBranches.find(b=>b.toLowerCase()===canonical);
  if(m)return m;
  // Try the original token (pre-alias) against branch lower
  m=brandBranches.find(b=>b.toLowerCase()===tl);
  if(m)return m;
  // Whitespace-insensitive match — handles "motor city" vs "Motorcity", "town square" vs
  // "TownSquare", etc. Many user-written comments don't match the dashboard's exact spelling.
  const nows=s=>s.toLowerCase().replace(/\s+/g,"");
  m=brandBranches.find(b=>nows(b)===nows(canonical))||brandBranches.find(b=>nows(b)===nows(tl));
  if(m)return m;
  // Fuzzy contains (only if token is long enough to be specific)
  if(canonical.length>=3){
    m=brandBranches.find(b=>b.toLowerCase().includes(canonical)||canonical.includes(b.toLowerCase()));
    if(m)return m;
  }
  return null;
}

// ── COMMENT PARSER ──
// Extracts structured info from a free-text comment:
//   - Branch exclusions  ("Except: A, B, C" / "Excluding A, B" / "Not valid in X")
//   - Branch inclusions  ("Only in X, Y" / "At X, Y" / "Locations: X, Y")
//   - Co-funding         ("50% co-funded", "60:40 Co-Funding" (brand:platform), "Talabat funds 30%")
//   - Unresolved tokens  (anything in an exclusion/inclusion list that didn't match a known branch)
// The parser is conservative: it only extracts branch lists that follow a clear keyword like
// "Except / Excluding / Only / At / Locations". Free-floating branch names are ignored to avoid
// false positives. Returns: {includeBranches, excludeBranches, coFundedPctOfDiscount, unresolved, hasInfo}
function parseCampComment(c){
  const text=(c.comments||"").trim();
  const result={includeBranches:null,excludeBranches:null,coFundedPctOfDiscount:null,regionOnly:null,unresolved:[],hasInfo:false};
  if(!text)return result;
  const brandBranches=[...new Set(allData.filter(r=>c.brand==="All Brands"||r.brand===c.brand).map(r=>r.branch))].filter(b=>b!=="(brand-level)");
  // ─ Branch exclusions ─
  // Match phrases like "Except: A, B, C" / "Excluding A and B" / "Not valid in X, Y" / "All except X"
  const excPat=/(?:locations?\s+except|all\s+except|except(?:\s+for)?|excluding|not\s+valid\s+(?:in|at|for))\s*[:\-]?\s*([^.\n]+?)(?:\s+since\b|\s+because\b|\s+as\b|\s+because\s+of\b|\.|$|\n)/i;
  const excMatch=text.match(excPat);
  if(excMatch){
    // Split on commas/and/&/+ AND on close-paren — handles "Except Combos) FTU Only" where the
    // regex over-captured into the comment's free-text tail.
    const list=excMatch[1].split(/[,;)]|\s+and\s+|\s+&\s+|\s+\+\s+/i).map(s=>s.trim()).filter(Boolean);
    const resolved=[],unresolved=[];
    list.forEach(tok=>{
      // Skip tokens that clearly aren't branch names (item categories, pricing rules, customer
      // segments) — they're allowed in the comment but don't trigger a clarification warning.
      if(!isPlausibleBranchToken(tok))return;
      const r=resolveBranchName(tok,brandBranches);
      if(r)resolved.push(r);
      else if(tok.length>1)unresolved.push(tok);
    });
    if(resolved.length){result.excludeBranches=new Set(resolved);result.hasInfo=true;}
    if(unresolved.length)result.unresolved.push(...unresolved);
  }
  // ─ Region restriction from the COMMENT (not just the Outlet column) ─
  // Catches "valid only in AUH", "Abu Dhabi outlets only", "DXB only", "Dubai branches only" etc.
  // Sets result.regionOnly so campOutlets can restrict to that region's branches.
  if(!result.excludeBranches&&!result.includeBranches){
    const tl=text.toLowerCase();
    const auhRe=/\b(?:auh|abu\s?dhabi)\b/;
    const dxbRe=/\b(?:dxb|dubai)\b/;
    // Only treat as a restriction when paired with limiting language (only/valid in/exclusive to)
    const limiting=/\b(only|valid\s+(?:in|at|for|only)|exclusive(?:ly)?|restricted\s+to|just)\b/.test(tl);
    if(limiting){
      if(auhRe.test(tl)&&!dxbRe.test(tl)){result.regionOnly="auh";result.hasInfo=true;}
      else if(dxbRe.test(tl)&&!auhRe.test(tl)){result.regionOnly="dxb";result.hasInfo=true;}
    }
  }
  // ─ Branch inclusions ─
  // Match "Only in X, Y" / "Only at X" / "Locations: X, Y" / "Valid at X, Y, Z" /
  // "Select Locations only X, Y" / "Locations only X" / bare "only X, Y" (where X resolves to branches).
  // Skip if we already found an exclusion list to avoid double-processing.
  if(!result.excludeBranches){
    // Try the explicit keyword forms first.
    const incPat=/(?:(?:select\s+|specific\s+)?locations?\s+only|only\s+(?:in|at|for)|locations?\s*[:\-]\s*(?!except)|valid\s+(?:in|at|only\s+in|only\s+at))\s*([^.\n]+?)(?:\s+since\b|\s+because\b|\s+as\b|\.|$|\n)/i;
    let incMatch=text.match(incPat);
    // Fallback: bare "only <list>" where the list resolves to known branches (e.g. "... only Al Quoz, MC, Mirdif")
    if(!incMatch){const bareOnly=text.match(/\bonly\s+([A-Za-z][^.\n]+?)(?:\s+since\b|\s+because\b|\.|$|\n)/i);if(bareOnly)incMatch=bareOnly;}
    if(incMatch){
      const list=incMatch[1].split(/[,;)]|\s+and\s+|\s+&\s+|\s+\+\s+/i).map(s=>s.trim()).filter(Boolean);
      const resolved=[],unresolved=[];
      list.forEach(tok=>{
        if(!isPlausibleBranchToken(tok))return;
        const r=resolveBranchName(tok,brandBranches);
        if(r)resolved.push(r);
        else if(tok.length>1)unresolved.push(tok);
      });
      // For the bare-only fallback, require at least 2 resolved branches to avoid false positives.
      if(resolved.length>=2||(resolved.length>=1&&/locations?\s+only|only\s+(?:in|at|for)/i.test(text))){result.includeBranches=new Set(resolved);result.hasInfo=true;if(unresolved.length)result.unresolved.push(...unresolved);}
    }
  }
  // ─ Fallback: outlet says "Select Locations" but no keyword found ─
  // When the outlet field is a generic phrase like "Select Locations" / "Specific Locations" and
  // we still have no branch info, look for a colon-separated list at the end of the comment and
  // try resolving each token. Only commit if ≥2 tokens resolve to known branches (one match could
  // be coincidence; 2+ is reliable evidence the colon introduces a branch list).
  if(!result.excludeBranches&&!result.includeBranches){
    const outlet=(c.outlet||"").trim().toLowerCase();
    const isGenericOutlet=/^(select|specific|selected)\s+(locations?|branches?|outlets?)/.test(outlet);
    if(isGenericOutlet){
      // Find the LAST colon in the text and parse what follows as a candidate branch list
      const lastColon=text.lastIndexOf(":");
      if(lastColon>-1){
        const tail=text.slice(lastColon+1).trim();
        if(tail.length>1&&tail.length<300){
          const list=tail.split(/[,;]|\s+and\s+|\s+&\s+|\s+\+\s+/i).map(s=>s.trim()).filter(Boolean);
          const resolved=[],unresolved=[];
          list.forEach(tok=>{
            if(!isPlausibleBranchToken(tok))return;
            const r=resolveBranchName(tok,brandBranches);
            if(r)resolved.push(r);
            else if(tok.length>1&&tok.length<25)unresolved.push(tok);
          });
          // Only treat as a branch list if at least 2 tokens resolved AND most resolved
          if(resolved.length>=2&&resolved.length>=Math.ceil(list.length*0.6)){
            result.includeBranches=new Set(resolved);
            result.hasInfo=true;
            if(unresolved.length)result.unresolved.push(...unresolved);
          }
        }
      }
    }
  }
  // ─ Co-funding percentage of discount ─
  // Patterns:
  //   "X% co-funded" / "X% co funded" / "co-funded X%" / "X% cofunded"  → platform funds X%
  //   "X:Y co-funding" / "X:Y co funded"  → brand:platform → platform funds Y%
  //   "<Platform> funds X%" / "<Platform> X%" near "co-fund"  → platform funds X%
  const t=text.toLowerCase();
  // v143: comments that EXPLICITLY name both parties — e.g. "Co-Funded 60% Oregano, 40%
  // Keeta" — were previously misread by the generic "bare X% near co-funded" pattern below,
  // which assumes an unlabeled percentage is always the PLATFORM's share. That's correct when
  // no party is named, but here the sheet explicitly labels 60% as the MERCHANT's (Oregano's)
  // share — the old parser grabbed it anyway and treated it as the platform's share, a straight
  // inversion of who actually funds what. Checked first: find every "NUMBER% <name>" pair in
  // the comment, and if one is explicitly labeled with the campaign's own aggregator name, use
  // THAT percentage as the platform's share — regardless of which number appears first in the
  // sentence. Falls through untouched to the existing patterns below for comments that don't
  // name a specific party (plain ratios, bare percentages).
  if(/co[\s\-]?fund/.test(t)){
    const labelRe=/(\d{1,3})\s*%\s*([a-z][a-z\s]*?)(?=[,;.\-–]|\s+co-?fund|$)/gi;
    const labeled=[];let lm;
    while((lm=labelRe.exec(t))!==null)labeled.push({pct:parseInt(lm[1],10),label:lm[2].trim()});
    const aggLower=(c.aggregator||"").toLowerCase();
    const aggFirstWord=aggLower.split(/\s+/)[0];
    const aggMatch=aggFirstWord?labeled.find(x=>x.label&&(aggLower.startsWith(x.label)||x.label.startsWith(aggFirstWord))):null;
    if(aggMatch&&aggMatch.pct>=0&&aggMatch.pct<=100){
      result.coFundedPctOfDiscount=aggMatch.pct/100;result.hasInfo=true;
    }
  }
  // Ratio form: "A:B co-funding" / "A-B co-funded" / "co-funded A:B" / "co-funded A-B"
  // (brand:platform → platform funds B%). Separator can be colon, hyphen, en-dash, or "/".
  // The "co-fund" keyword may come before OR after the ratio.
  let m=t.match(/(\d{1,3})\s*[:\-–\/]\s*(\d{1,3})\s*(?:co[\s\-]?fund(?:ing|ed)?|cofund(?:ing|ed)?)/)
       ||t.match(/(?:co[\s\-]?fund(?:ing|ed)?|cofund(?:ing|ed)?)\s*(?:by\s+\S+\s+)?(\d{1,3})\s*[:\-–\/]\s*(\d{1,3})/);
  if(result.coFundedPctOfDiscount==null&&m){const platformPct=parseInt(m[2],10);if(platformPct>=0&&platformPct<=100){result.coFundedPctOfDiscount=platformPct/100;result.hasInfo=true;}}
  // Single percentage near "co-fund"
  if(result.coFundedPctOfDiscount==null){
    m=t.match(/(\d{1,3})\s*%\s*(?:co[\s\-]?funded|co[\s\-]?funding|cofunded)/)||t.match(/(?:co[\s\-]?funded|co[\s\-]?funding|cofunded)\s*(?:by\s+\S+\s+)?(?:at\s+)?(\d{1,3})\s*%/);
    if(m){const pct=parseInt(m[1],10);if(pct>0&&pct<=100){result.coFundedPctOfDiscount=pct/100;result.hasInfo=true;}}
  }
  return result;
}

// ── EFFECTIVE OUTLET SCOPE ──
// Combines the campaign's outlet field with branch-list refinements from comments.
// outlet="DXB" + comment "Except DMC, Motorcity" → DXB branches MINUS those two.
// outlet="All" + comment "Only in Marina, DSO"   → just Marina + DSO.
// outlet="Select Locations" + comment "Locations Except: ..."  → all brand branches MINUS those.
function campOutlets(c){
  const raw=(c.outlet||"").trim();
  const rawLower=raw.toLowerCase();
  const brandBranches=[...new Set(allData.filter(r=>c.brand==="All Brands"||r.brand===c.brand).map(r=>r.branch))].filter(b=>b!=="(brand-level)");
  // Detect exclusion pattern in the outlet field itself: "All Locations Except Jumeirah",
  // "All branches except Al Reef", "All except AUH", etc. Previously the leading "all" made
  // this match isAllField and Jumeirah-only campaigns were never actually excluded, causing
  // false-positive overlap detection with the true Jumeirah-only campaign on the same brand+
  // aggregator (e.g. Smokeys × Talabat July had "Super Saver" on Jumeirah + "World Cup Deals"
  // on "All Locations Except Jumeirah" — both were treated as covering Jumeirah, both got 0
  // attribution, no ROI shown).
  const exceptMatch=rawLower.match(/^all[\s\w]*?\bexcept\b\s+(.+)$/i);
  if(exceptMatch){
    const exclusionText=exceptMatch[1].replace(/\b(only|outlets?|locations?|branches?|stores?)\b/gi,"").trim();
    const exclusionTokens=exclusionText.split(/[,;+/&]+|\s+and\s+|\s+\+\s+/i).map(t=>t.trim()).filter(Boolean);
    const excluded=new Set();
    exclusionTokens.forEach(tok=>{
      const tl=tok.toLowerCase().trim();
      if(tl==="dxb"||tl==="dubai"){brandBranches.forEach(b=>{if(!AUH_OUTLETS.has(b))excluded.add(b);});return;}
      if(tl==="auh"||tl==="abudhabi"||tl==="abu dhabi"){brandBranches.forEach(b=>{if(AUH_OUTLETS.has(b))excluded.add(b);});return;}
      const r=resolveBranchName(tok,brandBranches);
      if(r)excluded.add(r);
    });
    if(excluded.size){
      const result=new Set(brandBranches.filter(b=>!excluded.has(b)));
      return result.size?result:null;
    }
  }
  // Step 1: resolve the outlet field into an initial set (or null = all)
  let base=null;
  const isAllField=!raw||/^all\b/i.test(raw)||raw==="—"||raw==="-"||/^select\s+locations?/i.test(raw)||/^specific\s+locations?/i.test(raw)||/^selected\s+(branches?|outlets?)/i.test(raw);
  if(isAllField){base=null;}
  else{
    const tokens=raw.split(/[,;+/&]+|\s+and\s+|\s+\+\s+/i).map(t=>t.trim()).filter(Boolean);
    base=new Set();
    tokens.forEach(tok=>{
      // Normalize: drop trailing qualifier words so "AUH Locations only", "Abu Dhabi outlets",
      // "DXB branches only" all reduce to the bare region keyword.
      const tl=tok.toLowerCase().replace(/\b(only|outlets?|locations?|branches?|stores?|all)\b/g,"").replace(/\s+/g," ").trim();
      if(!tl)return;
      if(tl==="dxb"||tl==="dubai"){brandBranches.forEach(b=>{if(!AUH_OUTLETS.has(b))base.add(b);});return;}
      if(tl==="auh"||tl==="abudhabi"||tl==="abu dhabi"){brandBranches.forEach(b=>{if(AUH_OUTLETS.has(b))base.add(b);});return;}
      const r=resolveBranchName(tok,brandBranches);
      if(r)base.add(r);
    });
    if(!base.size)base=null;
  }
  // Step 2: apply comment refinements
  const parsed=parseCampComment(c);
  // Region restriction from the comment (e.g. "valid only in AUH") — intersect with base or apply directly.
  if(parsed.regionOnly){
    const regionSet=new Set(brandBranches.filter(b=>parsed.regionOnly==="auh"?AUH_OUTLETS.has(b):!AUH_OUTLETS.has(b)));
    if(base){const inter=new Set([...base].filter(b=>regionSet.has(b)));return inter.size?inter:regionSet;}
    return regionSet.size?regionSet:base;
  }
  if(parsed.includeBranches&&parsed.includeBranches.size){
    // Comments restrict to a specific list — that becomes the scope
    return parsed.includeBranches;
  }
  if(parsed.excludeBranches&&parsed.excludeBranches.size){
    // Start from base (or all brand branches if outlet was unrestricted) and subtract exclusions
    const start=base?new Set(base):new Set(brandBranches);
    parsed.excludeBranches.forEach(b=>start.delete(b));
    return start.size?start:null;
  }
  return base;
}
// Build a "Scope label" for display, e.g. "Dubai outlets (DXB) — 4 branches" or "All outlets"
function campScopeLabel(c){
  const set=campOutlets(c);
  const raw=(c.outlet||"").trim();
  if(!set)return"All outlets";
  const list=[...set].sort();
  const parsed=parseCampComment(c);
  // Region restriction from comment
  if(parsed.regionOnly==="auh")return `🏛️ Abu Dhabi outlets only — ${set.size} branch${set.size!==1?'es':''}: ${list.join(", ")}`;
  if(parsed.regionOnly==="dxb")return `🏙️ Dubai outlets only — ${set.size} branch${set.size!==1?'es':''}: ${list.join(", ")}`;
  if(parsed.excludeBranches&&parsed.excludeBranches.size){
    const excluded=[...parsed.excludeBranches].sort();
    return `📍 ${list.length} branch${list.length!==1?'es':''} (all except ${excluded.join(", ")}): ${list.join(", ")}`;
  }
  // Comment-derived inclusion → describe as "only at"
  if(parsed.includeBranches&&parsed.includeBranches.size){
    return `📍 Only at ${list.length} branch${list.length!==1?'es':''}: ${list.join(", ")}`;
  }
  // Region labels
  if(/^(dxb|dubai)/i.test(raw)){return `🏙️ Dubai outlets only — ${set.size} branch${set.size!==1?'es':''}: ${list.join(", ")}`;}
  if(/^(auh|abu\s?dhabi)/i.test(raw)){return `🏛️ Abu Dhabi outlets only — ${set.size} branch${set.size!==1?'es':''}: ${list.join(", ")}`;}
  return `📍 ${raw} — ${set.size} branch${set.size!==1?'es':''}: ${list.join(", ")}`;
}

function campImpact(c){
  const days=Math.max(1,Math.round((new Date(c.endDate)-new Date(c.startDate))/86400000)+1);
  const baseEnd=subDays(c.startDate,1),baseStart=subDays(baseEnd,days-1);
  const outletSet=campOutlets(c);
  const flt=r=>{if(c.brand!=='All Brands'&&r.brand!==c.brand)return false;if(c.aggregator&&c.aggregator!=='All'&&r.aggregator!==c.aggregator)return false;if(outletSet&&!outletSet.has(r.branch))return false;return true;};
  const cR=allData.filter(r=>r.date>=c.startDate&&r.date<=c.endDate&&flt(r));
  const bR=allData.filter(r=>r.date>=baseStart&&r.date<=baseEnd&&flt(r));
  const cD=new Set(cR.map(r=>r.date)).size||1,bD=new Set(bR.map(r=>r.date)).size||1;
  const cs=sumR(cR),bs=sumR(bR);
  return{campOrders:cs.orders,campSales:cs.sales,campAOV:cs.orders>0?cs.sales/cs.orders:0,baseOrders:bs.orders,baseSales:bs.sales,baseAOV:bs.orders>0?bs.sales/bs.orders:0,ordersLift:pctOf(cs.orders/cD,bs.orders/bD),salesLift:pctOf(cs.sales/cD,bs.sales/bD),aovChange:cs.orders>0&&bs.orders>0?pctOf(cs.sales/cs.orders,bs.sales/bs.orders):null,days,baseStart,baseEnd,hasData:cs.orders>0||cs.sales>0,outletSet};
}
function selectCamp(idx){selCamp=campaignData[idx];selBundle=null;if(campTab!=='detail')campReturnTab=campTab;campTab='detail';renderCampaigns();}
let selBundle=null;
// Decode "bundle:1,4,7" → list of campaign indices, look them up, build the bundle, select it.
function selectBundleByKey(key){
  const idxs=key.replace(/^bundle:/,'').split(',').map(n=>parseInt(n,10)).filter(n=>!isNaN(n));
  const camps=idxs.map(i=>campaignData[i]).filter(Boolean);
  if(!camps.length)return;
  const start=camps.reduce((m,c)=>c.startDate<m?c.startDate:m,camps[0].startDate);
  const end=camps.reduce((m,c)=>c.endDate>m?c.endDate:m,camps[0].endDate);
  const exc=detectExclusion(camps);
  selBundle={
    isBundle:true,brand:camps[0].brand,aggregator:camps[0].aggregator,
    startDate:start,endDate:end,
    outlet:camps.every(c=>c.outlet===camps[0].outlet)?camps[0].outlet:"Mixed",
    campaigns:camps,
    exclusive:exc.exclusive,
    pausedByExclusive:exc.paused,
    name:`🎯 ${camps[0].brand} ${camps[0].aggregator} Bundle (${camps.length} segments)`,
    comments:camps.map(c=>c.name||c.comments||"").filter(Boolean).join(" + ")
  };
  selCamp=null;campTab='detail';renderCampaigns();
}
function fmtCampDate(key){if(!key)return"";const d=new Date(key+"T12:00:00");const dn=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'],mn=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];return `${dn[d.getDay()]} ${d.getDate()} ${mn[d.getMonth()]}`;}
function fmtCampDateRange(s,e){if(s===e)return fmtCampDate(s);return `${fmtCampDate(s)} → ${fmtCampDate(e)}`;}
function campImpactExtended(c){
  const base=campImpact(c);
  if(!base.hasData)return{...base,wowOrdersLift:null,wowSalesLift:null,momOrdersLift:null,momSalesLift:null,contributionDiff:null,profitability:null};
  const days=base.days;
  const wowEnd=subDays(c.startDate,1),wowStart=subDays(wowEnd,days-1);
  const momEnd=subDays(c.startDate,1),momStart=subDays(momEnd,29);
  const flt=r=>{if(c.brand!=='All Brands'&&r.brand!==c.brand)return false;if(c.aggregator&&c.aggregator!=='All'&&r.aggregator!==c.aggregator)return false;if(base.outletSet&&!base.outletSet.has(r.branch))return false;return true;};
  const cR=allData.filter(r=>r.date>=c.startDate&&r.date<=c.endDate&&flt(r));const cs=sumR(cR);const cDays=new Set(cR.map(r=>r.date)).size||1;
  const wR=allData.filter(r=>r.date>=wowStart&&r.date<=wowEnd&&flt(r));const ws=sumR(wR);const wDays=new Set(wR.map(r=>r.date)).size||1;
  const wowOrdersLift=pctOf(cs.orders/cDays,ws.orders/wDays),wowSalesLift=pctOf(cs.sales/cDays,ws.sales/wDays);
  const mR=allData.filter(r=>r.date>=momStart&&r.date<=momEnd&&flt(r));const ms=sumR(mR);const mDays=new Set(mR.map(r=>r.date)).size||1;
  const momOrdersLift=pctOf(cs.orders/cDays,ms.orders/mDays),momSalesLift=pctOf(cs.sales/cDays,ms.sales/mDays);
  const m=(c.comments||'').match(/(\d{1,2})\s*%/);const discountRate=m?parseInt(m[1])/100:0;
  const commData=COMM[c.aggregator]?.[c.brand]||COMM[c.aggregator]?.DEFAULT;
  // CPC/ads spend and cancellation are excluded from the commission cost (they're not per-order
  // commission). For Keeta, the rate steps up in 2027, so resolve it against the campaign's date.
  let baseComm=commData?.commission||0;
  if(c.aggregator==='Keeta')baseComm=keetaCommissionFor(c.startDate);
  const commRate=commData?baseComm+(commData.pg||0)+(commData.processingFee||0)+(commData.cancellation||0):0.30;
  const baseCMRate=1-commRate,campCMRate=1-commRate-discountRate;
  const baseDailyContribution=(base.baseSales/Math.max(1,Math.round((new Date(base.baseEnd)-new Date(base.baseStart))/86400000)+1))*baseCMRate;
  const campDailyContribution=(cs.sales/cDays)*campCMRate;
  const contributionDiff=campDailyContribution-baseDailyContribution;
  const profitability=baseDailyContribution>0?(contributionDiff/baseDailyContribution)*100:null;
  return{...base,wowOrdersLift,wowSalesLift,momOrdersLift,momSalesLift,contributionDiff,profitability,discountRate,commRate,campCMRate,baseDailyContribution,campDailyContribution};
}
function campSortBy(col){if(campSort.col===col)campSort.dir*=-1;else{campSort.col=col;campSort.dir=-1;}renderCampaigns();}
function campToggleFilter(type,val){const sets={brand:campFBrands,platform:campFPlatforms,status:campFStatuses,branch:campFBranches};const s=sets[type];if(s.has(val))s.delete(val);else s.add(val);rememberOpenDD();renderCampaigns();restoreOpenDD();}
// Select-all / clear-all for a filter group (e.g. "All Brands"). Adds every available value.
function campSelectAll(type){
  const sets={brand:campFBrands,platform:campFPlatforms,status:campFStatuses};
  const s=sets[type];if(!s)return;
  let all=[];
  if(type==='brand')all=[...new Set(campaignData.map(c=>c.brand))].filter(b=>b!=='All Brands');
  else if(type==='platform')all=[...new Set(campaignData.map(c=>c.aggregator))];
  else if(type==='status')all=['Running','Upcoming','Completed'];
  // If everything is already selected, clear; otherwise select all.
  const allSelected=all.length>0&&all.every(v=>s.has(v));
  s.clear();if(!allSelected)all.forEach(v=>s.add(v));
  rememberOpenDD();renderCampaigns();restoreOpenDD();
}
// Remember which dropdown menu is open so a re-render doesn't close it.
let campOpenDDId=null;
function rememberOpenDD(){const open=document.querySelector('.dd-menu[data-open="1"]');campOpenDDId=open?open.id:null;}
function restoreOpenDD(){if(!campOpenDDId)return;const el=document.getElementById(campOpenDDId);if(el){el.classList.add("open");el.style.display="block";el.setAttribute("data-open","1");}}
function campClearFilters(){campFBrands.clear();campFPlatforms.clear();campFStatuses.clear();campFBranches.clear();renderCampaigns();}
function applyCampFilters(camps){
  const q=campSearchQ.trim().toLowerCase();
  return camps.filter(c=>{
    if(campFBrands.size&&!campFBrands.has(c.brand))return false;
    if(campFPlatforms.size&&!campFPlatforms.has(c.aggregator))return false;
    if(campFStartFrom&&c.startDate<campFStartFrom)return false;
    if(campFStartTo&&c.startDate>campFStartTo)return false;
    if(campFBranches&&campFBranches.size){
      const scope=campOutlets(c);
      if(scope!==null){
        let hit=false;
        for(const b of campFBranches){if(scope.has(b)){hit=true;break;}}
        if(!hit)return false;
      }
    }
    if(q){
      const hay=`${c.name||''} ${c.brand||''} ${c.aggregator||''} ${c.comments||''}`.toLowerCase();
      if(!hay.includes(q))return false;
    }
    if(campQuickFilter!=='all'){
      if(campQuickFilter==='ending'){
        if(campStatus(c)!=='Running')return false;
        const h=(new Date(c.endDate+"T23:59:59")-new Date())/3600000;
        if(!(h>0&&h<=72))return false;
      }else{
        try{
          const a=campAnalysisCached(c);
          if(!a.hasData)return false;
          const roi=a.discountROI;
          if(campQuickFilter==='winning'&&!(roi!=null&&roi>=1))return false;
          if(campQuickFilter==='losing'&&!(roi!=null&&roi<1))return false;
        }catch(e){return false;}
      }
    }
    return true;
  });
}
function campSetSearch(v){campSearchQ=v;renderCampaigns();}
function campSetQuickFilter(f){campQuickFilter=campQuickFilter===f?'all':f;renderCampaigns();}
function campSetCardSort(v){campCardSort=v;renderCampaigns();}
function sortCampCards(camps){
  const withData=[],noData=[];
  for(const c of camps){
    try{const a=campAnalysisCached(c);(a&&a.hasData?withData:noData).push(c);}
    catch(e){noData.push(c);}
  }
  const key=campCardSort;
  withData.sort((x,y)=>{
    const ax=campAnalysisCached(x),ay=campAnalysisCached(y);
    if(key==='contribution')return (ay.incrContribTotal||0)-(ax.incrContribTotal||0);
    if(key==='roi')return (ay.discountROI??-999)-(ax.discountROI??-999);
    if(key==='end')return (x.endDate||'').localeCompare(y.endDate||'');
    if(key==='lift')return (ay.ordersLift??-999)-(ax.ordersLift??-999);
    return 0;
  });
  return [...withData,...noData];
}
function campSetDate(which,val){if(which==="from")campFStartFrom=val;else campFStartTo=val;renderCampaigns();}
function campClearDates(){campFStartFrom="";campFStartTo="";renderCampaigns();}
function sortCampaigns(camps){
  const{col,dir}=campSort;
  return[...camps].sort((a,b)=>{
    let va,vb;
    if(col==='startDate'){va=a.startDate;vb=b.startDate;}
    else if(col==='name'){va=a.name||'';vb=b.name||'';}
    else if(col==='brand'){va=a.brand;vb=b.brand;}
    else if(col==='platform'){va=a.aggregator;vb=b.aggregator;}
    else if(col==='ordersLift'){const ia=campImpact(a),ib=campImpact(b);va=ia.hasData?ia.ordersLift:-999;vb=ib.hasData?ib.ordersLift:-999;}
    else if(col==='salesLift'){const ia=campImpact(a),ib=campImpact(b);va=ia.hasData?ia.salesLift:-999;vb=ib.hasData?ib.salesLift:-999;}
    else if(col==='momLift'){const ia=campImpactExtended(a),ib=campImpactExtended(b);va=ia.momSalesLift!=null?ia.momSalesLift:-999;vb=ib.momSalesLift!=null?ib.momSalesLift:-999;}
    else if(col==='profitability'){const ia=campImpactExtended(a),ib=campImpactExtended(b);va=ia.profitability!=null?ia.profitability:-9999;vb=ib.profitability!=null?ib.profitability:-9999;}
    else{va=a[col];vb=b[col];}
    if(typeof va==='string')return dir*va.localeCompare(vb);
    return dir*((va||0)-(vb||0));
  });
}
