  filtered.forEach(c=>{aggTallyForTile[c.aggregator]=(aggTallyForTile[c.aggregator]||0)+1;});
  const topAggEntry=Object.entries(aggTallyForTile).sort((a,b)=>b[1]-a[1])[0];
  const outletTallyForTile={};
